// Glob parsing and matching, implemented from observed gitignore/globset style behaviour.
use regex::bytes::{Regex, RegexBuilder};

#[derive(Debug, Clone)]
pub struct Glob {
    pub original: String,
    pub regex: Regex,
    pub literal_separator: bool, // true if pattern should be treated as anchored with / semantics? internal
}

#[derive(Debug, Clone)]
pub struct GlobError(pub String);

fn is_regex_special(b: u8) -> bool {
    matches!(b, b'.' | b'+' | b'(' | b')' | b'|' | b'^' | b'$' | b'#' )
}

// Expand {a,b} alternatives. Nested alternates are rejected before this is called.
// Empty alternatives are permitted by the observed implementation (they simply expand).
pub fn expand_braces(pat: &str) -> Result<Vec<String>, GlobError> {
    // Validation performed in validate_glob; here expand first-level groups recursively.
    let bytes = pat.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => { i += 2; continue; }
            b'[' => {
                // skip char class
                i += 1;
                if i < bytes.len() && (bytes[i] == b'!' || bytes[i] == b'^') { i += 1; }
                if i < bytes.len() && bytes[i] == b']' { i += 1; }
                while i < bytes.len() && bytes[i] != b']' {
                    if bytes[i] == b'\\' { i += 1; }
                    i += 1;
                }
                i += 1; continue;
            }
            b'{' => {
                let start = i;
                let mut j = i + 1;
                let mut depth = 0;
                let mut parts = Vec::new();
                let mut last = j;
                let mut found = false;
                while j < bytes.len() {
                    match bytes[j] {
                        b'\\' => { j += 2; continue; }
                        b'{' => { depth += 1; }
                        b'}' => {
                            if depth == 0 {
                                parts.push(&pat[last..j]);
                                found = true;
                                break;
                            } else { depth -= 1; }
                        }
                        b',' if depth == 0 => { parts.push(&pat[last..j]); last = j + 1; }
                        _ => {}
                    }
                    j += 1;
                }
                if !found {
                    return Err(GlobError(format!("unclosed alternate group; missing '}}' (maybe escape '{{' with '[{{]'?)")));
                }
                let prefix = &pat[..start];
                let suffix = &pat[j+1..];
                let mut out = Vec::new();
                for part in parts {
                    let combined = format!("{}{}{}", prefix, part, suffix);
                    out.extend(expand_braces(&combined)?);
                }
                return Ok(out);
            }
            _ => { i += 1; }
        }
    }
    Ok(vec![pat.to_string()])
}

pub fn validate_glob(pat: &str) -> Result<(), GlobError> {
    let b = pat.as_bytes();
    let mut i = 0usize;
    while i < b.len() {
        match b[i] {
            b'\\' => {
                if i + 1 >= b.len() {
                    return Err(GlobError("dangling '\\'".to_string()));
                }
                i += 2;
            }
            b'[' => {
                // find closing ]
                let start = i;
                i += 1;
                if i < b.len() && (b[i] == b'!' || b[i] == b'^') { i += 1; }
                // A ] immediately after [ or [! is literal in some dialects, but observed rg treats [] and [^] as unclosed.
                let mut closed = false;
                let mut prev: Option<u8> = None;
                let mut first = true;
                while i < b.len() {
                    if b[i] == b'\\' {
                        if i + 1 >= b.len() { return Err(GlobError("dangling '\\'".to_string())); }
                        prev = Some(b[i+1]);
                        i += 2;
                        first = false;
                        continue;
                    }
                    if b[i] == b']' && !first {
                        closed = true; i += 1; break;
                    }
                    // POSIX class [:name:]
                    if b[i] == b'[' && i + 1 < b.len() && b[i+1] == b':' {
                        if let Some(end) = pat[i+2..].find(":]") {
                            i = i + 2 + end + 2;
                            prev = None; first = false; continue;
                        }
                    }
                    if b[i] == b'-' && !first {
                        // range check needs next char not ]
                        if let Some(p) = prev {
                            if i + 1 < b.len() && b[i+1] != b']' {
                                let nxt = b[i+1];
                                if p > nxt {
                                    return Err(GlobError(format!("invalid range; '{}' > '{}'", p as char, nxt as char)));
                                }
                            }
                        }
                    }
                    if !(b[i] == b']' && first) {
                        prev = Some(b[i]);
                    }
                    first = false;
                    i += 1;
                }
                if !closed {
                    return Err(GlobError("unclosed character class; missing ']'".to_string()));
                }
                let _ = start;
            }
            b'{' => {
                // check nested and closed
                let mut j = i + 1;
                let mut closed = false;
                while j < b.len() {
                    match b[j] {
                        b'\\' => { j += 2; continue; }
                        b'{' => { return Err(GlobError("nested alternate groups are not allowed".to_string())); }
                        b'}' => { closed = true; break; }
                        b'[' => {
                            // skip class inside braces to avoid mistaking { in class
                            // minimal skip
                            j += 1;
                            while j < b.len() && b[j] != b']' { j += 1; }
                        }
                        _ => {}
                    }
                    j += 1;
                }
                if !closed {
                    return Err(GlobError("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)".to_string()));
                }
                i = j + 1;
            }
            _ => { i += 1; }
        }
    }
    Ok(())
}

fn posix_class(name: &str) -> Option<&'static str> {
    match name {
        "alnum" => Some("A-Za-z0-9"),
        "alpha" => Some("A-Za-z"),
        "ascii" => Some("\\x00-\\x7F"),
        "blank" => Some(" \\t"),
        "cntrl" => Some("\\x00-\\x1F\\x7F"),
        "digit" => Some("0-9"),
        "graph" => Some("!-~"),
        "lower" => Some("a-z"),
        "print" => Some(" -~"),
        "punct" => Some("!-/:-@\\[-`{-~"),
        "space" => Some("\\s"),
        "upper" => Some("A-Z"),
        "word" => Some("A-Za-z0-9_"),
        "xdigit" => Some("A-Fa-f0-9"),
        _ => None,
    }
}

// Translate a single expanded glob (no braces) to a regex string (bytes).
// If anchored is false (gitignore non-anchored pattern semantics are handled by caller),
// this function expects caller to have prepared the effective pattern:
//   - For gitignore: patterns are transformed before calling (see gitignore_to_regex).
// Here we implement full-path glob translation where:
//   *  does not cross /
//   ?  does not cross /
//   ** as a path component matches across /
//   ** elsewhere behaves like *
//   [...] char classes, \ escapes.
pub fn glob_to_regex_str(pat: &str) -> Result<String, GlobError> {
    validate_glob(pat)?;
    let b = pat.as_bytes();
    let mut out = String::from("(?s:");
    let mut i = 0usize;
    while i < b.len() {
        match b[i] {
            b'*' => {
                // count stars
                let mut j = i;
                while j < b.len() && b[j] == b'*' { j += 1; }
                let star_count = j - i;
                let before_slash = i == 0 || b[i-1] == b'/';
                let after_slash = j >= b.len() || b[j] == b'/';
                if star_count >= 2 && before_slash && after_slash {
                    if j >= b.len() {
                        // trailing ** matches everything (including empty)
                        out.push_str(".*");
                    } else {
                        // **/ matches zero or more directories
                        out.push_str("(?:.*/)?");
                        j += 1; // consume slash
                    }
                } else {
                    out.push_str("[^/]*");
                }
                i = j;
            }
            b'?' => { out.push_str("[^/]"); i += 1; }
            b'[' => {
                // copy class, translating posix classes and negation
                let mut j = i + 1;
                let neg = if j < b.len() && (b[j] == b'!' || b[j] == b'^') { j += 1; true } else { false };
                // find end
                let mut content_start = j;
                let mut first = true;
                let mut class_body = String::new();
                // handle initial ] as ??? globset treats [] as unclosed already validated
                while j < b.len() {
                    if b[j] == b'\\' && j + 1 < b.len() {
                        // escaped char in class
                        let ch = b[j+1] as char;
                        if matches!(ch, ']' | '\\' | '^' | '-' ) {
                            class_body.push('\\');
                            class_body.push(ch);
                        } else {
                            class_body.push(ch);
                        }
                        j += 2; first = false; content_start = j; continue;
                    }
                    if b[j] == b'[' && j + 1 < b.len() && b[j+1] == b':' {
                        if let Some(end_rel) = pat[j+2..].find(":]") {
                            let name = &pat[j+2..j+2+end_rel];
                            if let Some(rep) = posix_class(name) {
                                class_body.push_str(rep);
                            } else {
                                // unknown posix class: treat literally like regex crate would? keep as-is characters
                                class_body.push_str(name);
                            }
                            j = j + 2 + end_rel + 2; first = false; continue;
                        }
                    }
                    if b[j] == b']' && !first { break; }
                    // escape regex special inside class except - and ]
                    let ch = b[j] as char;
                    if matches!(ch, '\\') { class_body.push('\\'); class_body.push(ch); } else { class_body.push(ch); }
                    j += 1; first = false;
                }
                out.push('[');
                if neg { out.push('^'); }
                out.push_str(&class_body);
                out.push(']');
                i = j + 1;
                let _ = content_start;
            }
            b'\\' => {
                if i + 1 >= b.len() { return Err(GlobError("dangling '\\'".to_string())); }
                let ch = b[i+1] as char;
                // escape regex metachars
                if is_regex_special(b[i+1]) || matches!(ch, '*' | '?' | '[' | ']' | '{' | '}' | '\\') {
                    out.push('\\');
                }
                out.push(ch);
                i += 2;
            }
