    let mut out = String::from("(?s:");
    let mut i = 0usize;
    while i < b.len() {
        match b[i] {
            b'*' => {
                // count stars
                let mut j = i;
                while j < b.len() && b[j] == b'*' { j += 1; }
                let star_count = j - i;
                let before_slash = i == 0 || b[i-1] == b'/';
                let after_slash = j >= b.len() || b[j] == b'/';
                if star_count >= 2 && before_slash && after_slash {
                    if j >= b.len() {
                        // trailing ** matches everything (including empty)
                        out.push_str(".*");
                    } else {
                        // **/ matches zero or more directories
                        out.push_str("(?:.*/)?");
                        j += 1; // consume slash
                    }
                } else {
                    out.push_str("[^/]*");
                }
                i = j;
            }
            b'?' => { out.push_str("[^/]"); i += 1; }
            b'[' => {
                // copy class, translating posix classes and negation
                let mut j = i + 1;
                let neg = if j < b.len() && (b[j] == b'!' || b[j] == b'^') { j += 1; true } else { false };
                // find end
                let mut content_start = j;
                let mut first = true;
                let mut class_body = String::new();
                // handle initial ] as ??? globset treats [] as unclosed already validated
                while j < b.len() {
                    if b[j] == b'\\' && j + 1 < b.len() {
                        // escaped char in class
                        let ch = b[j+1] as char;
                        if matches!(ch, ']' | '\\' | '^' | '-' ) {
                            class_body.push('\\');
                            class_body.push(ch);
                        } else {
                            class_body.push(ch);
                        }
                        j += 2; first = false; content_start = j; continue;
                    }
                    if b[j] == b'[' && j + 1 < b.len() && b[j+1] == b':' {
                        if let Some(end_rel) = pat[j+2..].find(":]") {
                            let name = &pat[j+2..j+2+end_rel];
                            if let Some(rep) = posix_class(name) {
                                class_body.push_str(rep);
                            } else {
                                // unknown posix class: treat literally like regex crate would? keep as-is characters
                                class_body.push_str(name);
                            }
                            j = j + 2 + end_rel + 2; first = false; continue;
                        }
                    }
                    if b[j] == b']' && !first { break; }
                    // escape regex special inside class except - and ]
                    let ch = b[j] as char;
                    if matches!(ch, '\\') { class_body.push('\\'); class_body.push(ch); } else { class_body.push(ch); }
                    j += 1; first = false;
                }
                out.push('[');
                if neg { out.push('^'); }
                out.push_str(&class_body);
                out.push(']');
                i = j + 1;
                let _ = content_start;
            }
            b'\\' => {
                if i + 1 >= b.len() { return Err(GlobError("dangling '\\'".to_string())); }
                let ch = b[i+1] as char;
                // escape regex metachars
                if is_regex_special(b[i+1]) || matches!(ch, '*' | '?' | '[' | ']' | '{' | '}' | '\\') {
                    out.push('\\');
                }
                out.push(ch);
                i += 2;
            }
            b'.' | b'+' | b'(' | b')' | b'|' | b'^' | b'$' | b'#' | b'{' | b'}' => {
                out.push('\\'); out.push(b[i] as char); i += 1;
            }
            _ => {
                // push as byte-char; pattern strings are UTF-8, pushing char is fine for ASCII.
                // For non-ASCII, need to push whole char.
                let s = &pat[i..];
                let ch = s.chars().next().unwrap();
                out.push(ch);
                i += ch.len_utf8();
            }
        }
    }
    out.push(')');
    Ok(out)
}

pub fn build_glob(pat: &str, case_insensitive: bool) -> Result<Glob, GlobError> {
    validate_glob(pat).map_err(|e| e)?;
    let expanded = expand_braces(pat)?;
    let mut regex_parts = Vec::new();
    for ex in &expanded {
        regex_parts.push(glob_to_regex_str(ex)?);
    }
    let regex_str = if regex_parts.len() == 1 {
        format!("^{}$", regex_parts[0])
    } else {
        format!("^(?:{})$", regex_parts.join("|"))
    };
    let re = RegexBuilder::new(&regex_str)
        .case_insensitive(case_insensitive)
        .unicode(false)
        .build()
        .map_err(|e| GlobError(e.to_string()))?;
    Ok(Glob { original: pat.to_string(), regex: re, literal_separator: pat.contains('/') })
}

impl Glob {
    pub fn is_match(&self, text: &[u8]) -> bool {
        self.regex.is_match(text)
    }
}

// Gitignore style pattern conversion:
// Returns a Glob that matches a relative path (using / separators) given to is_match.
// Semantics:
// - If pattern contains a slash (other than trailing), it is anchored to base: match entire relative path.
// - If no slash, it matches basename of path (any component? Actually for files: basename; for matching directories during traversal: component name)
// - Leading / is stripped and anchors.
// - Trailing / handled by caller (dir_only).
// - ** etc as above.
pub fn build_gitignore_glob(pat: &str, case_insensitive: bool) -> Result<Glob, GlobError> {
    // Caller should have stripped leading ! and trailing / etc, but keep leading / info.
    let mut anchored = false;
    let mut p = pat.to_string();
    if p.starts_with('/') {
        anchored = true;
        p = p[1..].to_string();
    }
    if p.contains('/') {
        anchored = true;
    }
    if !anchored {
        // match basename: pattern matches final component
        // We convert to **/pat equivalent but need to handle pat containing **? No slash means single component glob.
        let full = format!("**/{}", p);
        // Special case: build via expanded handling: we need regex ^(?:.*/)?pat$
        // Use build_glob on full with special ** handling: glob **/ at start should give (?:.*/)? 
        return build_glob(&full, case_insensitive);
    } else {
        return build_glob(&p, case_insensitive);
    }
}

// For override -g globs: semantics are same as gitignore (per docs), except leading ! is blacklist.
// But also behaviour: a glob like "*.txt" matches basename anywhere, "sub/*.txt" anchored, "/a.txt" anchored to cwd/root?
// In override matching, paths are matched relative to cwd (for search root?) Actually override matcher matches against path as given / relative to cwd.
// We'll use gitignore-style building.
pub fn build_override_glob(pat: &str, case_insensitive: bool) -> Result<Glob, GlobError> {
    build_gitignore_glob(pat, case_insensitive)
}
