        "unrestricted" => {
            args.unrestricted += 1;
            match args.unrestricted { 1 => { apply_switch(args, "no-ignore"); }, 2 => { apply_switch(args, "no-ignore"); args.hidden = true; }, _ => { apply_switch(args, "no-ignore"); args.hidden = true; args.binary_mode = BinaryMode::Binary; } }
        }
        "block-buffered" => { args.block_buffered = true; args.line_buffered = false; }
