        "no-heading" => args.heading = Some(false),
        "include-zero" => args.include_zero = true,
        "no-include-zero" => args.include_zero = false,
        "line-buffered" => { args.line_buffered = true; args.block_buffered = false; }
        "no-line-buffered" => args.line_buffered = false,
        "line-number" => args.line_number = Some(true),
        "no-line-number" => args.line_number = Some(false),
        "max-columns-preview" => args.max_columns_preview = true,
        "no-max-columns-preview" => args.max_columns_preview = false,
        "null"|"print0" => args.null = true,
        "only-matching" => args.only_matching = true,
        "passthru"|"passthrough" => args.passthru = true,
        "pretty" => { args.color_when = "ansi".to_string(); args.heading = Some(true); args.line_number = Some(true); }
        "quiet" => args.quiet = true,
        "trim" => args.trim = true,
        "no-trim" => args.trim = false,
        "vimgrep" => args.vimgrep = true,
        "with-filename" => args.with_filename = Some(true),
        "no-filename" => args.with_filename = Some(false),
        "sort-files" => { args.sort = Some(("path".to_string(), false)); }
        "no-sort-files" => { if args.sort.as_ref().map(|(k,_)| k=="path") == Some(true) { /* keep? original deprecated negation sets sort to none */ } args.sort = Some(("none".to_string(), false)); }
        "debug" => { args.debug = true; }
        "trace" => { args.trace = true; args.debug = true; }
        "no-ignore-messages" => args.no_ignore_messages = true,
        "ignore-messages" => args.no_ignore_messages = false,
        "no-messages" => args.no_messages = true,
        "messages" => args.no_messages = false,
        "stats" => args.stats = true,
        "no-stats" => args.stats = false,
        "no-config" => args.no_config = true,
        "no-encoding" => args.encoding = Encoding::Auto,
        "no-pre" => args.pre = None,
        "no-context-separator" => args.context_separator = None,
        _ => {}
    }
}

fn apply_value(args: &mut Args, id: &str, display: &str, raw_value: OsString, is_path_value: bool) -> Result<(), FlagError> {
    // path values keep OsString
    if is_path_value {
        let path = PathBuf::from(raw_value);
        match id {
            "file" => { args.has_pattern_flags = true; args.pattern_sources.push(PatternSource::File(path)); }
            "ignore-file" => args.ignore_files_custom.push(path),
            "pre" => args.pre = Some(path),
            "hostname-bin" => args.hostname_bin = Some(path),
            _ => unreachable!(),
        }
        return Ok(());
    }
    let v = match raw_value.to_str() {
        Some(s) => s.to_string(),
        None => return Err(FlagError(format!("rg: error parsing flag {}: value is not valid UTF-8\n", display))),
    };
    match id {
        "regexp" => { args.has_pattern_flags = true; args.pattern_sources.push(PatternSource::Regexp(v)); }
        "pre-glob" => args.pre_globs.push(v),
        "dfa-size-limit" => args.dfa_size_limit = Some(parse_size(display, &v)? as usize),
        "regex-size-limit" => args.regex_size_limit = Some(parse_size(display, &v)? as usize),
        "encoding" => {
            if v == "none" { args.encoding = Encoding::None; }
            else if v == "auto" { args.encoding = Encoding::Auto; }
            else if crate::encoding::is_valid_encoding_label(&v) { args.encoding = Encoding::Label(v); }
            else { return Err(FlagError(format!("rg: error parsing flag {}: grep config error: unknown encoding: {}\n", display, v))); }
        }
        "engine" => {
            match v.as_str() { "default" => args.engine = Engine::Default, "pcre2" => args.engine = Engine::Pcre2, "auto" => args.engine = Engine::Auto, _ => return Err(FlagError(format!("rg: error parsing flag {}: unrecognized regex engine '{}'\n", display, v))) }
        }
        "max-count" => args.max_count = Some(parse_number(display, &v)?),
        "threads" => args.threads = parse_number(display, &v)?,
        "glob" => args.globs.push(v),
        "iglob" => args.iglobs.push(v),
        "max-depth" => args.max_depth = Some(parse_number(display, &v)?),
        "max-filesize" => args.max_filesize = Some(parse_size(display, &v)?),
        "type" => args.type_select.push(v),
        "type-not" => args.type_not.push(v),
        "type-add" => args.type_add.push(v),
        "type-clear" => args.type_clear.push(v),
        "after-context" => { args.after_context = Some(parse_number(display, &v)?); args.passthru = false; }
        "before-context" => { args.before_context = Some(parse_number(display, &v)?); args.passthru = false; }
        "context" => { args.context_both = Some(parse_number(display, &v)?); args.passthru = false; }
        "color" => {
            match v.as_str() { "never"|"auto"|"always"|"ansi" => args.color_when = v, _ => return Err(FlagError(format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", display, v))) }
        }
        "colors" => parse_color_value(display, &v, args)?,
        "context-separator" => args.context_separator = Some(String::from_utf8_lossy(&decode_escapes(&v)).into_owned()),
        "field-context-separator" => args.field_context_separator = String::from_utf8_lossy(&decode_escapes(&v)).into_owned(),
        "field-match-separator" => args.field_match_separator = String::from_utf8_lossy(&decode_escapes(&v)).into_owned(),
        "generate" => {
            match v.as_str() { "man"|"complete-bash"|"complete-zsh"|"complete-fish"|"complete-powershell" => args.mode = Mode::Generate(v), _ => return Err(FlagError(format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", display, v))) }
        }
        "hyperlink-format" => { args.hyperlink_format = validate_hyperlink(display, &v)?; args.hyperlink_format_raw = v; }
        "max-columns" => args.max_columns = Some(parse_number(display, &v)?),
        "replace" => args.replace = Some(v),
        "sort" => {
            match v.as_str() { "none"|"path"|"modified"|"accessed"|"created" => args.sort = Some((v,false)), _ => return Err(FlagError(format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", display, v))) }
        }
        "sortr" => {
            match v.as_str() { "none"|"path"|"modified"|"accessed"|"created" => args.sort = Some((v,true)), _ => return Err(FlagError(format!("rg: error parsing flag {}: choice '{}' is unrecognized\n", display, v))) }
        }
        _ => {}
    }
    Ok(())
}

fn is_path_value(id: &str) -> bool { matches!(id, "file"|"ignore-file"|"pre"|"hostname-bin") }

pub fn parse_args(argv: Vec<OsString>) -> Result<Args, FlagError> {
    let mut args = Args::default();
    let mut i = 0usize;
    let mut only_positional = false;
    while i < argv.len() {
        let arg = &argv[i];
        let arg_bytes = {
            #[cfg(unix)] { use std::os::unix::ffi::OsStrExt; arg.as_os_str().as_bytes().to_vec() }
            #[cfg(not(unix))] { arg.to_string_lossy().as_bytes().to_vec() }
        };
        if only_positional {
            args.positionals.push(PathBuf::from(arg.clone())); i += 1; continue;
        }
        if arg_bytes == b"--" {
            only_positional = true; i += 1; continue;
        }
        if arg_bytes.len() >= 2 && arg_bytes[0]==b'-' && arg_bytes[1]==b'-' {
            // long
            let rest = &arg.to_string_lossy()[2..].to_string();
            let (name, attached) = match rest.find('=') {
                Some(pos) => (rest[..pos].to_string(), Some(rest[pos+1..].to_string())),
                None => (rest.clone(), None),
            };
            // lookup
            let def_opt = if name.chars().count()==1 {
                let c = name.chars().next().unwrap();
                if c=='h' || c=='V' {
                    // observed special behaviour for --h / --V: treated as a switch with no search effect
                    Some(FlagDef{id:"__noop_hv", kind:FlagKind::Switch})
                } else {
                    short_def(c)
                }
            } else {
                long_def(&name)
            };
            let def = match def_opt {
                Some(d) => d,
                None => {
                    let mut msg = format!("rg: unrecognized flag --{}\n", name);
                    let sugg = suggestions(&name);
                    if !sugg.is_empty() {
                        msg.push_str(&format!("\nsimilar flags that are available: {}\n", sugg.iter().map(|s| format!("--{}", s)).collect::<Vec<_>>().join(", ")));
                    }
                    return Err(FlagError(msg));
                }
            };
            let display = if name.chars().count()==1 && def.id!="__noop_hv" {
                // short canonical
                // need determine if short_def actually existed; for h/V noop use --h
                if name=="h" || name=="V" { format!("--{}", name) } else { format!("-{}", name) }
            } else { format!("--{}", name) };
            let lexopt_display = format!("--{}", name);
            match def.kind {
                FlagKind::Switch => {
                    if let Some(val) = attached {
                        return Err(FlagError(format!("rg: invalid CLI arguments: unexpected argument for option '{}': \"{}\"\n", lexopt_display, val)));
                    }
                    apply_switch(&mut args, def.id);
                }
                FlagKind::Value => {
                    let value_os: OsString = if let Some(val) = attached {
                        OsString::from(val)
                    } else {
                        i += 1;
                        if i >= argv.len() {
                            return Err(FlagError(format!("rg: missing value for flag {}: missing argument for option '{}'\n", display, lexopt_display)));
                        }
                        argv[i].clone()
                    };
                    apply_value(&mut args, def.id, &display, value_os, is_path_value(def.id))?;
                }
            }
            i += 1; continue;
        }
        if arg_bytes.len() >= 2 && arg_bytes[0]==b'-' && arg_bytes != b"-" {
            // short cluster: work on string lossy characters (flags are ASCII, other chars will be unknown)
            let s = arg.to_string_lossy().to_string();
            let chars: Vec<char> = s[1..].chars().collect();
            let mut idx = 0usize;
            let mut consumed_next = false;
            while idx < chars.len() {
                let c = chars[idx];
                let def = match short_def(c) {
                    Some(d) => d,
                    None => { return Err(FlagError(format!("rg: unrecognized flag -{}\n", c))); }
                };
                let display = format!("-{}", c);
                let lexopt_display = display.clone();
                match def.kind {
                    FlagKind::Switch => { apply_switch(&mut args, def.id); idx += 1; }
                    FlagKind::Value => {
                        // remaining string after c
                        // rebuild remainder from original s: position in bytes - approximate using char indices
                        let remainder: String = chars[idx+1..].iter().collect();
                        let value_os: OsString = if !remainder.is_empty() {
                            let v = remainder.strip_prefix('=').map(|x| x.to_string()).unwrap_or(remainder);
                            OsString::from(v)
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return Err(FlagError(format!("rg: missing value for flag {}: missing argument for option '{}'\n", display, lexopt_display)));
                            }
                            consumed_next = true;
                            argv[i].clone()
                        };
                        apply_value(&mut args, def.id, &display, value_os, is_path_value(def.id))?;
                        idx = chars.len();
                    }
                }
            }
            let _ = consumed_next;
            i += 1; continue;
        }
        // positional (including single "-")
        args.positionals.push(PathBuf::from(arg.clone()));
        i += 1;
    }
    Ok(args)
}
RS
"}

