#[derive(Debug)]
pub struct FlagError(pub String);
impl FlagError { pub fn to_string(&self) -> String { self.0.clone() } }

pub fn err_exit(msg: String) -> FlagError { FlagError(msg) }

pub fn parse_number(display: &str, v: &str) -> Result<u64, FlagError> {
    match v.parse::<u64>() {
        Ok(n) => Ok(n),
        Err(e) => Err(FlagError(format!("rg: error parsing flag {}: value is not a valid number: {}\n", display, e))),
    }
}
pub fn parse_size(display: &str, v: &str) -> Result<u64, FlagError> {
    // format digits + optional K/M/G
    if v.is_empty() {
        return Err(FlagError(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", display, v)));
    }
    let (digits, mult) = if let Some(s) = v.strip_suffix('K') { (s, 1024u64) } else if let Some(s) = v.strip_suffix('M') { (s, 1024u64*1024) } else if let Some(s) = v.strip_suffix('G') { (s, 1024u64*1024*1024) } else { (v, 1u64) };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err(FlagError(format!("rg: error parsing flag {}: invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix\n", display, v)));
    }
    let n: u64 = match digits.parse() {
        Ok(n) => n,
        Err(e) => return Err(FlagError(format!("rg: error parsing flag {}: invalid size: invalid integer found in size '{}': {}\n", display, v, e))),
    };
    match n.checked_mul(mult) {
        Some(x) => Ok(x),
        None => Err(FlagError(format!("rg: error parsing flag {}: invalid size: size too big in '{}'\n", display, v))),
    }
}

pub fn decode_escapes(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'\\' && i + 1 < b.len() {
            match b[i+1] {
                b'n' => { out.push(b'\n'); i += 2; }
                b'r' => { out.push(b'\r'); i += 2; }
                b't' => { out.push(b'\t'); i += 2; }
                b'0' => { out.push(0); i += 2; }
                b'\\' => { out.push(b'\\'); i += 2; }
                b'x' => {
                    if i + 3 < b.len() + 1 && i+2 < b.len() && i+3 < b.len() {
                        let h1 = (b[i+2] as char).to_digit(16);
                        let h2 = (b[i+3] as char).to_digit(16);
                        if let (Some(a), Some(c)) = (h1, h2) {
                            out.push((a*16 + c) as u8); i += 4; continue;
                        }
                    }
                    // not valid hex, keep literally
                    out.push(b'\\'); i += 1;
                }
                _ => { out.push(b'\\'); i += 1; }
            }
        } else {
            out.push(b[i]); i += 1;
        }
    }
    out
}

fn validate_hyperlink(display: &str, v: &str) -> Result<String, FlagError> {
    // returns resolved format
    let aliases: &[(&str,&str)] = &[
        ("default","file://{host}{path}"), ("file","file://{host}{path}"), ("none",""),
        ("grep+","grep+://{path}:{line}"), ("kitty","file://{host}{path}#{line}"),
        ("macvim","mvim://open?url=file://{path}&line={line}&column={column}"),
        ("textmate","txmt://open?url=file://{path}&line={line}&column={column}"),
        ("vscode","vscode://file{path}:{line}:{column}"),
        ("vscode-insiders","vscode-insiders://file{path}:{line}:{column}"),
        ("vscodium","vscodium://file{path}:{line}:{column}"),
    ];
    if v.is_empty() { return Ok(String::new()); }
    for (a, f) in aliases { if v == *a { return Ok(f.to_string()); } }
    // scan variables
    let mut vars: Vec<String> = Vec::new();
    let mut i = 0usize; let bytes = v.as_bytes();
    while i < bytes.len() {
        if bytes[i] == b'{' {
            if let Some(close) = v[i..].find('}') {
                let name = &v[i+1..i+close];
                if !matches!(name, "path"|"line"|"column"|"host"|"wslprefix") {
                    return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: invalid hyperlink format variable: '{}', choose from: path, line, column, host, wslprefix\n", display, name)));
                }
                vars.push(name.to_string());
                i += close + 1;
            } else {
                return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: unclosed variable: found '{{' without a corresponding '}}' following it\n", display)));
            }
        } else if bytes[i] == b'}' {
            return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: unopened variable: found '}}' without a corresponding '{{' preceding it\n", display)));
        } else { i += 1; }
    }
    if !vars.iter().any(|x| x=="path") {
        if vars.is_empty() {
            return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: at least a {{path}} variable is required in a hyperlink format, or otherwise use a valid alias: default, file, grep+, kitty, macvim, none, textmate, vscode, vscode-insiders, vscodium\n", display)));
        } else {
            return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: the {{path}} variable is required in a hyperlink format\n", display)));
        }
    }
    if vars.iter().any(|x| x=="column") && !vars.iter().any(|x| x=="line") {
        return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: the hyperlink format contains a {{column}} variable, but no {{line}} variable is present\n", display)));
    }
    // scheme check: format must start with scheme pattern [0-9A-Za-z+-.]+:
    // Take up to first '{' or ':' 
    // Simpler: find first ':'; preceding chars must all be scheme chars and at least one, and ':' must appear before any '}' etc.
    // And the literal prefix before first variable must contain scheme+colon.
    let first_brace = v.find('{').unwrap_or(v.len());
    let prefix = &v[..first_brace];
    let valid_scheme = {
        if let Some(colon) = prefix.find(':') {
            let scheme = &prefix[..colon];
            !scheme.is_empty() && scheme.bytes().all(|c| c.is_ascii_alphanumeric() || c==b'+'||c==b'-'||c==b'.')
        } else { false }
    };
    if !valid_scheme {
        return Err(FlagError(format!("rg: error parsing flag {}: invalid hyperlink format: the hyperlink format must start with a valid URL scheme, i.e., [0-9A-Za-z+-.]+:\n", display)));
    }
    Ok(v.to_string())
}

fn parse_color_value(display: &str, spec: &str, args: &mut Args) -> Result<(), FlagError> {
    let parts: Vec<&str> = spec.split(':').collect();
    // valid: 2 parts with none, or 3 parts
    let (kind, attr, value_opt) = if parts.len() == 2 {
        if parts[1].eq_ignore_ascii_case("none") {
            (parts[0].to_lowercase(), "none".to_string(), None)
        } else {
            return Err(FlagError(format!("rg: error parsing flag {}: invalid color spec format: '{}'. Valid format is '(path|line|column|match):(fg|bg|style):(value)'.\n", display, spec)));
        }
    } else if parts.len() == 3 {
        (parts[0].to_lowercase(), parts[1].to_lowercase(), Some(parts[2].to_string()))
    } else {
        return Err(FlagError(format!("rg: error parsing flag {}: invalid color spec format: '{}'. Valid format is '(path|line|column|match):(fg|bg|style):(value)'.\n", display, spec)));
    };
    if !matches!(kind.as_str(), "path"|"line"|"column"|"match") {
        return Err(FlagError(format!("rg: error parsing flag {}: unrecognized output type '{}'. Choose from: path, line, column, match.\n", display, parts[0])));
    }
    if !matches!(attr.as_str(), "fg"|"bg"|"style"|"none") {
        return Err(FlagError(format!("rg: error parsing flag {}: unrecognized spec type '{}'. Choose from: fg, bg, style, none.\n", display, parts[1])));
    }
    if attr == "none" {
        args.colors.push(ColorSpecValue{kind, attr, value: String::new()});
        return Ok(());
    }
    let value = value_opt.unwrap();
    if attr == "style" {
        if !matches!(value.to_lowercase().as_str(), "bold"|"nobold"|"intense"|"nointense"|"underline"|"nounderline") {
            return Err(FlagError(format!("rg: error parsing flag {}: unrecognized style attribute '{}'. Choose from: nobold, bold, nointense, intense, nounderline, underline.\n", display, value)));
        }
    } else {
        // fg/bg color validation
        let low = value.to_lowercase();
        let named = ["black","blue","green","red","cyan","magenta","yellow","white"];
        if named.contains(&low.as_str()) {
            // ok
        } else if value.contains(',') {
            // RGB
            let toks: Vec<&str> = value.split(',').collect();
            let mut ok = toks.len()==3;
            if ok {
                for t in &toks {
                    if parse_color_num(t).is_none() { ok=false; }
                }
            }
            if !ok {
                return Err(FlagError(format!("rg: error parsing flag {}: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'\n", display, value)));
            }
        } else if let Some(stripped) = low.strip_prefix("0x") {
            // hex ansi256
            if u8::from_str_radix(stripped, 16).is_err() {
                return Err(FlagError(format!("rg: error parsing flag {}: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n", display, value)));
            }
        } else {
            // ansi256 attempt if all alphanumeric (and not empty)
            if !value.is_empty() && value.bytes().all(|b| b.is_ascii_alphanumeric()) {
                if value.parse::<u8>().is_err() {
                    // also try hex? observed 12a -> ansi256 error, so treat this as ansi error
                    return Err(FlagError(format!("rg: error parsing flag {}: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'\n", display, value)));
                }
            } else {
                return Err(FlagError(format!("rg: error parsing flag {}: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n", display, value)));
            }
        }
    }
    args.colors.push(ColorSpecValue{kind, attr, value});
    Ok(())
}

pub fn parse_color_num(t: &str) -> Option<u8> {
    let low = t.to_lowercase();
    if let Some(hex) = low.strip_prefix("0x") {
        u8::from_str_radix(hex, 16).ok()
    } else {
        t.parse::<u8>().ok()
    }
}

#[derive(Debug, Clone, PartialEq)]
enum FlagKind { Switch, Value }

#[derive(Debug, Clone)]
struct FlagDef { id: &'static str, kind: FlagKind }

fn long_def(name: &str) -> Option<FlagDef> {
    let (id, kind) = match name {
        // value flags
        "regexp" => ("regexp", FlagKind::Value),
        "file" => ("file", FlagKind::Value),
        "pre" => ("pre", FlagKind::Value),
        "pre-glob" => ("pre-glob", FlagKind::Value),
        "dfa-size-limit" => ("dfa-size-limit", FlagKind::Value),
        "encoding" => ("encoding", FlagKind::Value),
        "engine" => ("engine", FlagKind::Value),
        "max-count" => ("max-count", FlagKind::Value),
        "regex-size-limit" => ("regex-size-limit", FlagKind::Value),
        "threads" => ("threads", FlagKind::Value),
        "glob" => ("glob", FlagKind::Value),
        "iglob" => ("iglob", FlagKind::Value),
        "ignore-file" => ("ignore-file", FlagKind::Value),
        "max-depth"|"maxdepth" => ("max-depth", FlagKind::Value),
        "max-filesize" => ("max-filesize", FlagKind::Value),
        "type" => ("type", FlagKind::Value),
        "type-not" => ("type-not", FlagKind::Value),
        "type-add" => ("type-add", FlagKind::Value),
        "type-clear" => ("type-clear", FlagKind::Value),
        "after-context" => ("after-context", FlagKind::Value),
        "before-context" => ("before-context", FlagKind::Value),
        "color" => ("color", FlagKind::Value),
        "colors" => ("colors", FlagKind::Value),
        "context" => ("context", FlagKind::Value),
        "context-separator" => ("context-separator", FlagKind::Value),
        "field-context-separator" => ("field-context-separator", FlagKind::Value),
        "field-match-separator" => ("field-match-separator", FlagKind::Value),
        "generate" => ("generate", FlagKind::Value),
        "hostname-bin" => ("hostname-bin", FlagKind::Value),
        "hyperlink-format" => ("hyperlink-format", FlagKind::Value),
        "max-columns" => ("max-columns", FlagKind::Value),
        "replace" => ("replace", FlagKind::Value),
        "sort" => ("sort", FlagKind::Value),
        "sortr" => ("sortr", FlagKind::Value),
        // switch flags (ids encode action)
        _ => {
            // check switch list
            if is_switch_long(name) { (Box::leak(name.to_string().into_boxed_str()) as &'static str, FlagKind::Switch) } else { return None; }
        }
    };
    Some(FlagDef{id, kind})
}

fn is_switch_long(name: &str) -> bool {
    matches!(name,
    "search-zip"|"no-search-zip"|"case-sensitive"|"crlf"|"no-crlf"|"fixed-strings"|"no-fixed-strings"|"ignore-case"|"invert-match"|"no-invert-match"|"line-regexp"|"mmap"|"no-mmap"|"multiline"|"no-multiline"|"multiline-dotall"|"no-multiline-dotall"|"no-unicode"|"unicode"|"null-data"|"pcre2"|"no-pcre2"|"smart-case"|"stop-on-nonmatch"|"text"|"no-text"|"word-regexp"|"auto-hybrid-regex"|"no-auto-hybrid-regex"|"no-pcre2-unicode"|"pcre2-unicode"|"binary"|"no-binary"|"follow"|"no-follow"|"glob-case-insensitive"|"no-glob-case-insensitive"|"hidden"|"no-hidden"|"ignore-file-case-insensitive"|"no-ignore-file-case-insensitive"|"no-ignore"|"ignore"|"no-ignore-dot"|"ignore-dot"|"no-ignore-exclude"|"ignore-exclude"|"no-ignore-files"|"ignore-files"|"no-ignore-global"|"ignore-global"|"no-ignore-parent"|"ignore-parent"|"no-ignore-vcs"|"ignore-vcs"|"no-require-git"|"require-git"|"one-file-system"|"no-one-file-system"|"unrestricted"|"block-buffered"|"no-block-buffered"|"byte-offset"|"no-byte-offset"|"column"|"no-column"|"heading"|"no-heading"|"help"|"include-zero"|"no-include-zero"|"line-buffered"|"no-line-buffered"|"line-number"|"no-line-number"|"max-columns-preview"|"no-max-columns-preview"|"null"|"print0"|"only-matching"|"passthru"|"passthrough"|"pretty"|"quiet"|"trim"|"no-trim"|"vimgrep"|"with-filename"|"no-filename"|"sort-files"|"no-sort-files"|"count"|"count-matches"|"files-with-matches"|"files-without-match"|"json"|"no-json"|"debug"|"no-ignore-messages"|"ignore-messages"|"no-messages"|"messages"|"stats"|"no-stats"|"trace"|"files"|"no-config"|"pcre2-version"|"type-list"|"version"|"no-encoding"|"no-pre"|"no-context-separator"
    )
}

fn short_def(c: char) -> Option<FlagDef> {
    let (id, kind) = match c {
        'e' => ("regexp", FlagKind::Value),
        'f' => ("file", FlagKind::Value),
        'E' => ("encoding", FlagKind::Value),
        'm' => ("max-count", FlagKind::Value),
        'j' => ("threads", FlagKind::Value),
        'g' => ("glob", FlagKind::Value),
        'd' => ("max-depth", FlagKind::Value),
        't' => ("type", FlagKind::Value),
        'T' => ("type-not", FlagKind::Value),
        'A' => ("after-context", FlagKind::Value),
        'B' => ("before-context", FlagKind::Value),
        'C' => ("context", FlagKind::Value),
        'M' => ("max-columns", FlagKind::Value),
        'r' => ("replace", FlagKind::Value),
        'h' => ("__help_short", FlagKind::Switch),
        'V' => ("__version_short", FlagKind::Switch),
        's'|'F'|'i'|'v'|'x'|'U'|'P'|'S'|'a'|'w'|'z'|'L'|'.'|'u'|'b'|'c'|'l'|'n'|'N'|'o'|'p'|'q'|'H'|'I'|'0' => {
            let id = match c {
                's' => "case-sensitive", 'F' => "fixed-strings", 'i' => "ignore-case", 'v' => "invert-match", 'x' => "line-regexp", 'U' => "multiline", 'P' => "pcre2", 'S' => "smart-case", 'a' => "text", 'w' => "word-regexp", 'z' => "search-zip", 'L' => "follow", '.' => "hidden", 'u' => "unrestricted", 'b' => "byte-offset", 'c' => "count", 'l' => "files-with-matches", 'n' => "line-number", 'N' => "no-line-number", 'o' => "only-matching", 'p' => "pretty", 'q' => "quiet", 'H' => "with-filename", 'I' => "no-filename", '0' => "null", _ => unreachable!(),
            };
            (id, FlagKind::Switch)
        }
        _ => return None,
    };
    // leak for uniformity (id static-ish) - use match returning static strings via re-match in apply functions using char/id str passed
    Some(FlagDef{id: match id { "regexp"=>"regexp","file"=>"file","encoding"=>"encoding","max-count"=>"max-count","threads"=>"threads","glob"=>"glob","max-depth"=>"max-depth","type"=>"type","type-not"=>"type-not","after-context"=>"after-context","before-context"=>"before-context","context"=>"context","max-columns"=>"max-columns","replace"=>"replace","__help_short"=>"__help_short","__version_short"=>"__version_short", x=> match x {"case-sensitive"=>"case-sensitive","fixed-strings"=>"fixed-strings","ignore-case"=>"ignore-case","invert-match"=>"invert-match","line-regexp"=>"line-regexp","multiline"=>"multiline","pcre2"=>"pcre2","smart-case"=>"smart-case","text"=>"text","word-regexp"=>"word-regexp","search-zip"=>"search-zip","follow"=>"follow","hidden"=>"hidden","unrestricted"=>"unrestricted","byte-offset"=>"byte-offset","count"=>"count","files-with-matches"=>"files-with-matches","line-number"=>"line-number","no-line-number"=>"no-line-number","only-matching"=>"only-matching","pretty"=>"pretty","quiet"=>"quiet","with-filename"=>"with-filename","no-filename"=>"no-filename","null"=>"null", _=>"unknown"} }, kind})
}

fn suggestions(name: &str) -> Vec<&'static str> {
    // Sorensen-Dice bigram similarity > 0.6 (approx observed), plus prefix relation.
    fn dice(a: &str, b: &str) -> f64 {
        if a.len() < 2 || b.len() < 2 { return if a==b {1.0} else {0.0}; }
        let bigrams = |s: &str| -> Vec<String> { s.chars().collect::<Vec<_>>().windows(2).map(|w| w.iter().collect()).collect() };
        let aa = bigrams(a); let bb = bigrams(b);
        let mut used = vec![false; bb.len()];
        let mut common = 0usize;
        for x in &aa {
            for (i,y) in bb.iter().enumerate() {
                if !used[i] && x==y { used[i]=true; common+=1; break; }
            }
        }
        (2.0 * common as f64) / ((aa.len()+bb.len()) as f64)
    }
    let mut out = Vec::new();
    for cand in all_long_flags() {
        if cand == "hostname-bin" && out.iter().filter(|c| **c=="hostname-bin").count()>0 { continue; }
        let d = dice(name, cand);
        let prefix_rel = cand.starts_with(name) || name.starts_with(cand);
        if d > 0.6 || (prefix_rel && name.len()>=3 && cand.len()>=3 && (name.len() as isize - cand.len() as isize).abs() <= 6) {
            // avoid spurious short sort/text anomalies approximating original: require d>0.6 already; prefix case may add some but keep within dice fallback
            if d > 0.6 { out.push(cand); }
        }
    }
    // dedup preserve order
    let mut seen = std::collections::HashSet::new();
    out.retain(|x| seen.insert(*x));
    out
}

fn apply_switch(args: &mut Args, id: &str) {
    match id {
        "__help_short" => args.special = Some(Special::HelpShort),
        "__version_short" => args.special = Some(Special::VersionShort),
        "__noop_hv" => {},
        "help" => args.special = Some(Special::HelpLong),
        "version" => args.special = Some(Special::VersionLong),
        "pcre2-version" => args.special = Some(Special::Pcre2Version),
        "type-list" => args.mode = Mode::Types,
        "files" => args.mode = Mode::Files,
        "count" => args.mode = Mode::Search(PrinterMode::Count),
        "count-matches" => args.mode = Mode::Search(PrinterMode::CountMatches),
        "files-with-matches" => args.mode = Mode::Search(PrinterMode::FilesWithMatches),
        "files-without-match" => args.mode = Mode::Search(PrinterMode::FilesWithoutMatch),
        "json" => args.mode = Mode::Search(PrinterMode::Json),
        "no-json" => { if args.mode == Mode::Search(PrinterMode::Json) { args.mode = Mode::Search(PrinterMode::Standard); } }
        "search-zip" => args.search_zip = true,
        "no-search-zip" => args.search_zip = false,
        "case-sensitive" => args.case = CaseMode::Sensitive,
        "ignore-case" => args.case = CaseMode::Insensitive,
        "smart-case" => args.case = CaseMode::Smart,
        "crlf" => { args.crlf = true; if args.null_data { args.null_data = false; } },
        "no-crlf" => args.crlf = false,
        "fixed-strings" => args.fixed = true,
        "no-fixed-strings" => args.fixed = false,
        "invert-match" => args.invert = true,
        "no-invert-match" => args.invert = false,
        "line-regexp" => args.boundary = Boundary::Line,
        "word-regexp" => args.boundary = Boundary::Word,
        "mmap" => args.mmap = true,
        "no-mmap" => args.mmap = false,
        "multiline" => args.multiline = true,
        "no-multiline" => args.multiline = false,
        "multiline-dotall" => args.multiline_dotall = true,
        "no-multiline-dotall" => args.multiline_dotall = false,
        "no-unicode" => args.unicode = false,
        "unicode" => args.unicode = true,
        "null-data" => { args.null_data = true; args.crlf = false; },
        "pcre2" => args.engine = Engine::Pcre2,
        "no-pcre2" => args.engine = Engine::Default,
        "stop-on-nonmatch" => args.stop_on_nonmatch = true,
        "text" => args.binary_mode = BinaryMode::Text,
        "no-text" => args.binary_mode = BinaryMode::Default,
        "auto-hybrid-regex" => args.engine = Engine::Auto,
        "no-auto-hybrid-regex" => args.engine = Engine::Default,
        "no-pcre2-unicode" => args.pcre2_unicode = false,
        "pcre2-unicode" => args.pcre2_unicode = true,
        "binary" => args.binary_mode = BinaryMode::Binary,
        "no-binary" => args.binary_mode = BinaryMode::Default,
        "follow" => args.follow = true,
        "no-follow" => args.follow = false,
        "glob-case-insensitive" => args.glob_case_insensitive = true,
        "no-glob-case-insensitive" => args.glob_case_insensitive = false,
        "hidden" => args.hidden = true,
        "no-hidden" => args.hidden = false,
        "ignore-file-case-insensitive" => args.ignore_file_case_insensitive = true,
        "no-ignore-file-case-insensitive" => args.ignore_file_case_insensitive = false,
        "no-ignore" => { args.no_ignore = true; args.no_ignore_dot = true; args.no_ignore_exclude = true; args.no_ignore_global = true; args.no_ignore_parent = true; args.no_ignore_vcs = true; },
        "ignore" => { args.no_ignore = false; args.no_ignore_dot = false; args.no_ignore_exclude = false; args.no_ignore_global = false; args.no_ignore_parent = false; args.no_ignore_vcs = false; },
        "no-ignore-dot" => args.no_ignore_dot = true,
        "ignore-dot" => args.no_ignore_dot = false,
        "no-ignore-exclude" => args.no_ignore_exclude = true,
        "ignore-exclude" => args.no_ignore_exclude = false,
        "no-ignore-files" => args.no_ignore_files = true,
        "ignore-files" => args.no_ignore_files = false,
        "no-ignore-global" => args.no_ignore_global = true,
        "ignore-global" => args.no_ignore_global = false,
