#[derive(Debug, Clone, PartialEq)]
pub enum EffectiveEncoding { Raw, Utf16Le, Utf16Be, Latin1ToUtf8, Utf8StripBom }

// Decode input bytes according to ripgrep rules:
// - If encoding is None -> raw
// - Else if BOM present (UTF8/UTF16) -> decode according to BOM, stripping it.
// - Else if explicit label -> decode according to label (subset implemented)
// - Else (auto) -> raw
pub fn decode_bytes(data: &[u8], encoding: &crate::flags::Encoding) -> Vec<u8> {
    use crate::flags::Encoding;
    match encoding {
        Encoding::None => return data.to_vec(),
        _ => {}
    }
    // BOM sniffing
    if data.starts_with(&[0xEF,0xBB,0xBF]) {
        // UTF-8 BOM: strip, but only if encoding != none (already handled)
        // However if explicit label is something? Observed BOM overrides, strip.
        return data[3..].to_vec();
    }
    if data.starts_with(&[0xFF,0xFE]) {
        return decode_utf16(&data[2..], true);
    }
    if data.starts_with(&[0xFE,0xFF]) {
        return decode_utf16(&data[2..], false);
    }
    if let Encoding::Label(label) = encoding {
        let low = label.to_ascii_lowercase();
        let trimmed = low.trim().to_string();
        match trimmed.as_str() {
            "utf-16"|"utf-16le"|"unicode"|"ucs-2"|"iso-10646-ucs-2"|"csunicode"|"unicodefeff" => return decode_utf16(data, true),
            "utf-16be"|"unicodefffe" => return decode_utf16(data, false),
            "utf-8"|"utf8"|"unicode-1-1-utf-8"|"unicode11utf8"|"unicode20utf8"|"x-unicode20utf8" => {
                // If UTF-8 BOM already handled above; also encoding_rs would strip BOM? strip if present (already)
                return data.to_vec();
            }
            s if is_latin_label(s) => {
                return data.iter().map(|b| {
                    let ch = windows1252_char(*b);
                    let mut buf = [0u8;4];
                    ch.encode_utf8(&mut buf).as_bytes().to_vec()
                }).collect::<Vec<_>>().concat();
            }
            _ => {
                // For other labels we do not have a full transcoder; treat as raw bytes
                // (ASCII-compatible encodings will mostly work, others are rare in tests)
                return data.to_vec();
            }
        }
    }
    data.to_vec()
}

fn is_latin_label(s: &str) -> bool {
    matches!(s, "latin1"|"iso-8859-1"|"iso8859-1"|"iso88591"|"iso_8859-1"|"iso_8859-1:1987"|"csisolatin1"|"l1"|"cp819"|"windows-1252"|"cp1252"|"ansi"|"ascii"|"us-ascii"|"csascii"|"iso-ir-6"|"iso646-us"|"iso_646.irv:1991"|"us"|"ibm367"|"cp367"|"ansi_x3.4-1968")
}

fn windows1252_char(b: u8) -> char {
    // WHATWG windows-1252 mapping; for iso-8859-1 labels encoding_rs also maps to windows-1252.
    match b {
        0x80 => '\u{20AC}', 0x82 => '\u{201A}', 0x83 => '\u{0192}', 0x84 => '\u{201E}', 0x85 => '\u{2026}', 0x86 => '\u{2020}', 0x87 => '\u{2021}', 0x88 => '\u{02C6}', 0x89 => '\u{2030}', 0x8A => '\u{0160}', 0x8B => '\u{2039}', 0x8C => '\u{0152}', 0x8E => '\u{017D}', 0x91 => '\u{2018}', 0x92 => '\u{2019}', 0x93 => '\u{201C}', 0x94 => '\u{201D}', 0x95 => '\u{2022}', 0x96 => '\u{2013}', 0x97 => '\u{2014}', 0x98 => '\u{02DC}', 0x99 => '\u{2122}', 0x9A => '\u{0161}', 0x9B => '\u{203A}', 0x9C => '\u{0153}', 0x9E => '\u{017E}', 0x9F => '\u{0178}',
        _ => b as char, // 0x81,0x8D,0x8F,0x90,0x9D map to control chars themselves in WHATWG index
    }
}

pub fn decode_utf16(data: &[u8], little_endian: bool) -> Vec<u8> {
    let mut units: Vec<u16> = Vec::new();
    let mut i = 0;
    while i + 1 < data.len() {
        let u = if little_endian { u16::from_le_bytes([data[i], data[i+1]]) } else { u16::from_be_bytes([data[i], data[i+1]]) };
        units.push(u);
        i += 2;
    }
    let trailing = if i < data.len() { Some(data[i]) } else { None };
    let decoded = String::from_utf16_lossy(&units);
    let mut out = decoded.into_bytes();
    if let Some(_b) = trailing {
        // invalid trailing byte becomes replacement char in encoding_rs
        out.extend_from_slice("\u{FFFD}".as_bytes());
    }
    out
}
