use std::collections::BTreeMap;
use crate::glob::{build_glob, Glob, GlobError};

pub struct Types {
    pub map: BTreeMap<String, Vec<String>>, // name -> glob strings (original order for display? sorted in display)
}

impl Types {
    pub fn defaults() -> Self {
        let txt = include_str!("../assets/types.txt");
        let mut map = BTreeMap::new();
        for line in txt.lines() {
            if let Some((name, rest)) = line.split_once(':') {
                let name = name.trim().to_string();
                let globs = rest.trim().split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect::<Vec<_>>();
                map.insert(name, globs);
            }
        }
        Types{map}
    }
    pub fn apply_add(&mut self, spec: &str) -> Result<(), String> {
        // format type:glob or type:include:a,b
        let parts: Vec<&str> = spec.split(':').collect();
        if parts.len() != 2 && parts.len() != 3 {
            return Err("rg: invalid definition (format is type:glob, e.g., html:*.html)\n".to_string());
        }
        let name = parts[0];
        if name.is_empty() || !name.chars().all(|c| c.is_alphanumeric()) {
            return Err("rg: invalid definition (format is type:glob, e.g., html:*.html)\n".to_string());
        }
        if parts.len() == 3 {
            if parts[1] != "include" {
                return Err("rg: invalid definition (format is type:glob, e.g., html:*.html)\n".to_string());
            }
            let inc = parts[2];
            if inc.is_empty() { return Err("rg: invalid definition (format is type:glob, e.g., html:*.html)\n".to_string()); }
            let mut new_globs: Vec<String> = Vec::new();
            for inc_name in inc.split(',') {
                match self.map.get(inc_name) {
                    Some(g) => new_globs.extend(g.iter().cloned()),
                    None => return Err("rg: invalid definition (format is type:glob, e.g., html:*.html)\n".to_string()),
                }
            }
            let entry = self.map.entry(name.to_string()).or_insert_with(Vec::new);
            entry.extend(new_globs);
            return Ok(());
        }
        // 2 parts
        let glob = parts[1];
        if glob.is_empty() { return Err("rg: invalid definition (format is type:glob, e.g., html:*.html)\n".to_string()); }
        // validate glob? If invalid, glob building elsewhere will error? Original for type-add with invalid glob pattern?
        let entry = self.map.entry(name.to_string()).or_insert_with(Vec::new);
        entry.push(glob.to_string());
        Ok(())
    }
    pub fn apply_clear(&mut self, name: &str) {
        self.map.remove(name);
    }
    pub fn display(&self) -> String {
        let mut out = String::new();
        for (name, globs) in &self.map {
            if globs.is_empty() { continue; }
            let mut sorted = globs.clone();
            sorted.sort();
            sorted.dedup();
            out.push_str(&format!("{}: {}\n", name, sorted.join(", ")));
        }
        out
    }
    // Build compiled globs per type name
    pub fn compiled(&self, name: &str) -> Option<Vec<Glob>> {
        self.map.get(name).map(|globs| {
            globs.iter().filter_map(|g| build_type_glob(g).ok()).collect()
        })
    }
    pub fn has_type(&self, name: &str) -> bool {
        // A type that has been cleared is removed, so unknown.
        // A type with empty glob list? Also considered unknown after clear (map removed)
        self.map.contains_key(name) && !self.map.get(name).map(|v| v.is_empty()).unwrap_or(true)
    }
}

pub fn build_type_glob(g: &str) -> Result<Glob, GlobError> {
    // Type globs are matched against file name (basename) only, as gitignore non-anchored
    // But some globs are like "BUILD", "Makefile", "*Dockerfile*", "gradle-wrapper.*", ".bashrc" - basename matching works.
    // Some might contain /? Not in defaults. Use gitignore style.
    crate::glob::build_gitignore_glob(g, false)
}

RS
