use crate::glob::{build_gitignore_glob, build_override_glob, Glob, GlobError};

#[derive(Debug, Clone)]
pub struct Haystack {
    pub display: PathBuf,
    pub fs_path: Option<PathBuf>,
    pub is_stdin: bool,
    pub explicit_file: bool,
}

#[derive(Debug)]
pub struct Segment { pub haystacks: Vec<Haystack> }

#[derive(Debug, Clone)]
struct Rule {
    base_abs: PathBuf,
    category: u8,
    depth: usize,
    order: usize,
    glob: Glob,
    negated: bool,
