pub struct Filters {
    pub overrides: Vec<OverrideEntry>,
    pub type_entries: Vec<(Glob, bool)>, // whitelist=true
    pub has_type_select: bool,
}

pub struct OverrideEntry { pub glob: Glob, pub blacklist: bool, pub dir_only: bool }

pub fn format_glob_error(original: &str, e: &GlobError) -> String {
    format!("rg: error parsing glob '{}': {}\n", original, e.0)
}

pub fn build_types(args: &Args) -> Result<Types, String> {
    let mut types = Types::defaults();
    for op in &args.type_ops {
        match op {
            TypeOp::Add(spec) => types.apply_add(spec)?,
            TypeOp::Clear(name) => types.apply_clear(name),
        }
    }
    Ok(types)
}

pub fn build_filters(args: &Args, types: &Types) -> Result<Filters, String> {
    // validate types mentioned and compile type entries in mention-order
    let mut type_entries = Vec::new();
    let mut has_select = false;
    for (name, is_select) in &args.type_mentions {
        if *is_select { has_select = true; }
        if name == "all" {
            // expand all types in sorted map order
            for (tname, globs) in &types.map {
                if globs.is_empty() { continue; }
                for g in globs {
                    let glob = build_type_glob(g).map_err(|e| format_glob_error(g, &e))?;
                    type_entries.push((glob, *is_select));
                    let _ = tname;
                }
            }
        } else {
            if !types.has_type(name) {
                return Err(format!("rg: unrecognized file type: {}\n", name));
            }
            if let Some(globs) = types.map.get(name) {
                for g in globs {
                    let glob = build_type_glob(g).map_err(|e| format_glob_error(g, &e))?;
                    type_entries.push((glob, *is_select));
                }
            }
        }
    }
    // override globs
    let mut overrides = Vec::new();
    for (pat, is_iglob) in &args.overrides {
        let (blacklist, stripped, dir_only) = parse_override_pattern(pat);
        let case_i = *is_iglob || args.glob_case_insensitive;
        let glob = build_override_glob(&stripped, case_i).map_err(|e| format_glob_error(pat, &e))?;
        overrides.push(OverrideEntry{glob, blacklist, dir_only});
    }
    Ok(Filters{overrides, type_entries, has_type_select: has_select})
}

fn parse_override_pattern(pat: &str) -> (bool, String, bool) {
    let mut blacklist = false;
    let mut s = pat.to_string();
    if let Some(rest) = s.strip_prefix('!') { blacklist = true; s = rest.to_string(); }
    else if let Some(rest) = s.strip_prefix("\\!") { s = format!("!{}", rest); }
    let mut dir_only = false;
    if s.ends_with('/') && !s.ends_with("\\/") { dir_only = true; s.pop(); }
    (blacklist, s, dir_only)
}

fn stderr_write(s: &str) {
    let _ = io::stderr().write_all(s.as_bytes());
}

pub struct WalkContext<'a> {
    pub args: &'a Args,
    pub filters: &'a Filters,
    pub had_error: bool,
    pub global_rules: Vec<Rule>,
    pub custom_rules: Vec<Rule>,
    next_order: usize,
    pub cwd_abs: PathBuf,
}

impl<'a> WalkContext<'a> {
    pub fn new(args: &'a Args, filters: &'a Filters) -> Self {
        let cwd_abs = absolute_lexical(&std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let mut ctx = WalkContext{ args, filters, had_error:false, global_rules:Vec::new(), custom_rules:Vec::new(), next_order:0, cwd_abs: cwd_abs.clone() };
        // custom ignore files
        if !args.no_ignore_files {
            for path in &args.ignore_files_custom {
                ctx.load_custom_ignore_file(path);
            }
        }
        // global
        if !args.no_ignore_global && !args.no_ignore_vcs {
            if let Some(gp) = global_gitignore_path() {
                if gp.exists() {
                    ctx.load_global_file(&gp, cwd_abs.clone());
                }
            }
        }
        ctx
    }

    fn load_custom_ignore_file(&mut self, path: &Path) {
        match fs::read(path) {
            Ok(content) => {
                let display = path.to_path_buf();
                self.parse_ignore_content(&content, &display, self.cwd_abs.clone(), 0, false);
            }
            Err(e) => {
                if !self.args.no_messages {
                    stderr_write(&format!("rg: {}: {}\n", path.to_string_lossy(), e));
                }
            }
        }
    }
    fn load_global_file(&mut self, path: &Path, cwd: PathBuf) {
        if let Ok(content) = fs::read(path) {
            let disp = path.to_path_buf();
            // global rules require git context
            let rules_before = self.global_rules.len();
            let mut tmp_rules = Vec::new();
            // parse into tmp via helper using self parser? We'll parse directly by temporarily swapping
            // Simpler: collect rules using parse function that returns rules
            let parsed = self.parse_rules_from_content(&content, &disp, cwd, 1, true);
            tmp_rules.extend(parsed);
            self.global_rules.extend(tmp_rules);
            let _ = rules_before;
        }
    }

    fn parse_ignore_content(&mut self, content: &[u8], display_path: &Path, base_abs: PathBuf, category: u8, requires_git: bool) {
        let rules = self.parse_rules_from_content(content, display_path, base_abs, category, requires_git);
        // dispatch to appropriate storage based on category? This loader is used for custom (goes to custom_rules) and directory rules (returned separately elsewhere)
        // For custom only call site here.
        self.custom_rules.extend(rules);
    }

    fn parse_rules_from_content(&mut self, content: &[u8], display_path: &Path, base_abs: PathBuf, category: u8, requires_git: bool) -> Vec<Rule> {
        let mut rules = Vec::new();
        let text = String::from_utf8_lossy(content);
        for (idx, raw_line) in text.lines().enumerate() {
            let line_no = idx + 1;
            let line_original = raw_line;
            let mut line = raw_line.to_string();
            // gitignore parsing
            if line.trim().is_empty() { continue; }
            // comment
            let mut negated = false;
            let mut pat: String;
            if let Some(rest) = line.strip_prefix("\\#") {
                pat = format!("#{}", rest);
            } else if line.starts_with('#') {
                continue;
            } else if let Some(rest) = line.strip_prefix("\\!") {
                pat = format!("!{}", rest);
            } else if let Some(rest) = line.strip_prefix('!') {
                negated = true; pat = rest.to_string();
            } else { pat = line.clone(); }
            // trailing slash dir_only
            let mut dir_only = false;
            if pat.ends_with('/') && !pat.ends_with("\\/") { dir_only = true; pat.pop(); }
            // trailing spaces (unescaped)
            loop {
                if pat.ends_with(' ') {
                    if pat.ends_with("\\ ") { pat = format!("{} ", &pat[..pat.len()-2]); break; } else { pat.pop(); }
                } else { break; }
            }
            if pat.is_empty() { continue; }
            // build glob
            match build_gitignore_glob(&pat, self.args.ignore_file_case_insensitive) {
                Ok(glob) => {
                    let depth = base_abs.components().count();
                    let order = self.next_order; self.next_order += 1;
                    rules.push(Rule{base_abs: base_abs.clone(), category, depth, order, glob, negated, dir_only, requires_git});
                }
                Err(e) => {
                    if !self.args.no_ignore_messages && !self.args.no_messages {
                        stderr_write(&format!("rg: {}: line {}: error parsing glob '{}': {}\n", display_path.to_string_lossy(), line_no, line_original, e.0));
                    }
                }
            }
            let _ = &mut line;
        }
        rules
    }

    fn load_dir_ignore_files(&mut self, dir_fs: &Path, dir_display_base: &Path, in_git: bool) -> Vec<Rule> {
        // dir_display_base is the filesystem path to use for opening/display (same as dir_fs generally except implicit root is ".")
        let mut out = Vec::new();
        // gitignore
        if !self.args.no_ignore_vcs {
            if in_git || !self.args.require_git {
                let p = dir_fs.join(".gitignore");
                if let Ok(content) = fs::read(&p) {
                    let base = absolute_lexical(&dir_fs.to_path_buf());
                    out.extend(self.parse_rules_from_content(&content, &p, base, 3, false));
                }
            }
        }
        // exclude, if this directory is a repo root (contains .git)
        if !self.args.no_ignore_exclude && !self.args.no_ignore_vcs {
            if let Some(exclude_path) = git_exclude_path(dir_fs) {
                if let Ok(content) = fs::read(&exclude_path) {
                    let base = absolute_lexical(&dir_fs.to_path_buf());
                    out.extend(self.parse_rules_from_content(&content, &exclude_path, base, 2, false));
                }
            }
        }
        if !self.args.no_ignore_dot {
            for (fname, cat) in [(".ignore",4u8),(".rgignore",5u8)] {
                let p = dir_fs.join(fname);
                if let Ok(content) = fs::read(&p) {
                    let base = absolute_lexical(&dir_fs.to_path_buf());
                    out.extend(self.parse_rules_from_content(&content, &p, base, cat, false));
                }
            }
        }
        let _ = dir_display_base;
        out
    }
}

fn git_exclude_path(dir_fs: &Path) -> Option<PathBuf> {
    let git_path = dir_fs.join(".git");
    let md = fs::symlink_metadata(&git_path).ok()?;
    if md.is_dir() {
        Some(git_path.join("info").join("exclude"))
    } else if md.is_file() {
        // parse gitdir: <path>
        if let Ok(content) = fs::read_to_string(&git_path) {
            for line in content.lines() {
                if let Some(rest) = line.strip_prefix("gitdir:") {
                    let p = rest.trim();
                    let gitdir = if Path::new(p).is_absolute() { PathBuf::from(p) } else { dir_fs.join(p) };
                    return Some(gitdir.join("info").join("exclude"));
                }
            }
        }
        None
    } else { None }
}

pub fn contains_git_marker(dir_fs: &Path) -> bool {
    dir_fs.join(".git").symlink_metadata().is_ok()
}

fn global_gitignore_path() -> Option<PathBuf> {
    let home = std::env::var_os("HOME").map(PathBuf::from).or_else(|| std::env::home_dir())?;
    // config lookup
    let xdg_config_home = std::env::var_os("XDG_CONFIG_HOME").map(PathBuf::from).unwrap_or_else(|| home.join(".config"));
    // read config files: XDG git/config then HOME/.gitconfig, later overrides
    let mut excludes: Option<PathBuf> = None;
    for cfg in [xdg_config_home.join("git").join("config"), home.join(".gitconfig")] {
        if let Ok(content) = fs::read_to_string(&cfg) {
            if let Some(p) = parse_git_config_excludes(&content, &home) { excludes = Some(p); }
        }
    }
    if let Some(p) = excludes { return Some(p); }
    Some(xdg_config_home.join("git").join("ignore"))
}

fn parse_git_config_excludes(content: &str, home: &Path) -> Option<PathBuf> {
    let mut in_core = false;
    let mut result = None;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            in_core = t.to_ascii_lowercase().starts_with("[core");
            continue;
        }
        if in_core {
            if let Some((k,v)) = t.split_once('=') {
                if k.trim().to_ascii_lowercase() == "excludesfile" {
                    let mut val = v.trim().to_string();
                    if val.starts_with("~/") { result = Some(home.join(&val[2..])); } else { result = Some(PathBuf::from(val)); }
                }
            }
        }
    }
    result
}

pub fn absolute_lexical(p: &Path) -> PathBuf {
    let abs = if p.is_absolute() { p.to_path_buf() } else {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(p)
    };
    normalize_lexical(&abs)
}
pub fn normalize_lexical(p: &Path) -> PathBuf {
    use std::path::Component;
    let mut out = PathBuf::new();
    for comp in p.components() {
        match comp {
            Component::CurDir => {}
            Component::ParentDir => { out.pop(); }
            c => out.push(c.as_os_str()),
        }
    }
    if out.as_os_str().is_empty() { out.push("/"); }
    out
}
fn relative_match_string(base_abs: &Path, cand_abs: &Path) -> String {
    // produce path relative to base using lexical components with ../ if needed
    let base_comps: Vec<String> = base_abs.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    let cand_comps: Vec<String> = cand_abs.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    let mut i = 0;
    while i < base_comps.len() && i < cand_comps.len() && base_comps[i]==cand_comps[i] { i += 1; }
    let mut parts = Vec::new();
    for _ in i..base_comps.len() { parts.push("..".to_string()); }
    for c in &cand_comps[i..] { parts.push(c.clone()); }
    parts.join("/")
}

fn eval_ignore_rules(rules: &[Rule], cand_abs: &Path, is_dir: bool, in_git: bool) -> Option<bool> {
    // return Some(true) if whitelist wins, Some(false) if ignore wins, None if no match (using bool whitelist indicator)
    // We'll return enum via Option<bool> where true = whitelisted, false = ignored
    let mut best: Option<(u8, usize, usize, bool)> = None; // cat,depth,order,negated
    for r in rules {
        if r.requires_git && !in_git { continue; }
        if r.dir_only && !is_dir {
            // need to consider ancestor directories below
            // matching below will handle ancestors
        }
        let rel = relative_match_string(&r.base_abs, cand_abs);
        if rel.is_empty() { continue; }
        // candidates to test: rel itself and ancestor prefixes (for patterns matching a parent directory)
        let comps: Vec<&str> = rel.split('/').collect();
        let mut candidate_strings: Vec<String> = Vec::new();
        if !r.dir_only || is_dir {
            candidate_strings.push(rel.clone());
        }
        // ancestors
        for k in 1..comps.len() {
            candidate_strings.push(comps[..k].join("/"));
        }
        let mut matched = false;
        for cand_str in &candidate_strings {
            // for ancestor candidate, it is a directory, so dir_only OK
            if r.glob.is_match(cand_str.as_bytes()) { matched = true; break; }
        }
        if matched {
            let key = (r.category, r.depth, r.order, r.negated);
            if best.map(|b| (key.0, key.1, key.2) >= (b.0, b.1, b.2)).unwrap_or(true) {
                best = Some(key);
            }
        }
    }
    best.map(|b| b.3)
}

fn last_override_decision(filters: &Filters, match_path: &str, is_dir: bool) -> Option<bool> {
    // Some(true) whitelist, Some(false) blacklist, None no match
    let mut last: Option<bool> = None;
    for e in &filters.overrides {
        if e.dir_only && !is_dir { continue; }
        if e.glob.is_match(match_path.as_bytes()) { last = Some(!e.blacklist); }
    }
    last
}
fn has_override_whitelist(filters: &Filters) -> bool { filters.overrides.iter().any(|e| !e.blacklist) }

fn type_decision(filters: &Filters, basename_bytes: &[u8]) -> (bool, bool) {
    // return (allowed, whitelist_matched)
    let mut last: Option<bool> = None;
    for (glob, is_white) in &filters.type_entries {
        if glob.is_match(basename_bytes) { last = Some(*is_white); }
    }
    match last {
        Some(true) => (true, true),
        Some(false) => (false, false),
        None => {
            if filters.has_type_select { (false, false) } else { (true, false) }
        }
    }
}

pub fn match_path_for_candidate(ctx: &WalkContext, cand_abs: &Path) -> String {
    relative_match_string(&ctx.cwd_abs, cand_abs)
}

pub fn is_hidden_name(name: &std::ffi::OsStr) -> bool {
    #[cfg(unix)] { name.as_bytes().first() == Some(&b'.') }
    #[cfg(not(unix))] { name.to_string_lossy().starts_with('.') }
}

// Walker for one filesystem root path.
// Returns segment haystacks; errors have been printed and ctx.had_error set.
pub fn walk_root(ctx: &mut WalkContext, root: &Path, total_paths: usize) -> Segment {
    let mut segment = Segment{haystacks: Vec::new()};
    // metadata following links
    let md = match fs::metadata(root) {
        Ok(m) => m,
        Err(e) => {
            if !ctx.args.no_messages {
                if total_paths == 1 {
                    stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", root.to_string_lossy(), root.to_string_lossy(), e));
                } else {
                    stderr_write(&format!("rg: {}: {}\n", root.to_string_lossy(), e));
                }
            }
            ctx.had_error = true;
            return segment;
        }
    };
    if !md.is_dir() {
        segment.haystacks.push(Haystack{display: root.to_path_buf(), fs_path: Some(root.to_path_buf()), is_stdin:false, explicit_file:true});
        return segment;
    }
    // directory traversal
    let root_abs = absolute_lexical(root);
    let anchor_dir_abs = root_abs.clone();
    // compute ancestors above anchor and parent git status
    let mut parent_has_git = false;
    let mut base_rules: Vec<Rule> = Vec::new();
    base_rules.extend(ctx.global_rules.clone());
    base_rules.extend(ctx.custom_rules.clone());
    // ancestors
    {
        // build list of ancestor directories (strictly above anchor)
        let mut ancestors: Vec<PathBuf> = Vec::new();
        let mut cur = anchor_dir_abs.parent().map(|p| p.to_path_buf());
        while let Some(p) = cur {
            ancestors.push(p.clone());
            cur = p.parent().map(|x| x.to_path_buf());
        }
        ancestors.reverse(); // top down
        let mut cumulative_git = false;
        for anc in &ancestors {
            let marker = contains_git_marker(anc);
            cumulative_git = cumulative_git || marker;
            if !ctx.args.no_ignore_parent {
                // load ignore files of ancestor (as if entering it, but not directory itself that we traverse below)
                // We need load using its own dir path (absolute)
                // Construct temporary loader rules:
                let anc_rules = ctx.load_dir_ignore_files(anc, anc, cumulative_git);
                base_rules.extend(anc_rules);
                // load_dir_ignore_files already loaded exclude if marker, but for ancestors that are repos their exclude was loaded there
            }
        }
        parent_has_git = cumulative_git;
    }
    // device of root for one-file-system
    let root_dev = {
        #[cfg(unix)] { md.dev() }
        #[cfg(not(unix))] { 0 }
    };
    let mut ancestors_dirs: Vec<(u64,u64,PathBuf)> = Vec::new();
    {
        #[cfg(unix)] { ancestors_dirs.push((md.dev(), md.ino(), root.to_path_buf())); }
    }
    // display base and fs base
    let display_base: PathBuf = if is_implicit_root(root) {
        PathBuf::new() // empty
    } else {
        root.to_path_buf()
    };
    let fs_base: PathBuf = root.to_path_buf();
    // recursive
    let mut rules = base_rules;
    visit_dir(ctx, &fs_base, &display_base, 0, parent_has_git, root_dev, &mut ancestors_dirs, &mut rules, &mut segment, root);
    segment
}

fn is_implicit_root(root: &Path) -> bool {
    // The caller signals implicit root by passing Path::new("\0IMPLICIT") placeholder - not used here.
    // Instead, main passes root "." but marks? We'll detect in main by separate function walk_root_implicit.
    false
}

pub fn walk_root_with_display(ctx: &mut WalkContext, root: &Path, total_paths: usize, implicit: bool) -> Segment {
    if !implicit { return walk_root(ctx, root, total_paths); }
    // implicit version duplicates walk_root but display base empty and fs base "."
    let mut segment = Segment{haystacks: Vec::new()};
    let md = match fs::metadata(root) {
        Ok(m) => m,
        Err(e) => {
            if !ctx.args.no_messages {
                if total_paths == 1 {
                    stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", root.to_string_lossy(), root.to_string_lossy(), e));
                } else {
                    stderr_write(&format!("rg: {}: {}\n", root.to_string_lossy(), e));
                }
            }
            ctx.had_error = true;
            return segment;
        }
    };
    if !md.is_dir() {
        segment.haystacks.push(Haystack{display: root.to_path_buf(), fs_path: Some(root.to_path_buf()), is_stdin:false, explicit_file:true});
        return segment;
    }
    let root_abs = absolute_lexical(root);
    let anchor_dir_abs = root_abs.clone();
    let mut parent_has_git = false;
    let mut base_rules: Vec<Rule> = Vec::new();
    base_rules.extend(ctx.global_rules.clone());
    base_rules.extend(ctx.custom_rules.clone());
    {
        let mut ancestors: Vec<PathBuf> = Vec::new();
        let mut cur = anchor_dir_abs.parent().map(|p| p.to_path_buf());
        while let Some(p) = cur { ancestors.push(p.clone()); cur = p.parent().map(|x| x.to_path_buf()); }
        ancestors.reverse();
        let mut cumulative_git = false;
        for anc in &ancestors {
            let marker = contains_git_marker(anc);
            cumulative_git = cumulative_git || marker;
            if !ctx.args.no_ignore_parent {
                base_rules.extend(ctx.load_dir_ignore_files(anc, anc, cumulative_git));
            }
        }
        parent_has_git = cumulative_git;
    }
    let root_dev = { #[cfg(unix)] { md.dev() } #[cfg(not(unix))] { 0 } };
    let mut ancestors_dirs: Vec<(u64,u64,PathBuf)> = Vec::new();
    { #[cfg(unix)] { ancestors_dirs.push((md.dev(), md.ino(), PathBuf::from("./"))); } }
    let display_base: PathBuf = PathBuf::new();
    let fs_base: PathBuf = root.to_path_buf();
    let mut rules = base_rules;
    visit_dir(ctx, &fs_base, &display_base, 0, parent_has_git, root_dev, &mut ancestors_dirs, &mut rules, &mut segment, root);
    segment
}

fn visit_dir(ctx: &mut WalkContext, fs_dir: &Path, display_dir: &Path, depth: u64, parent_has_git: bool, root_dev: u64, ancestors: &mut Vec<(u64,u64,PathBuf)>, rules: &mut Vec<Rule>, segment: &mut Segment, root_for_error: &Path) {
    // load ignore for this dir
    let has_marker = contains_git_marker(fs_dir);
    let in_git = parent_has_git || has_marker;
    let added_rules = ctx.load_dir_ignore_files(fs_dir, fs_dir, in_git);
    let rules_len_before = rules.len();
    rules.extend(added_rules);
    // read dir
    let read = match fs::read_dir(fs_dir) {
        Ok(r) => r,
        Err(e) => {
            if !ctx.args.no_messages {
                let disp = if display_dir.as_os_str().is_empty() { PathBuf::from(".") } else { display_dir.to_path_buf() };
                stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", disp.to_string_lossy(), disp.to_string_lossy(), e));
            }
            ctx.had_error = true;
            rules.truncate(rules_len_before);
            return;
        }
    };
    let entries: Vec<_> = read.collect();
    for entry_res in entries {
        let entry = match entry_res {
            Ok(en) => en,
            Err(e) => {
                if !ctx.args.no_messages {
                    stderr_write(&format!("rg: {}: {}\n", fs_dir.to_string_lossy(), e));
                }
                ctx.had_error = true; continue;
            }
        };
        let name = entry.file_name();
        let entry_fs = entry.path(); // fs_dir join name (for implicit root fs_dir is ".", path is ./name)
        let entry_display = if display_dir.as_os_str().is_empty() { PathBuf::from(&name) } else { display_dir.join(&name) };
        let entry_depth = depth + 1;
        if let Some(maxd) = ctx.args.max_depth { if entry_depth > maxd { continue; } }
        // symlink metadata
        let sym_md = match entry.metadata() {
            // DirEntry::metadata follows? In Rust, DirEntry::metadata does NOT traverse symlinks (equivalent symlink_metadata)
            Ok(m) => m,
            Err(_) => continue,
        };
        let is_symlink = sym_md.file_type().is_symlink();
        // determine effective type
        let (is_dir_eff, is_file_eff, eff_md_opt) = if is_symlink {
            if !ctx.args.follow { continue; }
            match fs::metadata(&entry_fs) {
                Ok(m) => (m.is_dir(), m.is_file(), Some(m)),
                Err(e) => {
                    if !ctx.args.no_messages {
                        stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", entry_display.to_string_lossy(), entry_display.to_string_lossy(), e));
                    }
                    ctx.had_error = true; continue;
                }
            }
        } else {
            // DirEntry metadata is symlink_metadata-like; for non-symlink is_dir/is_file reflect target
            let ft = sym_md.file_type();
            (ft.is_dir(), ft.is_file(), Some(sym_md.clone()))
        };
        if !is_dir_eff && !is_file_eff { continue; }
        // absolute lexical for matching
        let cand_abs = absolute_lexical(&entry_fs);
        let match_path = match_path_for_candidate(ctx, &cand_abs);
        // filters
        let override_dec = last_override_decision(ctx.filters, &match_path, is_dir_eff);
        if override_dec == Some(false) { continue; }
        let ignore_dec = eval_ignore_rules(rules, &cand_abs, is_dir_eff, in_git);
        if override_dec != Some(true) && ignore_dec == Some(false) { continue; }
        let mut bypass_hidden = false;
        if override_dec == Some(true) { bypass_hidden = true; }
        if ignore_dec == Some(true) { bypass_hidden = true; }
        // type decision for files (and for dir hidden bypass only)
        let basename_bytes: Vec<u8> = {
            #[cfg(unix)] { name.as_bytes().to_vec() }
            #[cfg(not(unix))] { name.to_string_lossy().as_bytes().to_vec() }
        };
        let (type_allowed, type_white) = type_decision(ctx.filters, &basename_bytes);
        if type_white { /* could bypass hidden for file/dir */ }
        let hidden = is_hidden_name(&name);
        if is_dir_eff {
            if hidden && !bypass_hidden && !type_white {
                // type_white for dir computed against dirname; if name matches type glob, allow? but type decision for dir with selected types would require... keep as bypass only when type_white and has_type_select? 
                // If type is blacklist mode, type_white is false.
                // So hidden check:
                // already bypass_hidden false
                continue;
            }
            if hidden && !bypass_hidden && type_white {
                // allowed due to type whitelist
            } else if hidden && !bypass_hidden && !type_white {
                continue;
            }
            // one-file-system
            #[cfg(unix)]
            if ctx.args.one_file_system {
                if let Some(m) = &eff_md_opt { if m.dev() != root_dev { continue; } }
            }
            // loop detection (when following symlinks, or generally)
            let mut loop_found: Option<PathBuf> = None;
            #[cfg(unix)]
            if let Some(m) = &eff_md_opt {
                for (dev, ino, disp) in ancestors.iter() {
                    if *dev == m.dev() && *ino == m.ino() { loop_found = Some(disp.clone()); break; }
                }
            }
            if let Some(anc_disp) = loop_found {
                if !ctx.args.no_messages {
                    stderr_write(&format!("rg: File system loop found: {} points to an ancestor {}\n", entry_display.to_string_lossy(), anc_disp.to_string_lossy()));
                }
                ctx.had_error = true; continue;
            }
            // push ancestor and recurse
            #[cfg(unix)]
            if let Some(m) = &eff_md_opt { ancestors.push((m.dev(), m.ino(), entry_display.clone())); }
            visit_dir(ctx, &entry_fs, &entry_display, entry_depth, in_git, root_dev, ancestors, rules, segment, root_for_error);
            #[cfg(unix)] { ancestors.pop(); }
        } else if is_file_eff {
            if override_dec == Some(true) {
                // bypass ignore/type/hidden, but still max_filesize
                if let Some(limit) = ctx.args.max_filesize { if let Some(m) = &eff_md_opt { if m.len() > limit { continue; } } }
                segment.haystacks.push(Haystack{display: entry_display, fs_path: Some(entry_fs), is_stdin:false, explicit_file:false});
                continue;
            }
            if has_override_whitelist(ctx.filters) && override_dec.is_none() { continue; }
            // ignore already handled
            if !type_allowed { continue; }
            if hidden && !bypass_hidden && !type_white { continue; }
            if let Some(limit) = ctx.args.max_filesize { if let Some(m) = &eff_md_opt { if m.len() > limit { continue; } } }
            segment.haystacks.push(Haystack{display: entry_display, fs_path: Some(entry_fs), is_stdin:false, explicit_file:false});
        }
    }
    rules.truncate(rules_len_before);
}
RS
"}

actions.command:
cat > src/walker.rs <<'RS'
use std::collections::HashSet;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
#[cfg(unix)] use std::os::unix::fs::{MetadataExt, FileTypeExt};
#[cfg(unix)] use std::os::unix::ffi::OsStrExt;

use crate::flags::{Args, TypeOp};
use crate::filetypes::{Types, build_type_glob};
use crate::glob::{build_gitignore_glob, build_override_glob, Glob, GlobError};

#[derive(Debug, Clone)]
pub struct Haystack {
    pub display: PathBuf,
    pub fs_path: Option<PathBuf>,
    pub is_stdin: bool,
    pub explicit_file: bool,
}

#[derive(Debug)]
pub struct Segment { pub haystacks: Vec<Haystack> }

#[derive(Debug, Clone)]
struct Rule {
    base_abs: PathBuf,
    category: u8,
    depth: usize,
    order: usize,
    glob: Glob,
    negated: bool,
    dir_only: bool,
    requires_git: bool,
}

pub struct Filters {
    pub overrides: Vec<OverrideEntry>,
    pub type_entries: Vec<(Glob, bool)>, // whitelist=true
    pub has_type_select: bool,
}

pub struct OverrideEntry { pub glob: Glob, pub blacklist: bool, pub dir_only: bool }

pub fn format_glob_error(original: &str, e: &GlobError) -> String {
    format!("rg: error parsing glob '{}': {}\n", original, e.0)
}

pub fn build_types(args: &Args) -> Result<Types, String> {
    let mut types = Types::defaults();
    for op in &args.type_ops {
        match op {
            TypeOp::Add(spec) => types.apply_add(spec)?,
            TypeOp::Clear(name) => types.apply_clear(name),
        }
    }
    Ok(types)
}

pub fn build_filters(args: &Args, types: &Types) -> Result<Filters, String> {
    // validate types mentioned and compile type entries in mention-order
    let mut type_entries = Vec::new();
    let mut has_select = false;
    for (name, is_select) in &args.type_mentions {
        if *is_select { has_select = true; }
        if name == "all" {
            // expand all types in sorted map order
            for (tname, globs) in &types.map {
                if globs.is_empty() { continue; }
                for g in globs {
                    let glob = build_type_glob(g).map_err(|e| format_glob_error(g, &e))?;
                    type_entries.push((glob, *is_select));
                    let _ = tname;
                }
            }
        } else {
            if !types.has_type(name) {
                return Err(format!("rg: unrecognized file type: {}\n", name));
            }
            if let Some(globs) = types.map.get(name) {
                for g in globs {
                    let glob = build_type_glob(g).map_err(|e| format_glob_error(g, &e))?;
                    type_entries.push((glob, *is_select));
                }
            }
        }
    }
    // override globs
    let mut overrides = Vec::new();
    for (pat, is_iglob) in &args.overrides {
        let (blacklist, stripped, dir_only) = parse_override_pattern(pat);
        let case_i = *is_iglob || args.glob_case_insensitive;
        let glob = build_override_glob(&stripped, case_i).map_err(|e| format_glob_error(pat, &e))?;
        overrides.push(OverrideEntry{glob, blacklist, dir_only});
    }
    Ok(Filters{overrides, type_entries, has_type_select: has_select})
}

fn parse_override_pattern(pat: &str) -> (bool, String, bool) {
    let mut blacklist = false;
    let mut s = pat.to_string();
    if let Some(rest) = s.strip_prefix('!') { blacklist = true; s = rest.to_string(); }
    else if let Some(rest) = s.strip_prefix("\\!") { s = format!("!{}", rest); }
    let mut dir_only = false;
    if s.ends_with('/') && !s.ends_with("\\/") { dir_only = true; s.pop(); }
    (blacklist, s, dir_only)
}

fn stderr_write(s: &str) {
    let _ = io::stderr().write_all(s.as_bytes());
}

pub struct WalkContext<'a> {
    pub args: &'a Args,
    pub filters: &'a Filters,
    pub had_error: bool,
    pub global_rules: Vec<Rule>,
    pub custom_rules: Vec<Rule>,
    next_order: usize,
    pub cwd_abs: PathBuf,
}

impl<'a> WalkContext<'a> {
    pub fn new(args: &'a Args, filters: &'a Filters) -> Self {
        let cwd_abs = absolute_lexical(&std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let mut ctx = WalkContext{ args, filters, had_error:false, global_rules:Vec::new(), custom_rules:Vec::new(), next_order:0, cwd_abs: cwd_abs.clone() };
        // custom ignore files
        if !args.no_ignore_files {
            for path in &args.ignore_files_custom {
                ctx.load_custom_ignore_file(path);
            }
        }
        // global
        if !args.no_ignore_global && !args.no_ignore_vcs {
            if let Some(gp) = global_gitignore_path() {
                if gp.exists() {
                    ctx.load_global_file(&gp, cwd_abs.clone());
                }
            }
        }
        ctx
    }

    fn load_custom_ignore_file(&mut self, path: &Path) {
        match fs::read(path) {
            Ok(content) => {
                let display = path.to_path_buf();
                self.parse_ignore_content(&content, &display, self.cwd_abs.clone(), 0, false);
            }
            Err(e) => {
                if !self.args.no_messages {
                    stderr_write(&format!("rg: {}: {}\n", path.to_string_lossy(), e));
                }
            }
        }
    }
    fn load_global_file(&mut self, path: &Path, cwd: PathBuf) {
        if let Ok(content) = fs::read(path) {
            let disp = path.to_path_buf();
            // global rules require git context
            let rules_before = self.global_rules.len();
            let mut tmp_rules = Vec::new();
            // parse into tmp via helper using self parser? We'll parse directly by temporarily swapping
            // Simpler: collect rules using parse function that returns rules
            let parsed = self.parse_rules_from_content(&content, &disp, cwd, 1, true);
            tmp_rules.extend(parsed);
            self.global_rules.extend(tmp_rules);
            let _ = rules_before;
        }
    }

    fn parse_ignore_content(&mut self, content: &[u8], display_path: &Path, base_abs: PathBuf, category: u8, requires_git: bool) {
        let rules = self.parse_rules_from_content(content, display_path, base_abs, category, requires_git);
        // dispatch to appropriate storage based on category? This loader is used for custom (goes to custom_rules) and directory rules (returned separately elsewhere)
        // For custom only call site here.
        self.custom_rules.extend(rules);
    }

    fn parse_rules_from_content(&mut self, content: &[u8], display_path: &Path, base_abs: PathBuf, category: u8, requires_git: bool) -> Vec<Rule> {
        let mut rules = Vec::new();
        let text = String::from_utf8_lossy(content);
        for (idx, raw_line) in text.lines().enumerate() {
            let line_no = idx + 1;
            let line_original = raw_line;
            let mut line = raw_line.to_string();
            // gitignore parsing
            if line.trim().is_empty() { continue; }
            // comment
            let mut negated = false;
            let mut pat: String;
            if let Some(rest) = line.strip_prefix("\\#") {
                pat = format!("#{}", rest);
            } else if line.starts_with('#') {
                continue;
            } else if let Some(rest) = line.strip_prefix("\\!") {
                pat = format!("!{}", rest);
            } else if let Some(rest) = line.strip_prefix('!') {
                negated = true; pat = rest.to_string();
            } else { pat = line.clone(); }
            // trailing slash dir_only
            let mut dir_only = false;
            if pat.ends_with('/') && !pat.ends_with("\\/") { dir_only = true; pat.pop(); }
            // trailing spaces (unescaped)
            loop {
                if pat.ends_with(' ') {
                    if pat.ends_with("\\ ") { pat = format!("{} ", &pat[..pat.len()-2]); break; } else { pat.pop(); }
                } else { break; }
            }
            if pat.is_empty() { continue; }
            // build glob
            match build_gitignore_glob(&pat, self.args.ignore_file_case_insensitive) {
                Ok(glob) => {
                    let depth = base_abs.components().count();
                    let order = self.next_order; self.next_order += 1;
                    rules.push(Rule{base_abs: base_abs.clone(), category, depth, order, glob, negated, dir_only, requires_git});
                }
                Err(e) => {
                    if !self.args.no_ignore_messages && !self.args.no_messages {
                        stderr_write(&format!("rg: {}: line {}: error parsing glob '{}': {}\n", display_path.to_string_lossy(), line_no, line_original, e.0));
                    }
                }
            }
            let _ = &mut line;
        }
        rules
    }

    fn load_dir_ignore_files(&mut self, dir_fs: &Path, dir_display_base: &Path, in_git: bool) -> Vec<Rule> {
        // dir_display_base is the filesystem path to use for opening/display (same as dir_fs generally except implicit root is ".")
        let mut out = Vec::new();
        // gitignore
        if !self.args.no_ignore_vcs {
            if in_git || !self.args.require_git {
                let p = dir_fs.join(".gitignore");
                if let Ok(content) = fs::read(&p) {
                    let base = absolute_lexical(&dir_fs.to_path_buf());
                    out.extend(self.parse_rules_from_content(&content, &p, base, 3, false));
                }
            }
        }
        // exclude, if this directory is a repo root (contains .git)
        if !self.args.no_ignore_exclude && !self.args.no_ignore_vcs {
            if let Some(exclude_path) = git_exclude_path(dir_fs) {
                if let Ok(content) = fs::read(&exclude_path) {
                    let base = absolute_lexical(&dir_fs.to_path_buf());
                    out.extend(self.parse_rules_from_content(&content, &exclude_path, base, 2, false));
                }
            }
        }
        if !self.args.no_ignore_dot {
            for (fname, cat) in [(".ignore",4u8),(".rgignore",5u8)] {
                let p = dir_fs.join(fname);
                if let Ok(content) = fs::read(&p) {
                    let base = absolute_lexical(&dir_fs.to_path_buf());
                    out.extend(self.parse_rules_from_content(&content, &p, base, cat, false));
                }
            }
        }
        let _ = dir_display_base;
        out
    }
}

fn git_exclude_path(dir_fs: &Path) -> Option<PathBuf> {
    let git_path = dir_fs.join(".git");
    let md = fs::symlink_metadata(&git_path).ok()?;
    if md.is_dir() {
        Some(git_path.join("info").join("exclude"))
    } else if md.is_file() {
        // parse gitdir: <path>
        if let Ok(content) = fs::read_to_string(&git_path) {
            for line in content.lines() {
                if let Some(rest) = line.strip_prefix("gitdir:") {
                    let p = rest.trim();
                    let gitdir = if Path::new(p).is_absolute() { PathBuf::from(p) } else { dir_fs.join(p) };
                    return Some(gitdir.join("info").join("exclude"));
                }
            }
        }
        None
    } else { None }
}

pub fn contains_git_marker(dir_fs: &Path) -> bool {
    dir_fs.join(".git").symlink_metadata().is_ok()
}

fn global_gitignore_path() -> Option<PathBuf> {
    let home = std::env::var_os("HOME").map(PathBuf::from).or_else(|| std::env::home_dir())?;
    // config lookup
    let xdg_config_home = std::env::var_os("XDG_CONFIG_HOME").map(PathBuf::from).unwrap_or_else(|| home.join(".config"));
    // read config files: XDG git/config then HOME/.gitconfig, later overrides
    let mut excludes: Option<PathBuf> = None;
    for cfg in [xdg_config_home.join("git").join("config"), home.join(".gitconfig")] {
        if let Ok(content) = fs::read_to_string(&cfg) {
            if let Some(p) = parse_git_config_excludes(&content, &home) { excludes = Some(p); }
        }
    }
    if let Some(p) = excludes { return Some(p); }
    Some(xdg_config_home.join("git").join("ignore"))
}

fn parse_git_config_excludes(content: &str, home: &Path) -> Option<PathBuf> {
    let mut in_core = false;
    let mut result = None;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            in_core = t.to_ascii_lowercase().starts_with("[core");
            continue;
        }
        if in_core {
            if let Some((k,v)) = t.split_once('=') {
                if k.trim().to_ascii_lowercase() == "excludesfile" {
                    let mut val = v.trim().to_string();
                    if val.starts_with("~/") { result = Some(home.join(&val[2..])); } else { result = Some(PathBuf::from(val)); }
                }
            }
        }
    }
    result
}

pub fn absolute_lexical(p: &Path) -> PathBuf {
    let abs = if p.is_absolute() { p.to_path_buf() } else {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(p)
    };
    normalize_lexical(&abs)
}
pub fn normalize_lexical(p: &Path) -> PathBuf {
    use std::path::Component;
    let mut out = PathBuf::new();
    for comp in p.components() {
        match comp {
            Component::CurDir => {}
            Component::ParentDir => { out.pop(); }
            c => out.push(c.as_os_str()),
        }
    }
    if out.as_os_str().is_empty() { out.push("/"); }
    out
}
fn relative_match_string(base_abs: &Path, cand_abs: &Path) -> String {
    // produce path relative to base using lexical components with ../ if needed
    let base_comps: Vec<String> = base_abs.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    let cand_comps: Vec<String> = cand_abs.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    let mut i = 0;
    while i < base_comps.len() && i < cand_comps.len() && base_comps[i]==cand_comps[i] { i += 1; }
    let mut parts = Vec::new();
    for _ in i..base_comps.len() { parts.push("..".to_string()); }
    for c in &cand_comps[i..] { parts.push(c.clone()); }
    parts.join("/")
}

fn eval_ignore_rules(rules: &[Rule], cand_abs: &Path, is_dir: bool, in_git: bool) -> Option<bool> {
    // return Some(true) if whitelist wins, Some(false) if ignore wins, None if no match (using bool whitelist indicator)
    // We'll return enum via Option<bool> where true = whitelisted, false = ignored
    let mut best: Option<(u8, usize, usize, bool)> = None; // cat,depth,order,negated
    for r in rules {
        if r.requires_git && !in_git { continue; }
        if r.dir_only && !is_dir {
            // need to consider ancestor directories below
            // matching below will handle ancestors
        }
        let rel = relative_match_string(&r.base_abs, cand_abs);
        if rel.is_empty() { continue; }
        // candidates to test: rel itself and ancestor prefixes (for patterns matching a parent directory)
        let comps: Vec<&str> = rel.split('/').collect();
        let mut candidate_strings: Vec<String> = Vec::new();
        if !r.dir_only || is_dir {
            candidate_strings.push(rel.clone());
        }
        // ancestors
        for k in 1..comps.len() {
            candidate_strings.push(comps[..k].join("/"));
        }
        let mut matched = false;
        for cand_str in &candidate_strings {
            // for ancestor candidate, it is a directory, so dir_only OK
            if r.glob.is_match(cand_str.as_bytes()) { matched = true; break; }
        }
        if matched {
            let key = (r.category, r.depth, r.order, r.negated);
            if best.map(|b| (key.0, key.1, key.2) >= (b.0, b.1, b.2)).unwrap_or(true) {
                best = Some(key);
            }
        }
    }
    best.map(|b| b.3)
}

fn last_override_decision(filters: &Filters, match_path: &str, is_dir: bool) -> Option<bool> {
    // Some(true) whitelist, Some(false) blacklist, None no match
    let mut last: Option<bool> = None;
    for e in &filters.overrides {
        if e.dir_only && !is_dir { continue; }
        if e.glob.is_match(match_path.as_bytes()) { last = Some(!e.blacklist); }
    }
    last
}
fn has_override_whitelist(filters: &Filters) -> bool { filters.overrides.iter().any(|e| !e.blacklist) }

fn type_decision(filters: &Filters, basename_bytes: &[u8]) -> (bool, bool) {
    // return (allowed, whitelist_matched)
    let mut last: Option<bool> = None;
    for (glob, is_white) in &filters.type_entries {
        if glob.is_match(basename_bytes) { last = Some(*is_white); }
    }
    match last {
        Some(true) => (true, true),
        Some(false) => (false, false),
        None => {
            if filters.has_type_select { (false, false) } else { (true, false) }
        }
    }
}

pub fn match_path_for_candidate(ctx: &WalkContext, cand_abs: &Path) -> String {
    relative_match_string(&ctx.cwd_abs, cand_abs)
}

pub fn is_hidden_name(name: &std::ffi::OsStr) -> bool {
    #[cfg(unix)] { name.as_bytes().first() == Some(&b'.') }
    #[cfg(not(unix))] { name.to_string_lossy().starts_with('.') }
}

// Walker for one filesystem root path.
// Returns segment haystacks; errors have been printed and ctx.had_error set.
pub fn walk_root(ctx: &mut WalkContext, root: &Path, total_paths: usize) -> Segment {
    let mut segment = Segment{haystacks: Vec::new()};
    // metadata following links
    let md = match fs::metadata(root) {
        Ok(m) => m,
        Err(e) => {
            if !ctx.args.no_messages {
                if total_paths == 1 {
                    stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", root.to_string_lossy(), root.to_string_lossy(), e));
                } else {
                    stderr_write(&format!("rg: {}: {}\n", root.to_string_lossy(), e));
                }
            }
            ctx.had_error = true;
            return segment;
        }
    };
    if !md.is_dir() {
        segment.haystacks.push(Haystack{display: root.to_path_buf(), fs_path: Some(root.to_path_buf()), is_stdin:false, explicit_file:true});
        return segment;
    }
    // directory traversal
    let root_abs = absolute_lexical(root);
    let anchor_dir_abs = root_abs.clone();
    // compute ancestors above anchor and parent git status
    let mut parent_has_git = false;
    let mut base_rules: Vec<Rule> = Vec::new();
    base_rules.extend(ctx.global_rules.clone());
    base_rules.extend(ctx.custom_rules.clone());
    // ancestors
    {
        // build list of ancestor directories (strictly above anchor)
        let mut ancestors: Vec<PathBuf> = Vec::new();
        let mut cur = anchor_dir_abs.parent().map(|p| p.to_path_buf());
        while let Some(p) = cur {
            ancestors.push(p.clone());
            cur = p.parent().map(|x| x.to_path_buf());
        }
        ancestors.reverse(); // top down
        let mut cumulative_git = false;
        for anc in &ancestors {
            let marker = contains_git_marker(anc);
            cumulative_git = cumulative_git || marker;
            if !ctx.args.no_ignore_parent {
                // load ignore files of ancestor (as if entering it, but not directory itself that we traverse below)
                // We need load using its own dir path (absolute)
                // Construct temporary loader rules:
                let anc_rules = ctx.load_dir_ignore_files(anc, anc, cumulative_git);
                base_rules.extend(anc_rules);
                // load_dir_ignore_files already loaded exclude if marker, but for ancestors that are repos their exclude was loaded there
            }
        }
        parent_has_git = cumulative_git;
    }
    // device of root for one-file-system
    let root_dev = {
        #[cfg(unix)] { md.dev() }
        #[cfg(not(unix))] { 0 }
    };
    let mut ancestors_dirs: Vec<(u64,u64,PathBuf)> = Vec::new();
    {
        #[cfg(unix)] { ancestors_dirs.push((md.dev(), md.ino(), root.to_path_buf())); }
    }
    // display base and fs base
    let display_base: PathBuf = if is_implicit_root(root) {
        PathBuf::new() // empty
    } else {
        root.to_path_buf()
    };
    let fs_base: PathBuf = root.to_path_buf();
    // recursive
    let mut rules = base_rules;
    visit_dir(ctx, &fs_base, &display_base, 0, parent_has_git, root_dev, &mut ancestors_dirs, &mut rules, &mut segment, root);
    segment
}

fn is_implicit_root(root: &Path) -> bool {
    // The caller signals implicit root by passing Path::new("\0IMPLICIT") placeholder - not used here.
    // Instead, main passes root "." but marks? We'll detect in main by separate function walk_root_implicit.
    false
}

pub fn walk_root_with_display(ctx: &mut WalkContext, root: &Path, total_paths: usize, implicit: bool) -> Segment {
    if !implicit { return walk_root(ctx, root, total_paths); }
    // implicit version duplicates walk_root but display base empty and fs base "."
    let mut segment = Segment{haystacks: Vec::new()};
    let md = match fs::metadata(root) {
        Ok(m) => m,
        Err(e) => {
            if !ctx.args.no_messages {
                if total_paths == 1 {
                    stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", root.to_string_lossy(), root.to_string_lossy(), e));
                } else {
                    stderr_write(&format!("rg: {}: {}\n", root.to_string_lossy(), e));
                }
            }
            ctx.had_error = true;
            return segment;
        }
    };
    if !md.is_dir() {
        segment.haystacks.push(Haystack{display: root.to_path_buf(), fs_path: Some(root.to_path_buf()), is_stdin:false, explicit_file:true});
        return segment;
    }
    let root_abs = absolute_lexical(root);
    let anchor_dir_abs = root_abs.clone();
    let mut parent_has_git = false;
    let mut base_rules: Vec<Rule> = Vec::new();
    base_rules.extend(ctx.global_rules.clone());
    base_rules.extend(ctx.custom_rules.clone());
    {
        let mut ancestors: Vec<PathBuf> = Vec::new();
        let mut cur = anchor_dir_abs.parent().map(|p| p.to_path_buf());
        while let Some(p) = cur { ancestors.push(p.clone()); cur = p.parent().map(|x| x.to_path_buf()); }
        ancestors.reverse();
        let mut cumulative_git = false;
        for anc in &ancestors {
            let marker = contains_git_marker(anc);
            cumulative_git = cumulative_git || marker;
            if !ctx.args.no_ignore_parent {
                base_rules.extend(ctx.load_dir_ignore_files(anc, anc, cumulative_git));
            }
        }
        parent_has_git = cumulative_git;
    }
    let root_dev = { #[cfg(unix)] { md.dev() } #[cfg(not(unix))] { 0 } };
    let mut ancestors_dirs: Vec<(u64,u64,PathBuf)> = Vec::new();
    { #[cfg(unix)] { ancestors_dirs.push((md.dev(), md.ino(), PathBuf::from("./"))); } }
    let display_base: PathBuf = PathBuf::new();
    let fs_base: PathBuf = root.to_path_buf();
    let mut rules = base_rules;
    visit_dir(ctx, &fs_base, &display_base, 0, parent_has_git, root_dev, &mut ancestors_dirs, &mut rules, &mut segment, root);
    segment
}

fn visit_dir(ctx: &mut WalkContext, fs_dir: &Path, display_dir: &Path, depth: u64, parent_has_git: bool, root_dev: u64, ancestors: &mut Vec<(u64,u64,PathBuf)>, rules: &mut Vec<Rule>, segment: &mut Segment, root_for_error: &Path) {
    // load ignore for this dir
    let has_marker = contains_git_marker(fs_dir);
    let in_git = parent_has_git || has_marker;
    let added_rules = ctx.load_dir_ignore_files(fs_dir, fs_dir, in_git);
    let rules_len_before = rules.len();
    rules.extend(added_rules);
    // read dir
    let read = match fs::read_dir(fs_dir) {
        Ok(r) => r,
        Err(e) => {
            if !ctx.args.no_messages {
                let disp = if display_dir.as_os_str().is_empty() { PathBuf::from(".") } else { display_dir.to_path_buf() };
                stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", disp.to_string_lossy(), disp.to_string_lossy(), e));
            }
            ctx.had_error = true;
            rules.truncate(rules_len_before);
            return;
        }
    };
    let entries: Vec<_> = read.collect();
    for entry_res in entries {
        let entry = match entry_res {
            Ok(en) => en,
            Err(e) => {
                if !ctx.args.no_messages {
                    stderr_write(&format!("rg: {}: {}\n", fs_dir.to_string_lossy(), e));
                }
                ctx.had_error = true; continue;
            }
        };
        let name = entry.file_name();
        let entry_fs = entry.path(); // fs_dir join name (for implicit root fs_dir is ".", path is ./name)
        let entry_display = if display_dir.as_os_str().is_empty() { PathBuf::from(&name) } else { display_dir.join(&name) };
        let entry_depth = depth + 1;
        if let Some(maxd) = ctx.args.max_depth { if entry_depth > maxd { continue; } }
        // symlink metadata
        let sym_md = match entry.metadata() {
            // DirEntry::metadata follows? In Rust, DirEntry::metadata does NOT traverse symlinks (equivalent symlink_metadata)
            Ok(m) => m,
            Err(_) => continue,
        };
        let is_symlink = sym_md.file_type().is_symlink();
        // determine effective type
        let (is_dir_eff, is_file_eff, eff_md_opt) = if is_symlink {
            if !ctx.args.follow { continue; }
            match fs::metadata(&entry_fs) {
                Ok(m) => (m.is_dir(), m.is_file(), Some(m)),
                Err(e) => {
                    if !ctx.args.no_messages {
                        stderr_write(&format!("rg: {}: IO error for operation on {}: {}\n", entry_display.to_string_lossy(), entry_display.to_string_lossy(), e));
                    }
                    ctx.had_error = true; continue;
                }
            }
        } else {
            // DirEntry metadata is symlink_metadata-like; for non-symlink is_dir/is_file reflect target
            let ft = sym_md.file_type();
            (ft.is_dir(), ft.is_file(), Some(sym_md.clone()))
        };
        if !is_dir_eff && !is_file_eff { continue; }
        // absolute lexical for matching
        let cand_abs = absolute_lexical(&entry_fs);
        let match_path = match_path_for_candidate(ctx, &cand_abs);
        // filters
        let override_dec = last_override_decision(ctx.filters, &match_path, is_dir_eff);
        if override_dec == Some(false) { continue; }
        let ignore_dec = eval_ignore_rules(rules, &cand_abs, is_dir_eff, in_git);
        if override_dec != Some(true) && ignore_dec == Some(false) { continue; }
        let mut bypass_hidden = false;
        if override_dec == Some(true) { bypass_hidden = true; }
        if ignore_dec == Some(true) { bypass_hidden = true; }
        // type decision for files (and for dir hidden bypass only)
        let basename_bytes: Vec<u8> = {
            #[cfg(unix)] { name.as_bytes().to_vec() }
            #[cfg(not(unix))] { name.to_string_lossy().as_bytes().to_vec() }
        };
        let (type_allowed, type_white) = type_decision(ctx.filters, &basename_bytes);
        if type_white { /* could bypass hidden for file/dir */ }
        let hidden = is_hidden_name(&name);
        if is_dir_eff {
            if hidden && !bypass_hidden && !type_white {
                // type_white for dir computed against dirname; if name matches type glob, allow? but type decision for dir with selected types would require... keep as bypass only when type_white and has_type_select? 
                // If type is blacklist mode, type_white is false.
                // So hidden check:
                // already bypass_hidden false
                continue;
            }
            if hidden && !bypass_hidden && type_white {
                // allowed due to type whitelist
            } else if hidden && !bypass_hidden && !type_white {
                continue;
            }
            // one-file-system
            #[cfg(unix)]
            if ctx.args.one_file_system {
                if let Some(m) = &eff_md_opt { if m.dev() != root_dev { continue; } }
            }
            // loop detection (when following symlinks, or generally)
            let mut loop_found: Option<PathBuf> = None;
            #[cfg(unix)]
            if let Some(m) = &eff_md_opt {
                for (dev, ino, disp) in ancestors.iter() {
                    if *dev == m.dev() && *ino == m.ino() { loop_found = Some(disp.clone()); break; }
                }
            }
            if let Some(anc_disp) = loop_found {
                if !ctx.args.no_messages {
                    stderr_write(&format!("rg: File system loop found: {} points to an ancestor {}\n", entry_display.to_string_lossy(), anc_disp.to_string_lossy()));
                }
                ctx.had_error = true; continue;
            }
            // push ancestor and recurse
            #[cfg(unix)]
            if let Some(m) = &eff_md_opt { ancestors.push((m.dev(), m.ino(), entry_display.clone())); }
            visit_dir(ctx, &entry_fs, &entry_display, entry_depth, in_git, root_dev, ancestors, rules, segment, root_for_error);
            #[cfg(unix)] { ancestors.pop(); }
        } else if is_file_eff {
            if override_dec == Some(true) {
                // bypass ignore/type/hidden, but still max_filesize
                if let Some(limit) = ctx.args.max_filesize { if let Some(m) = &eff_md_opt { if m.len() > limit { continue; } } }
                segment.haystacks.push(Haystack{display: entry_display, fs_path: Some(entry_fs), is_stdin:false, explicit_file:false});
                continue;
            }
            if has_override_whitelist(ctx.filters) && override_dec.is_none() { continue; }
            // ignore already handled
            if !type_allowed { continue; }
            if hidden && !bypass_hidden && !type_white { continue; }
            if let Some(limit) = ctx.args.max_filesize { if let Some(m) = &eff_md_opt { if m.len() > limit { continue; } } }
            segment.haystacks.push(Haystack{display: entry_display, fs_path: Some(entry_fs), is_stdin:false, explicit_file:false});
        }
    }
    rules.truncate(rules_len_before);
}
