#[derive(Debug, Clone)]
pub struct Engine {
    pub regex: Regex,
    pub capture_names: Vec<Option<String>>,
}
pub fn smart_case_insensitive(patterns: &[String]) -> bool {
    // Extract literal chars from patterns (approximation of regex HIR literal analysis)
    let mut has_literal = false; let mut has_upper = false;
    for pat in patterns {
        let chars: Vec<char> = pat.chars().collect();
        let mut i=0;
        let mut in_class=false;
        while i<chars.len() {
            let c=chars[i];
            if c=='\\' && i+1<chars.len() {
                let n=chars[i+1];
                match n {
                    'n'|'r'|'t'|'f'|'v'|'a' => { has_literal=true; i+=2; continue; }
                    'x' => {
                        // \xHH or \x{..}
                        if i+2<chars.len() && chars[i+2]=='{' {
                            if let Some(end)=pat.chars().skip(i+3).position(|ch| ch=='}') { let hex: String=chars[i+3..i+3+end].iter().collect(); if let Ok(v)=u32::from_str_radix(&hex,16) { if let Some(ch)=char::from_u32(v) { has_literal=true; if ch.is_uppercase(){has_upper=true;} } } i = i+3+end+1; continue; } else { i+=2; continue; }
                        } else if i+3<chars.len() { let hex: String=chars[i+2..i+4].iter().collect(); if let Ok(v)=u32::from_str_radix(&hex,16) { if let Some(ch)=char::from_u32(v){ has_literal=true; if ch.is_uppercase(){has_upper=true;} } } i+=4; continue; } else { i+=2; continue; }
                    }
                    'u' => {
                        if i+2<chars.len() && chars[i+2]=='{' {
                            let rest: String = chars[i+3..].iter().collect(); if let Some(end)=rest.find('}') { if let Ok(v)=u32::from_str_radix(&rest[..end],16){ if let Some(ch)=char::from_u32(v){has_literal=true; if ch.is_uppercase(){has_upper=true;}} } i+=3+end+1; continue; }
                        } else if i+5<chars.len() { let hex:String=chars[i+2..i+6].iter().collect(); if let Ok(v)=u32::from_str_radix(&hex,16){ if let Some(ch)=char::from_u32(v){has_literal=true; if ch.is_uppercase(){has_upper=true;}}} i+=6; continue; }
                        i+=2; continue;
                    }
                    'U' => { if i+9<chars.len() { let hex:String=chars[i+2..i+10].iter().collect(); if let Ok(v)=u32::from_str_radix(&hex,16){ if let Some(ch)=char::from_u32(v){has_literal=true; if ch.is_uppercase(){has_upper=true;}}} i+=10; continue; } i+=2; continue; }
                    'p'|'P'|'d'|'D'|'s'|'S'|'w'|'W'|'b'|'B' => { 
                        // skip \p{...}
                        if n=='p' || n=='P' { if i+2<chars.len() && chars[i+2]=='{' { if let Some(pos)=chars[i+3..].iter().position(|&ch| ch=='}'){ i+=3+pos+1; continue; } } }
                        i+=2; continue;
                    }
                    _ => { // escaped literal char
                        has_literal=true; if n.is_uppercase(){has_upper=true;} i+=2; continue;
                    }
                }
            }
            if c=='[' { in_class=true; i+=1; continue; }
            if c==']' { in_class=false; i+=1; continue; }
            if in_class {
                // characters inside class are literals except -,^ etc at special positions
                if c!='^' && c!='-' { has_literal=true; if c.is_uppercase(){has_upper=true;} }
                i+=1; continue;
            }
            match c {
                '.'|'*'|'+'|'?'|'('|')'|'|'|'^'|'$'|'{'|'}' => { i+=1; continue; }
                _ => { has_literal=true; if c.is_uppercase(){has_upper=true;} i+=1; continue; }
            }
        }
    }
    has_literal && !has_upper
}

pub fn pattern_contains_newline(pat: &str, fixed: bool) -> bool {
    if fixed { return pat.contains('\n'); }
    let chars: Vec<char> = pat.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c=='\n' { return true; }
        if c=='\\' && i+1<chars.len() {
            match chars[i+1] {
                'n' => return true,
                'x' => {
                    if i+2<chars.len() && chars[i+2]=='{' {
                        if let Some(pos)=chars[i+3..].iter().position(|&ch| ch=='}') { let hex:String=chars[i+3..i+3+pos].iter().collect(); if u32::from_str_radix(&hex,16).ok()==Some(10){return true;} i+=3+pos+1; continue; }
                    } else if i+3<chars.len() { let hex:String=chars[i+2..i+4].iter().collect(); if u32::from_str_radix(&hex,16).ok()==Some(10){return true;} }
                }
                'u' => {
                    if i+2<chars.len() && chars[i+2]=='{' {
                        if let Some(pos)=chars[i+3..].iter().position(|&ch| ch=='}') { let hex:String=chars[i+3..i+3+pos].iter().collect(); if u32::from_str_radix(&hex,16).ok()==Some(10){return true;} }
                    } else if i+5<chars.len() { let hex:String=chars[i+2..i+6].iter().collect(); if u32::from_str_radix(&hex,16).ok()==Some(10){return true;} }
                }
                'U' => { if i+9<chars.len(){ let hex:String=chars[i+2..i+10].iter().collect(); if u32::from_str_radix(&hex,16).ok()==Some(10){return true;} } }
                _ => {}
            }
            i+=2; continue;
        }
        i+=1;
    }
    false
}

pub fn build_engine(args: &Args, patterns: &[String]) -> Result<Engine, String> {
    // patterns are raw (not fixed-escaped yet for newline checking handled by caller)
    // Build combined original for errors
    let transformed: Vec<String> = patterns.iter().map(|p| if args.fixed { regex::escape(p) } else { p.clone() }).collect();
    let combined_original = transformed.iter().map(|p| format!("(?:{})", p)).collect::<Vec<_>>().join("|");
    // If engine is pcre2, caller handles before.
    // Build a builder helper
    let make_builder = |pat: &str| -> RegexBuilder {
        let mut b = RegexBuilder::new(pat);
        let insensitive = match args.case { CaseMode::Insensitive => true, CaseMode::Sensitive => false, CaseMode::Smart => smart_case_insensitive(patterns) };
        b.case_insensitive(insensitive);
        b.unicode(args.unicode);
        b.multi_line(args.multiline);
        b.crlf(args.crlf);
        b.dot_matches_new_line(args.multiline && args.multiline_dotall);
        if let Some(limit) = args.regex_size_limit { b.size_limit(limit); } else { b.size_limit(100_000_000); }
        // octal not enabled
        b
    };
    // Untransformed validation build (for errors)
    let validation = make_builder(&combined_original).build();
    if let Err(e) = validation {
        return Err(e.to_string());
    }
    let regex_pat = match args.boundary {
        Boundary::None => combined_original.clone(),
        Boundary::Word => {
            transformed.iter().map(|p| format!("(?:\\b{{start-half}}(?:{})\\b{{end-half}})", p)).collect::<Vec<_>>().join("|")
        }
        Boundary::Line => {
            if args.multiline {
                transformed.iter().map(|p| format!("(?:^(?:{})$)", p)).collect::<Vec<_>>().join("|")
            } else {
                transformed.iter().map(|p| format!("(?:^(?:{})$)", p)).collect::<Vec<_>>().join("|")
            }
        }
    };
    // Wrap word/line pattern in a non-capturing group to keep alternation semantics when combined? Our branches are already each grouped.
    let final_pat = if transformed.len()>1 && args.boundary!=Boundary::None { regex_pat.clone() } else { regex_pat.clone() };
    let re = match make_builder(&final_pat).build() {
        Ok(r) => r,
        Err(e) => return Err(e.to_string()),
    };
    let capture_names = re.capture_names().map(|n| n.map(|s| s.to_string())).collect();
    Ok(Engine{regex: re, capture_names})
}

pub fn expand_replacement(template: &[u8], caps_spans: &[Option<(usize,usize)>], capture_names: &[Option<String>], haystack: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i=0;
    while i<template.len() {
        if template[i]!=b'$' { out.push(template[i]); i+=1; continue; }
        if i+1>=template.len() { out.push(b'$'); i+=1; continue; }
        let nxt = template[i+1];
        if nxt==b'$' { out.push(b'$'); i+=2; continue; }
        if nxt==b'{' {
            if let Some(close_rel)=template[i+2..].iter().position(|&b| b==b'}') {
                let name = &template[i+2..i+2+close_rel];
                let name_str = String::from_utf8_lossy(name).to_string();
                if let Some((s,e))=lookup_capture(&name_str, caps_spans, capture_names) { out.extend_from_slice(&haystack[s..e]); }
                i += 2+close_rel+1; continue;
            } else {
                out.push(b'$'); i+=1; continue;
            }
        }
        // name: alphanumeric underscore
        let mut j=i+1;
        while j<template.len() && (template[j].is_ascii_alphanumeric() || template[j]==b'_' || template[j]==b'.' || template[j]==b'[' || template[j]==b']') {
            // regex crate allows some extra chars in names? Keep alnum_ only for digits/letters; stop at . [ to match usual
            if template[j]==b'.' || template[j]==b'[' || template[j]==b']' { break; }
            j+=1;
        }
        if j==i+1 { // no name char
            out.push(b'$'); i+=1; continue;
        }
        let name_str = String::from_utf8_lossy(&template[i+1..j]).to_string();
        if let Some((s,e))=lookup_capture(&name_str, caps_spans, capture_names) { out.extend_from_slice(&haystack[s..e]); }
        i=j;
    }
    out
}
fn lookup_capture(name: &str, caps: &[Option<(usize,usize)>], names: &[Option<String>]) -> Option<(usize,usize)> {
    if !name.is_empty() && name.bytes().all(|b| b.is_ascii_digit()) {
        if let Ok(idx)=name.parse::<usize>() { if idx<caps.len() { return caps[idx]; } }
        return None;
    }
    for (idx, n) in names.iter().enumerate() {
        if let Some(nn)=n { if nn==name { if idx<caps.len() { return caps[idx]; } } }
    }
    // also if name is a number mixed like 1x, regex crate treats as name and fails
    None
}

// ------------- Style / colors -------------

#[derive(Debug, Clone, PartialEq)]
pub enum ColorVal { Basic(u8), Ansi256(u8), Rgb(u8,u8,u8) }
#[derive(Debug, Clone, Default)]
pub struct Style { pub fg: Option<ColorVal>, pub bg: Option<ColorVal>, pub bold: bool, pub intense: bool, pub underline: bool }
impl Style {
    pub fn render(&self, content: &[u8], colors_enabled: bool, out: &mut Vec<u8>) {
        if !colors_enabled { out.extend_from_slice(content); return; }
        out.extend_from_slice(b"\x1b[0m");
        if self.bold { out.extend_from_slice(b"\x1b[1m"); }
        if self.underline { out.extend_from_slice(b"\x1b[4m"); }
        if let Some(fg)=&self.fg { out.extend_from_slice(color_code(fg, true, self.intense).as_bytes()); }
        if let Some(bg)=&self.bg { out.extend_from_slice(color_code(bg, false, self.intense).as_bytes()); }
        out.extend_from_slice(content);
        out.extend_from_slice(b"\x1b[0m");
    }
}
fn color_code(c: &ColorVal, fg: bool, intense: bool) -> String {
    match c {
        ColorVal::Basic(idx) => {
            if intense { format!("\x1b[{};5;{}m", if fg{38}else{48}, idx+8) } else { format!("\x1b[{}m", (if fg{30}else{40})+idx) }
        }
        ColorVal::Ansi256(n) => format!("\x1b[{};5;{}m", if fg{38}else{48}, n),
        ColorVal::Rgb(r,g,b) => format!("\x1b[{};2;{};{};{}m", if fg{38}else{48}, r,g,b),
    }
}
pub fn parse_color_to_val(v: &str) -> Option<ColorVal> {
    let low=v.to_lowercase();
    let named=[("black",0),("red",1),("green",2),("yellow",3),("blue",4),("magenta",5),("cyan",6),("white",7)];
    for (n,i) in named { if low==n { return Some(ColorVal::Basic(i)); } }
    if v.contains(',') {
        let toks:Vec<&str>=v.split(',').collect(); if toks.len()!=3{return None;}
        let mut vals=[0u8;3]; for (i,t) in toks.iter().enumerate(){ vals[i]=crate::flags::parse_color_num(t)?; } return Some(ColorVal::Rgb(vals[0],vals[1],vals[2]));
    }
    if let Some(hex)=low.strip_prefix("0x") { if let Ok(n)=u8::from_str_radix(hex,16){ return Some(ColorVal::Ansi256(n)); } return None; }
    if let Ok(n)=v.parse::<u8>() { return Some(ColorVal::Ansi256(n)); }
    None
}
#[derive(Debug, Clone)]
pub struct Styles { pub path: Style, pub line: Style, pub column: Style, pub match_: Style }
pub fn resolve_styles(args: &Args) -> Styles {
    let mut s = Styles { path: Style{fg:Some(ColorVal::Basic(5)), ..Default::default()}, line: Style{fg:Some(ColorVal::Basic(2)), ..Default::default()}, column: Style::default(), match_: Style{fg:Some(ColorVal::Basic(1)), bold:true, ..Default::default()} };
    for spec in &args.colors {
        let target = match spec.kind.as_str() { "path"=>&mut s.path, "line"=>&mut s.line, "column"=>&mut s.column, _=>&mut s.match_ };
        match spec.attr.as_str() {
            "none" => *target = Style::default(),
            "fg" => target.fg = parse_color_to_val(&spec.value),
            "bg" => target.bg = parse_color_to_val(&spec.value),
            "style" => {
                match spec.value.to_lowercase().as_str() {
                    "bold"=>target.bold=true, "nobold"=>target.bold=false, "intense"=>target.intense=true, "nointense"=>target.intense=false, "underline"=>target.underline=true, "nounderline"=>target.underline=false, _=>{}
                }
            }
            _=>{}
        }
    }
    s
}

// ------------- Hyperlink -------------
pub fn get_hostname(args: &Args) -> String {
    if let Some(bin)=&args.hostname_bin {
        let out = Command::new(bin).stdout(Stdio::piped()).stderr(Stdio::null()).output();
        if let Ok(o)=out {
            let s=String::from_utf8_lossy(&o.stdout).trim().to_string();
            if !s.is_empty() { return s; }
        }
    }
    if let Ok(content)=std::fs::read_to_string("/proc/sys/kernel/hostname") { return content.trim().to_string(); }
    String::new()
}
pub fn hyperlink_url(format: &str, args: &Args, hostname: &str, display_path: &Path, line_num: Option<usize>, col: Option<usize>) -> Option<String> {
    if format.is_empty() { return None; }
    // path must become absolute
    let abs = crate::walker::absolute_lexical(display_path);
    let path_str = abs.to_string_lossy().to_string();
    let encoded = percent_encode_path(&path_str);
    let line_val = line_num.unwrap_or(1).to_string();
    let col_val = col.unwrap_or(1).to_string();
    let wsl = std::env::var("WSL_DISTRO_NAME").map(|d| format!("wsl$/{}/", d)).unwrap_or_default();
    // Actually {wslprefix} is "wsl$/WSL_DISTRO_NAME" without trailing slash? docs say set to wsl$/WSL_DISTRO_NAME
    let wslprefix = std::env::var("WSL_DISTRO_NAME").map(|d| format!("wsl$/{}", d)).unwrap_or_default();
    let _ = wsl;
    let mut result = format.to_string();
    result = result.replace("{host}", hostname);
    result = result.replace("{path}", &encoded);
    result = result.replace("{line}", &line_val);
    result = result.replace("{column}", &col_val);
    result = result.replace("{wslprefix}", &wslprefix);
    Some(result)
}
fn percent_encode_path(s: &str) -> String {
    let mut out=String::new();
    for b in s.bytes() {
        let c=b as char;
        if c.is_ascii_alphanumeric() || matches!(c, '/'|':'|'-'|'.'|'_'|'~'|'$'|'&'|'+'|','|';'|'='|'@'|'!'|'('|')'|'*'|'\'') {
            out.push(c);
        } else {
            out.push_str(&format!("%{:02x}", b));
        }
    }
    out
}

// ------------- File processing -------------

pub struct StdinSource {
    pub data: Option<Vec<u8>>,
    pub taken: bool,
}
impl StdinSource {
    pub fn new() -> Self { StdinSource{data:None, taken:false} }
    pub fn read_patterns(&mut self) -> io::Result<Vec<u8>> {
        if self.data.is_none() { let mut buf=Vec::new(); io::stdin().lock().read_to_end(&mut buf)?; self.data=Some(buf); self.taken=true; }
        Ok(self.data.clone().unwrap_or_default())
    }
    pub fn take_for_search(&mut self) -> Vec<u8> {
        if self.taken { return Vec::new(); }
        if self.data.is_none() { let mut buf=Vec::new(); let _=io::stdin().lock().read_to_end(&mut buf); self.data=Some(buf.clone()); self.taken=true; return buf; }
        self.taken=true; self.data.clone().unwrap_or_default()
    }
    pub fn mark_taken(&mut self) { self.taken=true; }
}

pub struct PerFileOutput {
    pub stdout_bytes: Vec<u8>, // block for this file (excluding inter-file heading separators, including JSON begin/match/end etc for json? for json bytes counted separately)
    pub json_begin_match_bytes: usize, // for stats bytes_printed in JSON (begin+match/context)
    // stats contributions (if None discarding stats due to error)
    pub searched: bool, // plain files searched counted
    pub is_match: bool,
    pub files_without_contributed: bool,
    pub count_value: Option<u64>, // for count modes (lines/matches)
    pub count_match_for_exit: bool,
    pub stat_matches: u64,
    pub stat_matched_lines: u64,
    pub bytes_searched: u64,
    pub bytes_printed_stat: u64, // plain stats (standard !=0, other modes 0 except JSON handled)
    pub elapsed: Duration,
    pub binary_offset: Option<usize>,
    pub had_error: bool,
    pub quit_binary_blocked: bool,
    pub lines_for_json: Vec<u8>, // full json output for this file if json and matched (begin..end), else empty
}

pub struct Runtime<'a> {
    pub args: &'a Args,
    pub engine: &'a Engine,
    pub styles: Styles,
    pub colors_enabled: bool,
    pub heading_effective: bool,
    pub show_filename: bool, // decided per program? computed in main (depends on haystacks) - but per file may change? This is global decision.
    pub show_line_number: bool,
    pub hostname: String,
    pub hyperlink_active: bool,
    pub started_at: Instant,
}
impl<'a> Runtime<'a> {
    pub fn path_display_bytes(&self, hay: &Haystack) -> Vec<u8> {
        if hay.is_stdin { return b"<stdin>".to_vec(); }
        let p = &hay.display;
        let mut bytes = {
            #[cfg(unix)] { p.as_os_str().as_bytes().to_vec() }
            #[cfg(not(unix))] { p.to_string_lossy().as_bytes().to_vec() }
        };
        if let Some(sep)=self.args.path_separator { for b in bytes.iter_mut() { if *b==b'/' { *b=sep; } } }
        bytes
    }
    pub fn render_path(&self, hay: &Haystack, line_num: Option<usize>, col: Option<usize>, out: &mut Vec<u8>, is_heading: bool) {
        let disp_bytes = self.path_display_bytes(hay);
        let hyperlink = if self.hyperlink_active && !hay.is_stdin {
            hyperlink_url(&self.args.hyperlink_format, self.args, &self.hostname, &hay.display, line_num, col)
        } else { None };
        if let Some(url)=hyperlink {
            out.extend_from_slice(format!("\x1b]8;;{}\x1b\\", url).as_bytes());
            self.styles.path.render(&disp_bytes, self.colors_enabled, out);
            // closing will be done by caller after additional fields if not heading, else here
            if is_heading {
                out.extend_from_slice(b"\x1b]8;;\x1b\\");
            }
        } else {
            self.styles.path.render(&disp_bytes, self.colors_enabled, out);
        }
    }
}

// Helpers for matching etc are in process_file implementation below
pub fn process_file(hay: &Haystack, rt: &Runtime, stdin_src: &mut StdinSource) -> PerFileOutput {
    let start = Instant::now();
    let mut had_error=false;
    // obtain raw content
    let (raw_opt, transform_failed, transform_error_msg) = obtain_content(hay, rt, stdin_src, &mut had_error);
    let raw = match raw_opt { Some(v)=>v, None=> {
        return PerFileOutput{stdout_bytes:Vec::new(), json_begin_match_bytes:0, searched:false, is_match:false, files_without_contributed:false, count_value:None, count_match_for_exit:false, stat_matches:0, stat_matched_lines:0, bytes_searched:0, bytes_printed_stat:0, elapsed:start.elapsed(), binary_offset:None, had_error, quit_binary_blocked:false, lines_for_json:Vec::new()};
    }};
    let data = decode_bytes(&raw, &rt.args.encoding);
    // if transform failed, stats are discarded later (but content still searched)
    let analysis = analyze(&data, rt);
    // binary handling determinations
    let effective_binary = effective_binary_mode(hay, rt);
    // First NUL position
    let first_nul = data.iter().position(|b| *b==0);
    // Build file outputs based on mode
    let mut out = PerFileOutput{stdout_bytes:Vec::new(), json_begin_match_bytes:0, searched:true, is_match:false, files_without_contributed:false, count_value:None, count_match_for_exit:false, stat_matches:0, stat_matched_lines:0, bytes_searched:data.len() as u64, bytes_printed_stat:0, elapsed:Duration::from_secs(0), binary_offset:first_nul, had_error:had_error || transform_failed, quit_binary_blocked:false, lines_for_json:Vec::new()};
    // Early binary handling for JSON/Count etc is inside mode handlers due to differences; we compute variants:
    // Prepare line-basis analyses for different truncations:
    // - full analysis (already)
    // - truncated before first NUL line (for quit)
    // - truncated before chunk containing first NUL (for quit/convert standard output)
    // We'll handle in subfunctions per printer mode.
    let printer = &rt.args.mode;
    match printer {
        crate::flags::Mode::Search(PrinterMode::Json) => { process_json(hay, rt, &data, &analysis, first_nul, effective_binary, transform_failed, &mut out); }
        crate::flags::Mode::Search(PrinterMode::Count) | crate::flags::Mode::Search(PrinterMode::CountMatches) => { process_count(hay, rt, &data, &analysis, first_nul, effective_binary, transform_failed, &mut out); }
        crate::flags::Mode::Search(PrinterMode::FilesWithMatches) | crate::flags::Mode::Search(PrinterMode::FilesWithoutMatch) => { process_files_with(hay, rt, &data, &analysis, first_nul, effective_binary, transform_failed, &mut out); }
        _ => { process_standard(hay, rt, &data, &analysis, first_nul, effective_binary, transform_failed, &mut out); }
    }
    // stats discarding on transform failure
    if transform_failed {
        out.searched = false;
        out.bytes_searched = 0;
        out.stat_matches = 0; out.stat_matched_lines = 0; out.bytes_printed_stat = 0; out.json_begin_match_bytes = 0;
        // lines_for_json: keep printed JSON but stats in summary must be zero - caller handles by using flag? We store had_error; caller will check lines_for_json and adjust summary contributions if out.searched==false.
        // Also for JSON, end message must be omitted if transform failed (observed). process_json already produced begin+match but no end if we tell it? It doesn't know transform_failed for end suppression -> handled there via parameter.
    }
    // error message printing for transforms: done at the point after searching (so stderr order in separate stream irrelevant). We print here after output computed but before main writes stdout; for standard this mirrors post-search error; stderr is independent.
    if let Some(msg)=transform_error_msg {
        if !rt.args.no_messages {
            let _ = io::stderr().write_all(msg.as_bytes());
        }
    }
    out.elapsed = start.elapsed();
    out
}

#[derive(Clone, Copy, PartialEq)]
enum EffBinary { Text, Quit, Convert }
fn effective_binary_mode(hay: &Haystack, rt: &Runtime) -> EffBinary {
    match rt.args.binary_mode {
        BinaryMode::Text => EffBinary::Text,
        BinaryMode::Binary => EffBinary::Convert,
        BinaryMode::Default => {
            if hay.explicit_file || hay.is_stdin { EffBinary::Convert } else { EffBinary::Quit }
        }
    }
}
fn is_mmap_candidate(hay: &Haystack, rt: &Runtime, transform_used: bool) -> bool {
    rt.args.mmap && hay.explicit_file && !hay.is_stdin && !transform_used
}

// obtain content: returns (content, transform_failed (nonzero exit), error_msg_to_print)
fn obtain_content(hay: &Haystack, rt: &Runtime, stdin_src: &mut StdinSource, had_error: &mut bool) -> (Option<Vec<u8>>, bool, Option<String>) {
    if hay.is_stdin {
        let data = stdin_src.take_for_search();
        return (Some(data), false, None);
    }
    let fs_path = match &hay.fs_path { Some(p)=>p.clone(), None=>return (None,false,None) };
    // search zip
    if rt.args.search_zip {
        if let Some((cmd_name, prog)) = zip_command_for_path(&fs_path) {
            // try run
            let mut cmd = Command::new(&prog);
            cmd.args(&["-d","-c"]); cmd.arg(&fs_path); cmd.stdin(Stdio::null()); cmd.stdout(Stdio::piped()); cmd.stderr(Stdio::piped());
            match cmd.output() {
                Ok(output) => {
                    if output.status.success() {
                        return (Some(output.stdout), false, None);
                    } else {
                        *had_error = true;
                        // decompress error format
                        let msg = format_decompress_error(&hay, rt, &output.stderr);
                        return (Some(output.stdout), true, Some(msg));
                    }
                }
                Err(e) if e.kind()==io::ErrorKind::NotFound => {
                    // fall through to raw
                }
                Err(_e) => {
                    // fall through to raw per docs
                }
            }
        }
    } else if let Some(pre_prog) = &rt.args.pre {
        // note --pre with empty string disables (pre is None when empty handled in flag? --pre= sets Some("") - need handle)
        // Handle empty pre: in main we normalized? Here: if pre_prog.as_os_str empty, skip
        if !pre_prog.as_os_str().is_empty() && pre_glob_allows(hay, rt) {
            // stdin from file
            let stdin_file = match std::fs::File::open(&fs_path) {
                Ok(f)=>f,
                Err(e)=> {
                    if !rt.args.no_messages { let _ = io::stderr().write_all(format!("rg: {}: {}\n", hay.display.to_string_lossy(), e).as_bytes()); }
                    *had_error=true; return (None,false,None);
                }
            };
            let mut cmd = Command::new(pre_prog);
            cmd.arg(&hay.display); // argument as display path (as observed "a.txt")
            cmd.stdin(Stdio::from(stdin_file)); cmd.stdout(Stdio::piped()); cmd.stderr(Stdio::piped());
            match cmd.output() {
                Ok(output) => {
                    if output.status.success() {
                        return (Some(output.stdout), false, None);
                    } else {
                        *had_error=true;
                        let msg = if matches!(rt.args.mode, Mode::Search(PrinterMode::FilesWithMatches)) {
                            format_decompress_like_error(&hay, rt, &output.stderr)
                        } else {
                            format_pre_failed_error(&hay, rt, pre_prog, &output.stderr)
                        };
                        return (Some(output.stdout), true, Some(msg));
                    }
                }
                Err(e) => {
                    *had_error=true;
                    let msg = format!("rg: {}: preprocessor command could not start: '{}': {}\n", hay.display.to_string_lossy(), format_command_display(pre_prog, &hay.display), e);
                    if !rt.args.no_messages { let _ = io::stderr().write_all(msg.as_bytes()); }
                    return (None,false,None);
                }
            }
        }
    }
    // raw
    match std::fs::read(&fs_path) {
        Ok(v)=>(Some(v),false,None),
        Err(e)=>{
            if !rt.args.no_messages {
                let _ = io::stderr().write_all(format!("rg: {}: {}\n", hay.display.to_string_lossy(), e).as_bytes());
            }
            *had_error=true; (None,false,None)
        }
    }
}
fn format_command_display(prog: &Path, arg_path: &Path) -> String {
    format!("\"{}\" \"{}\"", prog.to_string_lossy(), arg_path.to_string_lossy())
}
fn format_pre_failed_error(hay: &Haystack, rt: &Runtime, prog: &Path, stderr: &[u8]) -> String {
    let _ = rt;
    let mut s = format!("rg: {}: preprocessor command failed: '{}': ", hay.display.to_string_lossy(), format_command_display(prog, &hay.display));
    if stderr.is_empty() { s.push_str("<stderr is empty>\n"); } else { s.push_str("\n-------------------------------------------------------------------------------\n"); s.push_str(&String::from_utf8_lossy(stderr)); if !stderr.ends_with(b"\n") { s.push('\n'); } s.push_str("-------------------------------------------------------------------------------\n"); }
    s
}
fn format_decompress_error(hay: &Haystack, rt: &Runtime, stderr: &[u8]) -> String { format_decompress_like_error(hay, rt, stderr) }
fn format_decompress_like_error(hay: &Haystack, _rt: &Runtime, stderr: &[u8]) -> String {
    let mut s = format!("rg: {}: ", hay.display.to_string_lossy());
    if stderr.is_empty() { s.push_str("<stderr is empty>\n"); } else { s.push_str("\n-------------------------------------------------------------------------------\n"); s.push_str(&String::from_utf8_lossy(stderr)); if !stderr.ends_with(b"\n") { s.push('\n'); } s.push_str("-------------------------------------------------------------------------------\n"); }
    s
}
fn zip_command_for_path(p: &Path) -> Option<(String,String)> {
    let name = p.file_name()?.to_string_lossy().to_lowercase();
    let ext = if name.ends_with(".tgz") {"tgz"} else if name.ends_with(".tbz2") {"tbz2"} else if name.ends_with(".txz") {"txz"} else if name.ends_with(".tzst") {"tzst"} else { name.rsplit('.').next()? };
    match ext {
        "gz"|"tgz"|"z" => Some(("gzip".to_string(),"gzip".to_string())),
        "bz2"|"tbz2" => Some(("bzip2".to_string(),"bzip2".to_string())),
        "xz"|"txz"|"lzma" => Some(("xz".to_string(),"xz".to_string())),
        "lz4" => Some(("lz4".to_string(),"lz4".to_string())),
        "br" => Some(("brotli".to_string(),"brotli".to_string())),
        "zst"|"tzst" => Some(("zstd".to_string(),"zstd".to_string())),
        _=>None,
    }
}
fn pre_glob_allows(hay: &Haystack, rt: &Runtime) -> bool {
    if rt.args.pre_globs.is_empty() { return true; }
    // Build globs each time (small)
    let cand = crate::walker::match_path_for_candidate(&crate::walker::WalkContext{args: rt.args, filters: &crate::walker::Filters{overrides:Vec::new(), type_entries:Vec::new(), has_type_select:false}, had_error:false, global_rules:Vec::new(), custom_rules:Vec::new(), next_order:0, cwd_abs: crate::walker::absolute_lexical(Path::new(".")) }, &crate::walker::absolute_lexical(&hay.display));
    // Actually match_path should be based on display relative to cwd; hay.display is already that path (or absolute). If absolute, relative computed works.
    let mut last: Option<bool> = None;
    let mut has_positive=false;
    for pat in &rt.args.pre_globs {
        let (blacklist, stripped) = if let Some(r)=pat.strip_prefix('!') { (true, r.to_string()) } else { (false, pat.clone()) };
        if !blacklist { has_positive=true; }
        if let Ok(g)=build_gitignore_glob(&stripped, false) {
            if g.is_match(cand.as_bytes()) { last=Some(!blacklist); }
        }
    }
    if let Some(v)=last { return v; }
    !has_positive
}

// ---------------- Analysis ----------------
pub struct Analysis {
    pub lines: Vec<LineInfo>,
    pub line_subs: Vec<Vec<SubMatch>>, // per line content (for non-multi line-unit and per line context submatches)
    pub line_raw_match: Vec<bool>,
    pub multi_units: Vec<SubMatch>, // whole haystack coords
    pub blocks_multi: Vec<MultiBlock>,
}
#[derive(Debug, Clone)]
pub struct MultiBlock { pub line_start: usize, pub line_end: usize, pub subs: Vec<SubMatch> } // line indices inclusive, subs coords whole data

pub fn analyze(data: &[u8], rt: &Runtime) -> Analysis {
    let lines = split_lines(data, rt.args);
    let mut line_subs = Vec::with_capacity(lines.len());
    let mut line_raw_match = Vec::with_capacity(lines.len());
    for line in &lines {
        let content = line.content(data);
        let subs: Vec<SubMatch> = rt.engine.regex.find_iter(content).map(|m| {
            // captures for this match
            let caps = rt.engine.regex.captures_at(content, m.start());
            let cap_spans = match caps { Some(c)=> (0..c.len()).map(|i| c.get(i).map(|mm| (mm.start(), mm.end()))).collect(), None=>vec![Some((m.start(), m.end()))] };
            SubMatch{start:m.start(), end:m.end(), caps:cap_spans}
        }).collect();
        line_raw_match.push(!subs.is_empty() || rt.engine.regex.is_match(content));
        // If regex matched but find_iter returns empty? is_match covers empty patterns: find_iter on empty-matching pattern returns matches, so fine. But for pattern that matches empty, find_iter returns many.
        // However for patterns where is_match true but find_iter empty due to ... not possible.
        // Adjust: if line_raw_match but subs empty, create an empty sub at 0?
        line_subs.push(subs);
    }
    // Multi units
    let mut multi_units = Vec::new();
    let mut blocks: Vec<MultiBlock> = Vec::new();
    if rt.args.multiline {
        for m in rt.engine.regex.find_iter(data) {
            let caps = rt.engine.regex.captures_at(data, m.start());
            let cap_spans = match caps { Some(c)=> (0..c.len()).map(|i| c.get(i).map(|mm| (mm.start(), mm.end()))).collect(), None=>vec![Some((m.start(), m.end()))] };
            multi_units.push(SubMatch{start:m.start(), end:m.end(), caps:cap_spans});
        }
        // build blocks merging units that share a line
        for unit in &multi_units {
            // line indices spanned: lines whose content/full ranges intersect [unit.start, unit.end)
            // Determine start line: first line with end > unit.start, or if unit empty at position, line containing that pos
            let (ls, le) = unit_line_span(unit, &lines, data.len());
            if let Some(last)=blocks.last_mut() {
                let last_block: &mut MultiBlock = last;
                if ls <= last_block.line_end { // share line
                    last_block.line_end = last_block.line_end.max(le);
                    last_block.subs.push(unit.clone());
                    continue;
                }
            }
            blocks.push(MultiBlock{line_start:ls, line_end:le, subs:vec![unit.clone()]});
        }
    }
    Analysis{lines, line_subs, line_raw_match, multi_units, blocks_multi: blocks}
}
fn unit_line_span(unit: &SubMatch, lines: &[LineInfo], data_len: usize) -> (usize, usize) {
    if lines.is_empty() { return (0,0); }
    // start pos
    let mut start_idx = lines.len()-1;
    for (i, l) in lines.iter().enumerate() {
        if unit.start < l.end || (unit.start==l.start) || (unit.start>=l.start && unit.start<l.end) { start_idx=i; break; }
        if unit.start < l.start { start_idx=i; break; }
    }
    // if unit.start == data_len (empty match at EOF), it belongs to last line? If data ends with newline, find_iter empty match at EOF would correspond to a phantom line after? Original counts ??? Line lines exclude trailing empty. Empty match at EOF in multiline x* counted matches... Its line span maybe last line.
    if unit.start>=data_len && data_len>0 { start_idx = lines.len()-1; }
    let end_pos = if unit.end>unit.start { unit.end-1 } else { unit.start };
    let mut end_idx = start_idx;
    for (i,l) in lines.iter().enumerate() {
        if end_pos < l.end || (end_pos>=l.start && end_pos<l.end) { end_idx=i; break; }
        if i==lines.len()-1 { end_idx=i; }
    }
    if unit.end==0 && unit.start==0 { end_idx=start_idx; }
    (start_idx, end_idx)
}

// utilities to compute reported matched lines etc, with limits.
pub struct ReportedInfo {
    pub reported_lines: Vec<bool>, // line is a reported match (invert adjusted)
    pub searched_line_count: usize, // number of lines considered searched (exclusive upper bound index count)
    pub primary_block_or_line_count: usize, // for count in non-JSON? deprecated
    pub blocks: Vec<MultiBlock>, // for multiline non-invert, reported blocks (after max limits)
    pub units_for_count_matches: usize, // total submatches/units in reported blocks/lines
}
pub fn compute_reported(analysis: &Analysis, rt: &Runtime, data_len: usize) -> ReportedInfo {
    let n = analysis.lines.len();
    if n==0 {
        return ReportedInfo{reported_lines:Vec::new(), searched_line_count:0, primary_block_or_line_count:0, blocks:Vec::new(), units_for_count_matches:0};
    }
    // Determine raw matched lines
    let mut raw_lines = vec![false; n];
    if rt.args.multiline && !rt.args.invert {
        for b in &analysis.blocks_multi { for i in b.line_start..=b.line_end { if i<n { raw_lines[i]=true; } } }
    } else if rt.args.multiline && rt.args.invert {
        // raw lines are those covered by multi matches
        for b in &analysis.blocks_multi { for i in b.line_start..=b.line_end { if i<n { raw_lines[i]=true; } } }
    } else {
        raw_lines = analysis.line_raw_match.clone();
    }
    let reported_raw = |i: usize| -> bool { if rt.args.invert { !raw_lines[i] } else { raw_lines[i] } };
    // Stop on nonmatch & max count simulation line by line.
    // For multiline non-invert, primary counting is by blocks, not lines. We'll handle max separately after determining line range.
    let maxc = rt.args.max_count;
    // Determine searched upper bound (exclusive)
    let mut searched_upper = n;
    // stop-on-nonmatch (line-based, using raw_lines underlying)
    if rt.args.stop_on_nonmatch {
        let mut seen=false;
        for i in 0..n {
            if raw_lines[i] { seen=true; } else if seen {
                searched_upper = i+1; // include triggering line
                break;
            }
        }
    }
    // max_count
    if let Some(maxv)=maxc {
        if maxv==0 { searched_upper=0; }
        else if rt.args.multiline && !rt.args.invert {
            // count blocks
            let mut cnt=0usize;
            let mut cutoff_line: Option<usize>=None;
            for b in &analysis.blocks_multi {
                if b.line_start >= searched_upper { break; }
                cnt+=1;
                if cnt >= maxv as usize { cutoff_line=Some(b.line_end); break; }
            }
            if let Some(cl)=cutoff_line {
                let after = rt.args.after_context_val();
                // if passthru, after is huge
                let limit = if after>= (u64::MAX/4) { n } else { std::cmp::min(n, cl+1+(after as usize)) };
                // also limited by stop_upper
                searched_upper = std::cmp::min(searched_upper, limit);
                // Wait if after_context is 0 in count mode, caller will handle differently; for standard reported we use after val (context). Count handler overrides.
            }
        } else {
            // count reported lines
            let mut cnt=0usize;
            let mut cutoff: Option<usize>=None;
            for i in 0..searched_upper {
                if reported_raw(i) { cnt+=1; if cnt>=maxv as usize { cutoff=Some(i); break; } }
            }
            if let Some(cl)=cutoff {
                let after = rt.args.after_context_val();
                let limit = if after>= (u64::MAX/4) { n } else { std::cmp::min(n, cl+1+(after as usize)) };
                searched_upper = std::cmp::min(searched_upper, limit);
            }
        }
    }
    let mut reported = vec![false; n];
    for i in 0..searched_upper { reported[i]=reported_raw(i); }
    // blocks for multiline non-invert: filter blocks that start < searched_upper, and clip line_end to searched_upper-1
    let mut blocks = Vec::new();
    if rt.args.multiline && !rt.args.invert {
        for b in &analysis.blocks_multi {
            if b.line_start < searched_upper {
                let mut nb=b.clone(); if nb.line_end >= searched_upper { nb.line_end = searched_upper-1; }
                blocks.push(nb);
            }
        }
    }
    // count matches units
    let mut units_cnt=0usize;
    if rt.args.invert {
        units_cnt = reported.iter().filter(|&&x| x).count();
    } else if rt.args.multiline {
        // count units whose start line < searched_upper (units in blocks)
        for b in &blocks { units_cnt += b.subs.len(); }
    } else {
        for i in 0..searched_upper { if reported[i] { units_cnt += analysis.line_subs[i].len(); } }
    }
    ReportedInfo{reported_lines:reported, searched_line_count:searched_upper, primary_block_or_line_count:0, blocks, units_for_count_matches:units_cnt}
}

fn truncated_analysis_for(data: &[u8], rt: &Runtime, byte_len: usize) -> Analysis {
    let sub = &data[..byte_len.min(data.len())];
    analyze(sub, rt)
}
fn chunk_boundaries(data: &[u8], lines: &[LineInfo]) -> Vec<(usize,usize)> {
    let mut out=Vec::new(); let mut start=0usize;
    while start<data.len() {
        let target = std::cmp::min(start+65536, data.len());
        if target>=data.len() { out.push((start, data.len())); break; }
        // find last line end <= target and > start
        let mut end_opt=None;
        for l in lines { if l.end>start && l.end<=target { end_opt=Some(l.end); } if l.end>target { break; } }
        let end = if let Some(e)=end_opt { e } else {
            // line longer than chunk: extend to that lines end
            let mut e=target; for l in lines { if l.start<=target && l.end>target { e=l.end; break; } }
            e
        };
        if end<=start { out.push((start, target)); start=target; } else { out.push((start,end)); start=end; }
    }
    if out.is_empty() { out.push((0,0)); }
    out
}
fn bytes_searched_for_binary(eff: EffBinary, mmap_explicit: bool, first_nul: Option<usize>, data: &[u8], chunks: &[(usize,usize)]) -> u64 {
    if let Some(nul)=first_nul {
        if eff!=EffBinary::Text {
            if mmap_explicit { return nul as u64; }
            // streaming: start of chunk containing nul
            for (s,e) in chunks { if nul>=*s && nul<*e { return *s as u64; } }
            return 0;
        }
    }
    data.len() as u64
}

