pub fn split_lines(data: &[u8], args: &Args) -> Vec<LineInfo> {
    let mut lines = Vec::new(); let mut start=0usize; let mut num=1usize;
    if args.null_data {
        let mut i=0; while i<data.len() { if data[i]==0 { lines.push(LineInfo{start, content_end:i, end:i+1, number:num}); num+=1; start=i+1; } i+=1; }
