        if start<data.len() { lines.push(LineInfo{start, content_end:data.len(), end:data.len(), number:num}); }
        return lines;
    }
    let mut i=0; while i<data.len() { if data[i]==b'\n' { lines.push(LineInfo{start, content_end:i, end:i+1, number:num}); num+=1; start=i+1; } i+=1; }
