// ---------------- Mode processors ----------------

fn effective_search_data(data: &[u8], eff: EffBinary) -> Vec<u8> {
    if eff==EffBinary::Convert {
        // convert NUL to line terminator \n (except null-data where terminator is NUL)
        // We need args; caller handles conversion before analyze separately. This function unused placeholder.
        data.to_vec()
    } else { data.to_vec() }
}

fn compute_reported_with_after(analysis: &Analysis, rt: &Runtime, after_override: Option<u64>) -> ReportedInfo {
    // temporarily clone logic from compute_reported but adjust after value by constructing a shallow modified runtime? Instead reimplement minimal after handling by calling compute_reported when override matches args.
    // For count/files modes (override Some(0)), we need max cutoff without after context. Our compute_reported uses rt.args.after_context_val() which may be >0.
    // To achieve this, we duplicate its core here with an after parameter.
    let args = rt.args;
    let n = analysis.lines.len();
    if n==0 { return ReportedInfo{reported_lines:vec![], searched_line_count:0, primary_block_or_line_count:0, blocks:vec![], units_for_count_matches:0}; }
    let after_val = after_override.unwrap_or_else(|| args.after_context_val());
    let mut raw_lines = vec![false; n];
    if args.multiline {
        for b in &analysis.blocks_multi { for i in b.line_start..=b.line_end { if i<n { raw_lines[i]=true; } } }
    } else { raw_lines = analysis.line_raw_match.clone(); }
    let reported_raw = |i: usize| -> bool { if args.invert { !raw_lines[i] } else { raw_lines[i] } };
    let mut searched_upper=n;
    if args.stop_on_nonmatch {
        let mut seen=false; for i in 0..n { if raw_lines[i] { seen=true; } else if seen { searched_upper=i+1; break; } }
    }
    if let Some(maxv)=args.max_count {
        if maxv==0 { searched_upper=0; } else if args.multiline && !args.invert {
            let mut cnt=0usize; let mut cutoff:Option<usize>=None;
            for b in &analysis.blocks_multi { if b.line_start>=searched_upper {break;} cnt+=1; if cnt>=maxv as usize {cutoff=Some(b.line_end); break;} }
            if let Some(cl)=cutoff { let limit=if after_val>=u64::MAX/4 {n} else { std::cmp::min(n, cl+1+(after_val as usize)) }; searched_upper=std::cmp::min(searched_upper, limit); }
        } else {
            let mut cnt=0usize; let mut cutoff:Option<usize>=None;
            for i in 0..searched_upper { if reported_raw(i){cnt+=1; if cnt>=maxv as usize {cutoff=Some(i); break;}} }
            if let Some(cl)=cutoff { let limit=if after_val>=u64::MAX/4 {n} else { std::cmp::min(n, cl+1+(after_val as usize)) }; searched_upper=std::cmp::min(searched_upper, limit); }
        }
    }
    let mut reported=vec![false;n]; for i in 0..searched_upper { reported[i]=reported_raw(i); }
    let mut blocks=Vec::new();
    if args.multiline && !args.invert { for b in &analysis.blocks_multi { if b.line_start<searched_upper { let mut nb=b.clone(); if nb.line_end>=searched_upper {nb.line_end=searched_upper-1;} blocks.push(nb); } } }
    let mut units_cnt=0usize;
    if args.invert { units_cnt=reported.iter().filter(|&&x| x).count(); }
    else if args.multiline { for b in &blocks {units_cnt+=b.subs.len();} }
    else { for i in 0..searched_upper { if reported[i]{units_cnt+=analysis.line_subs[i].len();} } }
    ReportedInfo{reported_lines:reported, searched_line_count:searched_upper, primary_block_or_line_count:0, blocks, units_for_count_matches:units_cnt}
}

fn line_index_containing(lines: &[LineInfo], pos: usize) -> usize {
    if lines.is_empty(){return 0;}
    for (i,l) in lines.iter().enumerate() { if pos>=l.start && pos<l.end {return i;} if pos<l.start {return i;} }
    lines.len()-1
}
fn first_chunk_end(chunks: &[(usize,usize)]) -> usize { chunks.get(0).map(|c| c.1).unwrap_or(0) }

fn standard_block(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis) -> (Vec<u8>, bool, ReportedInfo) {
    let reported = compute_reported_with_after(analysis, rt, None);
    let block = generate_standard(hay, rt, data, analysis, &reported);
    let is_match = reported.reported_lines.iter().any(|&x| x);
    (block, is_match, reported)
}

fn process_standard(hay: &Haystack, rt: &Runtime, original_data: &[u8], original_analysis: &Analysis, first_nul: Option<usize>, eff: EffBinary, transform_failed: bool, out: &mut PerFileOutput) {
    // Decide data to use: convert NULs for Convert mode
    let (data_vec, analysis_holder);
    let data: &[u8];
    let analysis: &Analysis;
    if eff==EffBinary::Convert && !rt.args.null_data {
        let mut converted = original_data.to_vec();
        for b in converted.iter_mut() { if *b==0 { *b=b'\n'; } }
        data_vec = converted;
        analysis_holder = analyze(&data_vec, rt);
        data = &data_vec; analysis = &analysis_holder;
    } else { data = original_data; analysis = original_analysis; }
    let _ = transform_failed;
    if eff==EffBinary::Text || first_nul.is_none() {
        let (block, is_match, reported) = standard_block(hay, rt, data, analysis);
        out.stdout_bytes = block; out.is_match=is_match;
        out.stat_matches = if rt.args.invert {0} else {reported.units_for_count_matches as u64};
        out.stat_matched_lines = reported.reported_lines.iter().filter(|&&x| x).count() as u64;
        out.bytes_printed_stat = out.stdout_bytes.len() as u64;
        out.bytes_searched = data.len() as u64;
        return;
    }
    // binary present
    let chunks = chunk_boundaries(data, &analysis.lines);
    let nul = first_nul.unwrap();
    let mmap_explicit = is_mmap_candidate(hay, rt, hay_transform_used(hay, rt));
    let chunk_start = chunks.iter().find(|(s,e)| nul>=*s && nul<*e).map(|c| c.0).unwrap_or(0);
    // detection for mmap
    if eff==EffBinary::Convert && mmap_explicit {
        let fce = first_chunk_end(&chunks);
        let nul_in_first = nul < fce;
        let mut detection_opt: Option<usize> = None;
        if nul_in_first { detection_opt=Some(nul); }
        else {
            // first NUL in a matched line (raw)
            for (idx,line) in analysis.lines.iter().enumerate() {
                if let Some(pos)=line.content(data).iter().position(|b| *b==0) {
                    let abs = line.start+pos;
                    let line_matched = if rt.args.multiline { analysis.blocks_multi.iter().any(|b| idx>=b.line_start && idx<=b.line_end) } else { analysis.line_raw_match[idx] };
                    if line_matched { detection_opt=Some(abs); break; }
                }
            }
        }
        if let Some(det)=detection_opt {
            out.binary_offset=Some(det);
            // before print data
            if nul_in_first {
                // any match in full?
                let (_, is_match_full, reported_full) = standard_block(hay, rt, data, analysis);
                out.stat_matches = stat_matches_convert_line_model(data, analysis, rt, det);
                out.stat_matched_lines = stat_matched_lines_convert_line_model(data, analysis, rt, det);
                out.bytes_searched = det as u64;
                if is_match_full {
                    let msg = binary_message_line(hay, rt, det, false);
                    out.bytes_printed_stat = msg.len() as u64;
                    out.stdout_bytes = msg; out.is_match=true;
                } else { out.is_match=false; }
                let _=reported_full;
                return;
            } else {
                let det_line = line_index_containing(&analysis.lines, det);
                let trunc_end = analysis.lines[det_line].start;
                let trunc_analysis = analyze(&data[..trunc_end], rt);
                let (block, is_match_before, _rep) = standard_block(hay, rt, &data[..trunc_end], &trunc_analysis);
                out.stat_matches = stat_matches_convert_line_model(data, analysis, rt, det);
                out.stat_matched_lines = stat_matched_lines_convert_line_model(data, analysis, rt, det);
                out.bytes_searched = det as u64;
                if is_match_before {
                    let mut b=block; let msg=binary_message_line(hay, rt, det, false); b.extend_from_slice(&msg); out.bytes_printed_stat=b.len() as u64; out.stdout_bytes=b; out.is_match=true;
                } else {
                    let (_, is_match_full, _) = standard_block(hay, rt, data, analysis);
                    if is_match_full { let msg=binary_message_line(hay, rt, det, false); out.bytes_printed_stat=msg.len() as u64; out.stdout_bytes=msg; out.is_match=true; }
                }
                return;
            }
        } else {
            // no detection
            let (block, is_match, reported)=standard_block(hay, rt, data, analysis);
            out.stdout_bytes=block; out.is_match=is_match; out.stat_matches=if rt.args.invert{0}else{reported.units_for_count_matches as u64}; out.stat_matched_lines=reported.reported_lines.iter().filter(|&&x| x).count() as u64; out.bytes_printed_stat=out.stdout_bytes.len() as u64; out.bytes_searched=data.len() as u64; out.binary_offset=None; return;
        }
    }
    // streaming Quit or Convert
    let before_data = &data[..chunk_start];
    let before_analysis = analyze(before_data, rt);
    let (before_block, is_before, _before_rep) = standard_block(hay, rt, before_data, &before_analysis);
    let det_line = line_index_containing(&analysis.lines, nul);
    match eff {
        EffBinary::Quit => {
            out.bytes_searched = chunk_start as u64;
            // stats: lines before detection line
            let trunc_end = if det_line<analysis.lines.len() { analysis.lines[det_line].start } else { data.len() };
            let trunc_analysis = analyze(&data[..trunc_end], rt);
            let rep_trunc = compute_reported_with_after(&trunc_analysis, rt, None);
            out.stat_matches = if rt.args.invert{0}else{rep_trunc.units_for_count_matches as u64};
            out.stat_matched_lines = rep_trunc.reported_lines.iter().filter(|&&x| x).count() as u64;
            if is_before {
                let mut b=before_block; let msg=binary_message_line(hay, rt, nul, true); b.extend_from_slice(&msg); out.bytes_printed_stat=b.len() as u64; out.stdout_bytes=b; out.is_match=true;
            } else {
                out.is_match=false; out.quit_binary_blocked=true; out.stdout_bytes=Vec::new(); out.bytes_printed_stat=0;
            }
        }
        EffBinary::Convert => {
            out.bytes_searched = chunk_start as u64;
            out.stat_matches = stat_matches_convert_line_model(data, analysis, rt, nul);
            out.stat_matched_lines = stat_matched_lines_convert_line_model(data, analysis, rt, nul);
            if is_before {
                let mut b=before_block; let msg=binary_message_line(hay, rt, nul, false); b.extend_from_slice(&msg); out.bytes_printed_stat=b.len() as u64; out.stdout_bytes=b; out.is_match=true;
            } else {
                let (_, is_full, _)=standard_block(hay, rt, data, analysis);
                if is_full { let msg=binary_message_line(hay, rt, nul, false); out.bytes_printed_stat=msg.len() as u64; out.stdout_bytes=msg; out.is_match=true; }
                else { out.is_match=false; }
            }
        }
        EffBinary::Text => unreachable!(),
    }
}

fn stat_matches_convert_line_model(data: &[u8], analysis: &Analysis, rt: &Runtime, nul: usize) -> u64 {
    if rt.args.invert { return 0; }
    // lines up to including first matching line at/after detection line
    let det_line = line_index_containing(&analysis.lines, nul);
    // compute an analysis truncated to end of that line
    let mut limit_end = data.len();
    let mut found=false;
    for i in det_line..analysis.lines.len() {
        let is_match_line = if rt.args.multiline { analysis.blocks_multi.iter().any(|b| i>=b.line_start && i<=b.line_end) } else { analysis.line_raw_match[i] };
        if is_match_line { limit_end = analysis.lines[i].end; found=true; break; }
    }
    if !found { limit_end = if det_line<analysis.lines.len() { analysis.lines[det_line].start } else { data.len() }; }
    let trunc = analyze(&data[..limit_end], rt);
    let rep = compute_reported_with_after(&trunc, rt, None);
    rep.units_for_count_matches as u64
}
fn stat_matched_lines_convert_line_model(data: &[u8], analysis: &Analysis, rt: &Runtime, nul: usize) -> u64 {
    let det_line = line_index_containing(&analysis.lines, nul);
    let mut limit_end = data.len(); let mut found=false;
    for i in det_line..analysis.lines.len() {
        let is_match_line = if rt.args.multiline { analysis.blocks_multi.iter().any(|b| i>=b.line_start && i<=b.line_end) } else { analysis.line_raw_match[i] };
        if is_match_line { limit_end = analysis.lines[i].end; found=true; break; }
    }
    if !found { limit_end = if det_line<analysis.lines.len() { analysis.lines[det_line].start } else { data.len() }; }
    let trunc = analyze(&data[..limit_end], rt);
    let rep = compute_reported_with_after(&trunc, rt, None);
    rep.reported_lines.iter().filter(|&&x| x).count() as u64
}

fn binary_message_line(hay: &Haystack, rt: &Runtime, offset: usize, warning: bool) -> Vec<u8> {
    let mut out=Vec::new();
    // filename prefix if show_filename (global) - not heading style
    if rt.show_filename {
        out.extend_from_slice(&rt.path_display_bytes(hay));
        out.extend_from_slice(b": ");
    }
    if warning { out.extend_from_slice(format!("WARNING: stopped searching binary file after match (found \"\\0\" byte around offset {})", offset).as_bytes()); }
    else { out.extend_from_slice(format!("binary file matches (found \"\\0\" byte around offset {})", offset).as_bytes()); }
    out.push(b'\n');
    out
}

fn hay_transform_used(hay: &Haystack, rt: &Runtime) -> bool {
    if rt.args.search_zip { if let Some(fs)=&hay.fs_path { if zip_command_for_path(fs).is_some() { return true; } } }
    if let Some(pre)=&rt.args.pre { if !pre.as_os_str().is_empty() { return true; } }
    false
}

// Standard output generation
fn generate_standard(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, reported: &ReportedInfo) -> Vec<u8> {
    if !reported.reported_lines.iter().any(|&x| x) { return Vec::new(); }
    let args=rt.args;
    // If replacement with multiline: use block records path
    if args.multiline && args.replace.is_some() && !args.invert {
        return generate_standard_multiline_replace(hay, rt, data, analysis, reported);
    }
    let n=analysis.lines.len();
    // printed set
    let mut printed = vec![false; n];
    if args.passthru && (args.after_context.is_some()||args.before_context.is_some()||args.context_both.is_some()) {
        // passthru was overridden by context flags if they came after; our args.passthru flag is false in that case due to parser, so this branch only when passthru true.
    }
    if args.passthru {
        for i in 0..reported.searched_line_count { printed[i]=true; }
    } else {
        let before=args.before_context_val() as usize; let after=args.after_context_val() as usize;
        // after/before may be huge (passthru handled)
        for i in 0..n {
            if reported.reported_lines[i] {
                let s=i.saturating_sub(before); let e=std::cmp::min(n-1, i+after);
                for j in s..=e { if j<reported.searched_line_count || (j>=reported.searched_line_count && false) { printed[j]=true; } else if j < n {
                    // context after a match can extend beyond searched range only if that match is within range and context not limited by max/stop; but searched range already includes after for max. For normal stop, after context beyond trigger is not printed; we keep restriction j < max(searched, i+1)
                    // Simplification: allow if no max/stop limiting? Distinguish: if searched_line_count<n and (max or stop active), don't allow beyond.
                    let limited = args.max_count.is_some() || args.stop_on_nonmatch;
                    if !limited { printed[j]=true; }
                }}
            }
        }
    }
    // vimgrep handling is integrated in line formatting loops below (it expands matches)
    let mut out=Vec::new();
    // heading prefix
    if rt.heading_effective && !args.vimgrep {
        if rt.show_filename {
            rt.render_path(hay, None, None, &mut out, true);
            // render_path with heading adds closure after path, but need hyperlink closure handling: render_path already closed if heading
            out.extend_from_slice(&disp_terminator_for_path(rt));
        }
        // if show_filename false, heading has no line but groups still separated by blank line in main
    }
    // groups separator logic
    let context_enabled = args.before_context_val()>0 || args.after_context_val()>0;
    let mut prev_printed_idx: Option<usize>=None;
    let mut first_printed=true;
    for i in 0..n {
        if !printed[i] { continue; }
        if context_enabled && !first_printed {
            if let Some(prev)=prev_printed_idx { if i>prev+1 {
                // context separator line (not in heading? separator is just line)
                if let Some(sep)=&args.context_separator {
                    out.extend_from_slice(sep.as_bytes()); out.push(b'\n');
                } else if args.context_separator.is_none() {
                    // no separator
                }
                // empty separator case: context_separator == Some("") yields just "\n" above (sep bytes empty)
            }}
        }
        let is_match = reported.reported_lines[i];
        // generate for this line
        if args.vimgrep {
            generate_vimgrep_line(hay, rt, data, analysis, reported, i, is_match, &mut out);
        } else if args.only_matching && is_match && !args.invert {
            generate_only_matching_for_line(hay, rt, data, analysis, reported, i, &mut out);
        } else {
            generate_normal_line(hay, rt, data, analysis, reported, i, is_match, &mut out);
        }
        prev_printed_idx=Some(i); first_printed=false;
    }
    out
}
fn disp_terminator_for_path(rt: &Runtime) -> Vec<u8> {
    if rt.args.null { vec![0] } else { vec![b'\n'] }
}
fn line_terminator_bytes(rt: &Runtime, line: &LineInfo, data: &[u8]) -> Vec<u8> {
    if line.end>line.content_end { return data[line.content_end..line.end].to_vec(); }
    if rt.args.null_data { return vec![0]; }
    if rt.args.crlf { return b"\r\n".to_vec(); }
    vec![b'\n']
}
fn generate_normal_line(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, reported: &ReportedInfo, idx: usize, is_match: bool, out: &mut Vec<u8>) {
    let line=&analysis.lines[idx];
    let sep = if is_match { rt.args.field_match_separator.as_bytes() } else { rt.args.field_context_separator.as_bytes() };
    // build prefix fields
    let mut fields: Vec<(Vec<u8>, u8)> = Vec::new(); // (rendered field, kind 0 path 1 line 2 column 3 offset)
    if !rt.heading_effective && rt.show_filename { let mut b=Vec::new(); rt.render_path_raw(hay, &mut b); fields.push((b,0)); }
    let show_line = rt.show_line_number;
    if show_line { let mut b=Vec::new(); rt.styles.line.render(line.number.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,1)); }
    let mut col_val: Option<usize>=None;
    if rt.args.column && is_match && !rt.args.invert {
        let subs = line_submatches_for_display(analysis, rt, data, idx);
        if let Some(first)=subs.first() { col_val=Some(first.start+1); let mut b=Vec::new(); rt.styles.column.render(col_val.unwrap().to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,2)); }
    }
    if rt.args.byte_offset { let mut b=Vec::new(); rt.styles.column.render(line.start.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,3)); }
    write_prefix_fields(hay, rt, fields, sep, line.number, col_val, out);
    // content
    let content = build_line_content(hay, rt, data, analysis, idx, is_match);
    out.extend_from_slice(&content);
    out.extend_from_slice(&line_terminator_bytes(rt, line, data));
}
fn line_submatches_for_display(analysis: &Analysis, rt: &Runtime, data: &[u8], idx: usize) -> Vec<SubMatch> {
    if rt.args.multiline {
        let line=&analysis.lines[idx];
        let mut subs=Vec::new();
        for block in &analysis.blocks_multi {
            // only blocks in reported? Caller will handle reported filtered? For display we use blocks_multi (raw). To avoid highlighting matches beyond searched/report, caller context uses reported lines; if line is reported, its raw matches are relevant.
            for unit in &block.subs {
                // intersect with line content
                let s = unit.start.max(line.start); let e = unit.end.min(line.content_end);
                if s<=e && (s<e || (unit.start>=line.start && unit.start<=line.content_end)) {
                    // caps need unit caps (for replacement handled separately)
                    subs.push(SubMatch{start: s-line.start, end: e-line.start, caps: unit.caps.iter().map(|c| c.map(|(cs,ce)| (cs,ce))).collect()});
                }
            }
        }
        subs
    } else {
        analysis.line_subs[idx].clone()
    }
}
fn build_line_content(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, idx: usize, is_match: bool) -> Vec<u8> {
    let _=hay;
    let line=&analysis.lines[idx];
    let mut content = line.content(data).to_vec();
    let mut subs = if is_match && !rt.args.invert { line_submatches_for_display(analysis, rt, data, idx) } else { Vec::new() };
    // trim
    let mut trim_len=0usize;
    if rt.args.trim {
        let mut t=0; while t<content.len() && matches!(content[t], b' '|b'\t'|0x0b|0x0c|b'\r') { t+=1; }
        trim_len=t;
        if t>0 { content=content[t..].to_vec(); for s in subs.iter_mut() { s.start=s.start.saturating_sub(t); s.end=s.end.saturating_sub(t); } }
    }
    // max columns
    if let Some(maxc)=rt.args.max_columns { if maxc>0 && (content.len() as u64)>maxc {
        let maxc_usize = maxc as usize;
        if !rt.args.max_columns_preview {
            return if is_match { b"[Omitted long matching line]".to_vec() } else { b"[Omitted long context line]".to_vec() };
        } else {
            let preview = content[..maxc_usize.min(content.len())].to_vec();
            let mut outv=Vec::new();
            if is_match && !rt.args.invert {
                // highlight preview parts
                outv = render_content_with_matches(&preview, &subs, rt, line, data, false);
                // suffix
                if rt.colors_enabled || rt.args.only_matching || rt.args.column || rt.args.vimgrep {
                    let more = subs.iter().filter(|s| s.start>=maxc_usize).count();
                    outv.extend_from_slice(format!(" [... {} more matches]", more).as_bytes());
                } else { outv.extend_from_slice(b" [... omitted end of long line]"); }
            } else {
                outv.extend_from_slice(&preview); outv.extend_from_slice(b" [... omitted end of long line]");
            }
            return outv;
        }
    }}
    if is_match && !rt.args.invert {
        if let Some(repl)=&rt.args.replace {
            // build replaced content
            return render_replaced_line(&content, &subs, repl, rt, line, data);
        } else {
            return render_content_with_matches(&content, &subs, rt, line, data, false);
        }
    } else {
        return content;
    }
}
fn render_content_with_matches(content: &[u8], subs: &[SubMatch], rt: &Runtime, _line: &LineInfo, _data: &[u8], _is_o: bool) -> Vec<u8> {
    let mut out=Vec::new(); let mut pos=0usize;
    // subs may overlap after trim clipping; sort by start
    let mut sorted=subs.to_vec(); sorted.sort_by_key(|s| s.start);
    for s in sorted {
        if s.start<pos { continue; }
        if s.start>content.len() { continue; }
        out.extend_from_slice(&content[pos..s.start.min(content.len())]);
        let end=s.end.min(content.len());
        // styled match segment
        rt.styles.match_.render(&content[s.start..end], rt.colors_enabled, &mut out);
        pos=end;
    }
    if pos<content.len() { out.extend_from_slice(&content[pos..]); }
    out
}
fn render_replaced_line(content: &[u8], subs: &[SubMatch], repl: &str, rt: &Runtime, line: &LineInfo, data: &[u8]) -> Vec<u8> {
    // for non-multi, subs caps are relative to original line content (before trim?). Caller passed content after trim and subs adjusted for trim, but caps are original offsets.
    // To handle trim correctly for replacement, we need haystack for capture extraction: original line content.
    // However subs passed here have starts adjusted but caps unchanged (still original). That's a mismatch. Simplify: if trim is active, we will have adjusted subs starts but caps point to original line content; expansion using line.content(data) as haystack works because caps are in that haystack.
    // For multiline display subs, caps are whole data.
    let haystack_for_caps: &[u8] = if rt.args.multiline { data } else { line.content(data) };
    let mut out=Vec::new(); let mut pos=0usize;
    let mut sorted=subs.to_vec(); sorted.sort_by_key(|s| s.start);
    for s in sorted {
        if s.start<pos || s.start>content.len() { continue; }
        out.extend_from_slice(&content[pos..s.start]);
        let expansion = expand_replacement(repl.as_bytes(), &s.caps, &rt.engine.capture_names, haystack_for_caps);
        rt.styles.match_.render(&expansion, rt.colors_enabled, &mut out);
        pos=s.end.min(content.len());
    }
    if pos<content.len() { out.extend_from_slice(&content[pos..]); }
    out
}
fn generate_only_matching_for_line(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, reported: &ReportedInfo, idx: usize, out: &mut Vec<u8>) {
    let line=&analysis.lines[idx];
    if rt.args.multiline {
        // records per unit that starts (?) in blocks reported for this line: Need avoid duplicate when same unit spans multiple lines: Only emit when idx == block's unit start line
        // We'll handle only-matching at a higher level in generate_standard? This per-line path is called for each printed line. For multiline, we must emit units whose start line == idx (or whose span includes idx and it's first printed line of unit)
        for block in &reported.blocks {
            for unit in &block.subs {
                let (ls,_le)=unit_line_span(unit, &analysis.lines, data.len());
                if ls!=idx { continue; }
                emit_only_record(hay, rt, data, analysis, unit, idx, out);
            }
        }
        return;
    }
    for sub in analysis.line_subs[idx].clone() {
        emit_only_record_line(hay, rt, data, analysis, &sub, idx, out);
    }
}
fn emit_only_record_line(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, sub: &SubMatch, idx: usize, out: &mut Vec<u8>) {
    let line=&analysis.lines[idx];
    let sep=rt.args.field_match_separator.as_bytes();
    let mut fields=Vec::new();
    if !rt.heading_effective && rt.show_filename { let mut b=Vec::new(); rt.render_path_raw(hay, &mut b); fields.push((b,0)); }
    let mut col_val=None;
    if rt.show_line_number { let mut b=Vec::new(); rt.styles.line.render(line.number.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,1)); }
    if rt.args.column { col_val=Some(sub.start+1); let mut b=Vec::new(); rt.styles.column.render(col_val.unwrap().to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,2)); }
    if rt.args.byte_offset { let off=line.start+sub.start; let mut b=Vec::new(); rt.styles.column.render(off.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,3)); }
    write_prefix_fields(hay, rt, fields, sep, line.number, col_val, out);
    // subject
    let subject_raw = &line.content(data)[sub.start..sub.end];
    let subject = if let Some(repl)=&rt.args.replace { expand_replacement(repl.as_bytes(), &sub.caps, &rt.engine.capture_names, line.content(data)) } else { subject_raw.to_vec() };
    emit_subject_with_maxcolumns(rt, subject, true, &[sub.clone()], line, data, out, true);
    // terminator
    out.extend_from_slice(&only_record_terminator(rt));
}
fn emit_only_record(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, unit: &SubMatch, idx: usize, out: &mut Vec<u8>) {
    let line=&analysis.lines[idx];
    let sep=rt.args.field_match_separator.as_bytes();
    let mut fields=Vec::new();
    if !rt.heading_effective && rt.show_filename { let mut b=Vec::new(); rt.render_path_raw(hay, &mut b); fields.push((b,0)); }
    // column is relative to start line of unit
    let line_start_offset = line.start;
    let col = if unit.start>=line_start_offset { unit.start-line_start_offset+1 } else { 1 };
    let mut col_val=None;
    if rt.show_line_number { let mut b=Vec::new(); rt.styles.line.render(line.number.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,1)); }
    if rt.args.column { col_val=Some(col); let mut b=Vec::new(); rt.styles.column.render(col.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,2)); }
    if rt.args.byte_offset { let mut b=Vec::new(); rt.styles.column.render(unit.start.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,3)); }
    write_prefix_fields(hay, rt, fields, sep, line.number, col_val, out);
    let subject_raw = &data[unit.start..unit.end];
