fn generate_vimgrep_line(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, reported: &ReportedInfo, idx: usize, is_match: bool, out: &mut Vec<u8>) {
    // If not match (context or invert), behave like normal line but without column and with vimgrep filename rules
    if !is_match || rt.args.invert {
        // normal line but force filename/line per vimgrep rules
        generate_vimgrep_nonmatch_line(hay, rt, data, analysis, idx, is_match, out);
        return;
    }
    if rt.args.only_matching {
        // per match records like only matching but with vimgrep fields
        generate_only_matching_for_line(hay, rt, data, analysis, reported, idx, out);
        return;
    }
    if rt.args.multiline {
        // per unit whose start line == idx
        for block in &reported.blocks {
            for unit in &block.subs {
                let (ls,_)=unit_line_span(unit, &analysis.lines, data.len()); if ls!=idx {continue;}
                emit_vimgrep_record(hay, rt, data, analysis, unit, idx, out);
            }
        }
        return;
    }
    for sub in analysis.line_subs[idx].clone() {
        // vimgrep record using sub as unit within line
        let unit = SubMatch{start: analysis.lines[idx].start+sub.start, end: analysis.lines[idx].start+sub.end, caps: sub.caps.clone()};
