fn write_prefix_fields_with_sep_override(hay: &Haystack, rt: &Runtime, fields: Vec<(Vec<u8>,u8)>, sep: &[u8], line_num: usize, col: Option<usize>, out: &mut Vec<u8>) {
    if fields.is_empty() { return; }
    // hyperlink handling: if first field is path (kind0) and hyperlink active, wrap prefix up to last field
    let has_path = fields[0].1==0;
    let url_opt = if has_path && rt.hyperlink_active && !hay.is_stdin { hyperlink_url(&rt.args.hyperlink_format, rt.args, &rt.hostname, &hay.display, Some(line_num), col) } else { None };
    if let Some(url)=url_opt { out.extend_from_slice(format!("\x1b]8;;{}\x1b\\", url).as_bytes()); }
