        if i>0 {
            // separator between fields (inside hyperlink if present)
            if i==1 && fields[0].1==0 && rt.args.null {
                out.push(0);
            } else { out.extend_from_slice(sep); }
        }
        out.extend_from_slice(field);
    }
    if url_opt.is_some() { out.extend_from_slice(b"\x1b]8;;\x1b\\"); }
