        // Our internal separator logic above incorrectly used NUL between path and second field (which is correct for -0). For final separator after all fields, it's sep.
        out.extend_from_slice(sep);
    } else {
        out.extend_from_slice(sep);
    }
}

fn generate_standard_multiline_replace(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, reported: &ReportedInfo) -> Vec<u8> {
    // Build printed line set like generate_standard, then emit block records for blocks and individual lines otherwise
    let n=analysis.lines.len();
    let mut printed=vec![false;n];
    if rt.args.passthru { for i in 0..reported.searched_line_count { printed[i]=true; } } else {
        let before=rt.args.before_context_val() as usize; let after=rt.args.after_context_val() as usize;
        for i in 0..n { if reported.reported_lines[i] { let s=i.saturating_sub(before); let e=std::cmp::min(n-1,i+after); for j in s..=e { if j<reported.searched_line_count || !(rt.args.max_count.is_some()||rt.args.stop_on_nonmatch) { printed[j]=true; } } } }
    }
    if !reported.reported_lines.iter().any(|&x| x) { return Vec::new(); }
    let mut out=Vec::new();
    if rt.heading_effective {
        if rt.show_filename { rt.render_path(hay, None, None, &mut out, true); out.extend_from_slice(&disp_terminator_for_path(rt)); }
    }
    let context_enabled = rt.args.before_context_val()>0 || rt.args.after_context_val()>0;
    let mut prev:Option<usize>=None; let mut first=true;
    let mut i=0usize;
    while i<n {
        if !printed[i] { i+=1; continue; }
        if context_enabled && !first { if let Some(p)=prev { if i>p+1 { if let Some(sep)=&rt.args.context_separator { out.extend_from_slice(sep.as_bytes()); out.push(b'\n'); } } } }
        // if this line is start of a reported block, emit block record
        let block_opt = reported.blocks.iter().find(|b| b.line_start==i);
        if let Some(block)=block_opt {
            emit_multiline_replace_block(hay, rt, data, analysis, block, &mut out);
            prev=Some(block.line_end); first=false; i=block.line_end+1; continue;
        } else {
            let is_match=reported.reported_lines[i];
            generate_normal_line(hay, rt, data, analysis, reported, i, is_match, &mut out);
            prev=Some(i); first=false; i+=1;
        }
    }
    out
}
fn emit_multiline_replace_block(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, block: &MultiBlock, out: &mut Vec<u8>) {
    let line=&analysis.lines[block.line_start];
    let sep=rt.args.field_match_separator.as_bytes();
    let mut fields=Vec::new();
    if !rt.heading_effective && rt.show_filename { let mut b=Vec::new(); rt.render_path_raw(hay, &mut b); fields.push((b,0)); }
    if rt.show_line_number { let mut b=Vec::new(); rt.styles.line.render(line.number.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,1)); }
    if rt.args.column {
        if let Some(first)=block.subs.first() { let col=first.start - line.start +1; let mut b=Vec::new(); rt.styles.column.render(col.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,2)); }
    }
    if rt.args.byte_offset { let mut b=Vec::new(); rt.styles.column.render(line.start.to_string().as_bytes(), rt.colors_enabled, &mut b); fields.push((b,3)); }
    write_prefix_fields(hay, rt, fields, sep, line.number, None, out);
    // block text from line_start.start to line_end.content_end
    let block_start=analysis.lines[block.line_start].start; let block_end=analysis.lines[block.line_end].content_end;
    let block_text=&data[block_start..block_end];
    // apply replacements for units in block sorted
    let mut subs=block.subs.clone(); subs.sort_by_key(|s| s.start);
    let mut content=Vec::new(); let mut pos=block_start;
    for unit in &subs {
        if unit.start<pos { continue; }
        content.extend_from_slice(&data[pos..unit.start]);
        let repl_text = expand_replacement(rt.args.replace.as_ref().unwrap().as_bytes(), &unit.caps, &rt.engine.capture_names, data);
        // trim handling for block? If trim, block text leading whitespace (?) ignore
        rt.styles.match_.render(&repl_text, rt.colors_enabled, &mut content);
        pos=unit.end;
    }
    if pos<block_end { content.extend_from_slice(&data[pos..block_end]); }
    // Max columns on content (as one subject)
    // If content longer than max, etc: simplify use max logic on content as a whole
    if let Some(maxc)=rt.args.max_columns { if maxc>0 && (content.len() as u64)>maxc {
        // Note content may have styling codes; measuring here is inaccurate if colors. Use raw block_text length approx.
        if !rt.args.max_columns_preview { out.extend_from_slice(b"[Omitted long matching line]"); out.extend_from_slice(&line_terminator_bytes(rt, &analysis.lines[block.line_end], data)); return; }
    }}
    out.extend_from_slice(&content);
    // terminator: use terminator of last line in block
    out.extend_from_slice(&line_terminator_bytes(rt, &analysis.lines[block.line_end], data));
}

