// ---------------- JSON / count / files processors ----------------

pub fn json_data_obj(bytes: &[u8]) -> String {
    match std::str::from_utf8(bytes) {
        Ok(s) => format!("{{\"text\":{}}}", json_escape_str(s)),
        Err(_) => format!("{{\"bytes\":\"{}\"}}", base64_encode(bytes)),
    }
}
pub fn json_escape_str(s: &str) -> String {
    let mut out=String::from("\"");
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"'); out
}
pub fn base64_encode(data: &[u8]) -> String {
    const TABLE: &[u8;64]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out=String::new();
    let mut i=0; while i<data.len() { let b0=data[i]; let b1=if i+1<data.len(){data[i+1]}else{0}; let b2=if i+2<data.len(){data[i+2]}else{0}; out.push(TABLE[(b0>>2) as usize] as char); out.push(TABLE[(((b0&0x03)<<4)|(b1>>4)) as usize] as char); out.push(if i+1<data.len(){ TABLE[(((b1&0x0f)<<2)|(b2>>6)) as usize] as char } else {'='}); out.push(if i+2<data.len(){ TABLE[(b2&0x3f) as usize] as char } else {'='}); i+=3; }
    out
}
pub fn json_duration_obj(d: Duration) -> String {
    let secs=d.as_secs(); let nanos=d.subsec_nanos();
    format!("{{\"secs\":{},\"nanos\":{},\"human\":\"{}\"}}", secs, nanos, human_duration(d))
}
pub fn json_duration_obj_summary(d: Duration) -> String {
    let secs=d.as_secs(); let nanos=d.subsec_nanos();
    // summary ordering human,nanos,secs
    format!("{{\"human\":\"{}\",\"nanos\":{},\"secs\":{}}}", human_duration(d), nanos_total_for_summary(d), secs)
}
fn nanos_total_for_summary(d: Duration) -> u64 {
    // In summary, elapsed object appears to use same struct but serialized in different order; the nanos field there is total? Check examples: summary elapsed nanos equals per-file nanos (subsec) when <1 sec. total elapsed_total nanos is total nanos.
    // For per-file stats aggregated, nanos field = subsec nanos of aggregated duration.
    d.subsec_nanos() as u64
}
pub fn human_duration(d: Duration) -> String {
    format!("{:.6}s", d.as_secs_f64())
}

fn process_json(hay: &Haystack, rt: &Runtime, original_data: &[u8], original_analysis: &Analysis, first_nul: Option<usize>, eff: EffBinary, transform_failed: bool, out: &mut PerFileOutput) {
    let json_start = Instant::now();
    // choose data/analysis
    let (data_vec, analysis_holder);
    let data: &[u8]; let analysis: &Analysis;
    let mut binary_offset_for_json: Option<usize> = None;
    let mut bytes_searched_json: u64 = original_data.len() as u64;
    if eff==EffBinary::Quit {
        if let Some(nul)=first_nul {
            let chunks=chunk_boundaries(original_data, &original_analysis.lines);
            let fce=first_chunk_end(&chunks);
            if nul < fce {
                out.searched=false; out.is_match=false; out.quit_binary_blocked=true; out.stdout_bytes=Vec::new(); out.lines_for_json=Vec::new(); out.bytes_searched=0; out.binary_offset=Some(nul); return;
            } else {
                let chunk_start=chunks.iter().find(|(s,e)| nul>=*s && nul<*e).map(|c| c.0).unwrap_or(0);
                let trunc=&original_data[..chunk_start];
                analysis_holder=analyze(trunc, rt); data=trunc; analysis=&analysis_holder;
                binary_offset_for_json=Some(nul); bytes_searched_json=chunk_start as u64;
                // produce json below using data/analysis
                // fallthrough to generation with these bindings: we need a scope - handle via generating here duplicate? We'll call generate_json_inner
                let (json_bytes, begin_match_bytes, is_match, rep) = generate_json(hay, rt, data, analysis, binary_offset_for_json, bytes_searched_json, transform_failed, json_start);
                out.lines_for_json=json_bytes.clone(); out.stdout_bytes=json_bytes; out.is_match=is_match; out.json_begin_match_bytes=begin_match_bytes; out.bytes_searched=bytes_searched_json; out.binary_offset=binary_offset_for_json;
                out.stat_matches=if rt.args.invert{0}else{rep.units_for_count_matches as u64}; out.stat_matched_lines=rep.reported_lines.iter().filter(|&&x| x).count() as u64;
                out.searched = is_match; // for JSON summary counting: only matched files contribute (caller uses lines and searched)
                return;
            }
        }
    }
    if eff==EffBinary::Convert && !rt.args.null_data {
        let mut converted=original_data.to_vec(); for b in converted.iter_mut(){ if *b==0 {*b=b'\n';}}
        data_vec=converted; analysis_holder=analyze(&data_vec, rt); data=&data_vec; analysis=&analysis_holder;
        if let Some(nul)=first_nul {
            binary_offset_for_json=Some(nul);
            let mmap_explicit=is_mmap_candidate(hay, rt, hay_transform_used(hay, rt));
            if mmap_explicit {
                // check detection
                let chunks=chunk_boundaries(original_data, &original_analysis.lines);
                let fce=first_chunk_end(&chunks);
                if nul < fce { bytes_searched_json=nul as u64; }
                else {
                    // matching line containing nul?
                    let mut det: Option<usize>=None;
                    for (idx,line) in original_analysis.lines.iter().enumerate() { if let Some(pos)=line.content(original_data).iter().position(|b| *b==0){ let line_matched=if rt.args.multiline { original_analysis.blocks_multi.iter().any(|b| idx>=b.line_start && idx<=b.line_end)} else {original_analysis.line_raw_match[idx]}; if line_matched {det=Some(line.start+pos); break;} } }
                    if let Some(d)=det { binary_offset_for_json=Some(d); bytes_searched_json=d as u64; } else { binary_offset_for_json=None; bytes_searched_json=original_data.len() as u64; }
                }
            } else { bytes_searched_json=original_data.len() as u64; }
        }
    } else { data=original_data; analysis=original_analysis; if eff==EffBinary::Text { binary_offset_for_json=None; } else if let Some(nul)=first_nul { if eff==EffBinary::Convert { binary_offset_for_json=Some(nul); } } }
    let (json_bytes, begin_match_bytes, is_match, rep) = generate_json(hay, rt, data, analysis, binary_offset_for_json, bytes_searched_json, transform_failed, json_start);
    out.lines_for_json=json_bytes.clone(); out.stdout_bytes=json_bytes; out.is_match=is_match; out.json_begin_match_bytes=begin_match_bytes; out.bytes_searched=bytes_searched_json; out.binary_offset=binary_offset_for_json;
    out.stat_matches=if rt.args.invert{0}else{rep.units_for_count_matches as u64}; out.stat_matched_lines=rep.reported_lines.iter().filter(|&&x| x).count() as u64;
    // JSON summary contribution only if end emitted (match and not transform failed)
    out.searched = is_match && !transform_failed;
}

fn generate_json(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, binary_offset: Option<usize>, bytes_searched: u64, transform_failed: bool, json_start: Instant) -> (Vec<u8>, usize, bool, ReportedInfo) {
    let reported = compute_reported_with_after(analysis, rt, None);
    let is_match = reported.reported_lines.iter().any(|&x| x);
    if !is_match { return (Vec::new(), 0, false, reported); }
    let path_obj = if hay.is_stdin { json_data_obj(b"<stdin>") } else { json_data_obj(&rt.path_display_bytes(hay)) };
    let mut out=Vec::new();
    let begin = format!("{{\"type\":\"begin\",\"data\":{{\"path\":{}}}}}\n", path_obj);
    let mut begin_match_bytes = begin.len();
    out.extend_from_slice(begin.as_bytes());
    // printed lines set
    let n=analysis.lines.len();
    let mut printed=vec![false;n];
    if rt.args.passthru { for i in 0..reported.searched_line_count { printed[i]=true; } } else {
        let before=rt.args.before_context_val() as usize; let after=rt.args.after_context_val() as usize;
        for i in 0..n { if reported.reported_lines[i] { let s=i.saturating_sub(before); let e=std::cmp::min(n-1, i+after); for j in s..=e { if j<reported.searched_line_count || !(rt.args.max_count.is_some()||rt.args.stop_on_nonmatch) { printed[j]=true; } } } }
    }
    // iterate
    if rt.args.multiline && !rt.args.invert {
        let mut i=0usize;
        while i<n {
            if !printed[i] { i+=1; continue; }
            // block starting at i?
            if let Some(block)=reported.blocks.iter().find(|b| b.line_start==i) {
                // match item for block
                let block_start_off=analysis.lines[block.line_start].start; let block_end_off=analysis.lines[block.line_end].end;
                let lines_bytes=&data[block_start_off..block_end_off];
                let mut subs_json=Vec::new();
                for unit in &block.subs {
                    let mt=&data[unit.start..unit.end];
                    subs_json.push(format!("{{\"match\":{},\"start\":{},\"end\":{}}}", json_data_obj(mt), unit.start-block_start_off, unit.end-block_start_off));
                }
                let item=format!("{{\"type\":\"match\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[{}]}}}}\n", path_obj, json_data_obj(lines_bytes), analysis.lines[block.line_start].number, block_start_off, subs_json.join(","));
                begin_match_bytes+=item.len(); out.extend_from_slice(item.as_bytes());
                i=block.line_end+1; continue;
            } else {
                // context line
                let line=&analysis.lines[i];
                let item=format!("{{\"type\":\"context\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[]}}}}\n", path_obj, json_data_obj(line.full(data)), line.number, line.start);
                begin_match_bytes+=item.len(); out.extend_from_slice(item.as_bytes());
                i+=1;
            }
        }
    } else {
        for i in 0..n { if !printed[i]{continue;}
            let line=&analysis.lines[i]; let is_m=reported.reported_lines[i];
            let typ=if is_m {"match"} else {"context"};
            // submatches
            let subs_json: Vec<String> = if is_m && !rt.args.invert {
                analysis.line_subs[i].iter().map(|s| { let mt=&line.content(data)[s.start..s.end]; format!("{{\"match\":{},\"start\":{},\"end\":{}}}", json_data_obj(mt), s.start, s.end) }).collect()
            } else if !is_m && rt.args.invert {
                analysis.line_subs[i].iter().map(|s| { let mt=&line.content(data)[s.start..s.end]; format!("{{\"match\":{},\"start\":{},\"end\":{}}}", json_data_obj(mt), s.start, s.end) }).collect()
            } else { Vec::new() };
            let item=format!("{{\"type\":\"{}\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[{}]}}}}\n", typ, path_obj, json_data_obj(line.full(data)), line.number, line.start, subs_json.join(","));
            begin_match_bytes+=item.len(); out.extend_from_slice(item.as_bytes());
        }
    }
    if !transform_failed {
        let elapsed=json_start.elapsed();
        // Store elapsed in a way caller can retrieve? generate_json returns bytes; the elapsed used here must be consistent with out.elapsed set by process_json caller.
        // We encode it into stats and process_file will later overwrite out.elapsed - caller (main) summary uses per-file elapsed values accumulated from PerFileOutput.elapsed, not from parsing JSON. There's a mismatch risk but timing is approximate anyway.
        let stats_obj=format!("{{\"elapsed\":{},\"searches\":1,\"searches_with_match\":1,\"bytes_searched\":{},\"bytes_printed\":{},\"matched_lines\":{},\"matches\":{}}}", json_duration_obj(elapsed), bytes_searched, begin_match_bytes, reported.reported_lines.iter().filter(|&&x| x).count(), if rt.args.invert{0}else{reported.units_for_count_matches});
        let bin_str = match binary_offset { Some(v)=>v.to_string(), None=>"null".to_string() };
        let end=format!("{{\"type\":\"end\",\"data\":{{\"path\":{},\"binary_offset\":{},\"stats\":{}}}}}\n", path_obj, bin_str, stats_obj);
        out.extend_from_slice(end.as_bytes());
        // stash elapsed into a global? Instead process_json sets out.elapsed after; main summary should ideally sum end elapsed values. We'll accept process_file elapsed (close).
    }
    (out, begin_match_bytes, true, reported)
}

fn process_count(hay: &Haystack, rt: &Runtime, original_data: &[u8], original_analysis: &Analysis, first_nul: Option<usize>, eff: EffBinary, transform_failed: bool, out: &mut PerFileOutput) {
    // choose analysis
    let (data_vec, analysis_holder); let data: &[u8]; let analysis: &Analysis;
    let mut bytes_searched = original_data.len() as u64;
    if eff==EffBinary::Quit {
        if let Some(nul)=first_nul {
            let det_line=line_index_containing(&original_analysis.lines, nul);
            let trunc_end=if det_line<original_analysis.lines.len(){original_analysis.lines[det_line].start}else{original_data.len()};
            let trunc=&original_data[..trunc_end]; analysis_holder=analyze(trunc, rt); data=trunc; analysis=&analysis_holder;
            let chunks=chunk_boundaries(original_data, &original_analysis.lines); bytes_searched=chunks.iter().find(|(s,e)| nul>=*s && nul<*e).map(|c| c.0).unwrap_or(0) as u64;
            // generate with these
            finish_count(hay, rt, data, analysis, bytes_searched, transform_failed, out); return;
        }
    }
    if eff==EffBinary::Convert && !rt.args.null_data {
        let mut converted=original_data.to_vec(); for b in converted.iter_mut(){ if *b==0 {*b=b'\n';} } data_vec=converted; analysis_holder=analyze(&data_vec, rt); data=&data_vec; analysis=&analysis_holder;
        if let Some(nul)=first_nul {
            let mmap_explicit=is_mmap_candidate(hay, rt, hay_transform_used(hay, rt));
            if mmap_explicit { bytes_searched=nul as u64; }
        }
    } else { data=original_data; analysis=original_analysis; if eff==EffBinary::Convert { if let Some(nul)=first_nul { if is_mmap_candidate(hay, rt, hay_transform_used(hay, rt)) { bytes_searched=nul as u64; } } } }
    finish_count(hay, rt, data, analysis, bytes_searched, transform_failed, out);
}
fn finish_count(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, bytes_searched: u64, transform_failed: bool, out: &mut PerFileOutput) {
    let reported=compute_reported_with_after(analysis, rt, Some(0));
    let is_match=reported.reported_lines.iter().any(|&x| x);
    out.is_match=is_match;
    out.bytes_searched=bytes_searched;
    out.stat_matches=if rt.args.invert{0}else{reported.units_for_count_matches as u64};
    out.stat_matched_lines=reported.reported_lines.iter().filter(|&&x| x).count() as u64;
    out.bytes_printed_stat=0;
    // count value
    let mode_is_count_matches = matches!(rt.args.mode, crate::flags::Mode::Search(PrinterMode::CountMatches)) || (matches!(rt.args.mode, crate::flags::Mode::Search(PrinterMode::Count)) && rt.args.only_matching);
    let count_val: u64 = if mode_is_count_matches {
