}
fn process_files_with(hay: &Haystack, rt: &Runtime, original_data: &[u8], original_analysis: &Analysis, first_nul: Option<usize>, eff: EffBinary, transform_failed: bool, out: &mut PerFileOutput) {
    // similar to count for determining match
    let (data_vec, analysis_holder); let data: &[u8]; let analysis: &Analysis;
    let mut bytes_searched=original_data.len() as u64;
    let mut quit_blocked=false;
    if eff==EffBinary::Quit {
