}
fn finish_files_with(hay: &Haystack, rt: &Runtime, data: &[u8], analysis: &Analysis, bytes_searched: u64, transform_failed: bool, out: &mut PerFileOutput, quit_blocked: bool) {
    let _=data;
    let reported=compute_reported_with_after(analysis, rt, Some(0));
    let is_match=reported.reported_lines.iter().any(|&x| x);
    out.is_match=is_match; out.bytes_searched=bytes_searched;
    out.stat_matches=if rt.args.invert{0}else{reported.units_for_count_matches as u64};
    out.stat_matched_lines=reported.reported_lines.iter().filter(|&&x| x).count() as u64;
    out.bytes_printed_stat=0;
    let is_without = matches!(rt.args.mode, crate::flags::Mode::Search(PrinterMode::FilesWithoutMatch));
    if transform_failed && !matches!(rt.args.mode, crate::flags::Mode::Search(PrinterMode::FilesWithMatches)) {
        // count/files-without drop output on transform error; files-with prints path despite (handled below since mode is files-with)
        if is_without { out.files_without_contributed=false; return; }
    }
    if transform_failed && is_without { out.files_without_contributed=false; return; }
    if !is_without {
        if is_match {
            out.stdout_bytes = path_line_bytes(hay, rt);
        }
    } else {
        if !is_match {
            if quit_blocked && eff_is_quit_for_file(hay, rt) {
                out.quit_binary_blocked=true; out.files_without_contributed=true;
            } else {
                out.stdout_bytes = path_line_bytes(hay, rt); out.files_without_contributed=true;
            }
        } else { out.files_without_contributed=false; }
    }
}
fn eff_is_quit_for_file(hay: &Haystack, rt: &Runtime) -> bool {
    matches!(effective_binary_mode(hay, rt), EffBinary::Quit)
}
fn path_line_bytes(hay: &Haystack, rt: &Runtime) -> Vec<u8> {
    let mut out=Vec::new();
    // hyperlink or colored path
    let mut fields=Vec::new(); let mut pb=Vec::new(); rt.render_path_raw(hay, &mut pb); fields.push((pb,0u8));
    // Use a special handling: write_prefix_fields adds a trailing separator, which we don't want for a lone path line.
    // Instead manually render:
    out.clear();
