    }
    out.extend_from_slice(&pb);
    out.extend_from_slice(&path_line_terminator(rt));
    out
}
fn path_line_terminator(rt: &Runtime) -> Vec<u8> {
    if rt.args.null { vec![0] } else { vec![b'\n'] }
}

