// ---------------- JSON / count / files processors ----------------

pub fn json_data_obj(bytes: &[u8]) -> String {
    match std::str::from_utf8(bytes) {
        Ok(s) => format!("{{\"text\":{}}}", json_escape_str(s)),
        Err(_) => format!("{{\"bytes\":\"{}\"}}", base64_encode(bytes)),
    }
}
pub fn json_escape_str(s: &str) -> String {
    let mut out=String::from("\"");
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"'); out
}
pub fn base64_encode(data: &[u8]) -> String {
    const TABLE: &[u8;64]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out=String::new();
    let mut i=0; while i<data.len() { let b0=data[i]; let b1=if i+1<data.len(){data[i+1]}else{0}; let b2=if i+2<data.len(){data[i+2]}else{0}; out.push(TABLE[(b0>>2) as usize] as char); out.push(TABLE[(((b0&0x03)<<4)|(b1>>4)) as usize] as char); out.push(if i+1<data.len(){ TABLE[(((b1&0x0f)<<2)|(b2>>6)) as usize] as char } else {'='}); out.push(if i+2<data.len(){ TABLE[(b2&0x3f) as usize] as char } else {'='}); i+=3; }
    out
}
pub fn json_duration_obj(d: Duration) -> String {
    let secs=d.as_secs(); let nanos=d.subsec_nanos();
    format!("{{\"secs\":{},\"nanos\":{},\"human\":\"{}\"}}", secs, nanos, human_duration(d))
}
pub fn json_duration_obj_summary(d: Duration) -> String {
    let secs=d.as_secs(); let nanos=d.subsec_nanos();
    // summary ordering human,nanos,secs
    format!("{{\"human\":\"{}\",\"nanos\":{},\"secs\":{}}}", human_duration(d), nanos_total_for_summary(d), secs)
}
fn nanos_total_for_summary(d: Duration) -> u64 {
    // In summary, elapsed object appears to use same struct but serialized in different order; the nanos field there is total? Check examples: summary elapsed nanos equals per-file nanos (subsec) when <1 sec. total elapsed_total nanos is total nanos.
    // For per-file stats aggregated, nanos field = subsec nanos of aggregated duration.
    d.subsec_nanos() as u64
}
pub fn human_duration(d: Duration) -> String {
    format!("{:.6}s", d.as_secs_f64())
}

fn process_json(hay: &Haystack, rt: &Runtime, original_data: &[u8], original_analysis: &Analysis, first_nul: Option<usize>, eff: EffBinary, transform_failed: bool, out: &mut PerFileOutput) {
    let json_start = Instant::now();
    // choose data/analysis
    let (data_vec, analysis_holder);
    let data: &[u8]; let analysis: &Analysis;
    let mut binary_offset_for_json: Option<usize> = None;
    let mut bytes_searched_json: u64 = original_data.len() as u64;
    if eff==EffBinary::Quit {
        if let Some(nul)=first_nul {
            let chunks=chunk_boundaries(original_data, &original_analysis.lines);
