            write_prefix_fields(hay, rt, fields, b":", 1, None, &mut b);
            // write_prefix_fields adds trailing sep, so we should not add another
            // It appended sep, remove? Actually for count format, prefix function leaves sep at end, good.
            b.extend_from_slice(count_val.to_string().as_bytes());
        } else { b.extend_from_slice(count_val.to_string().as_bytes()); }
