    let rt = search::Runtime { args: &args, engine: &engine, styles, colors_enabled, heading_effective, show_filename, show_line_number, hostname, hyperlink_active, started_at: program_start };
    return process_search_mode(&args, &rt, segments, walk_had_error, implicit_search, &mut stdin_src, program_start);
