fn handle_special(special: &Special) -> i32 {
    match special {
        Special::HelpLong => write_stdout_simple(include_bytes!("../assets/help_long.txt")),
        Special::HelpShort => write_stdout_simple(include_bytes!("../assets/help_short.txt")),
