        Special::VersionShort => write_stdout_simple(b"ripgrep 14.1.1 (rev 41bff5fc54)\n"),
        Special::Pcre2Version => {
            let rc = write_stdout_simple(b"PCRE2 is not available in this build of ripgrep.\n");
            if rc==0 {1} else {rc}
        }
    }
}
fn write_stdout_simple(data: &[u8]) -> i32 {
    let stdout=io::stdout(); let mut handle=stdout.lock();
    match handle.write_all(data) { Ok(_)=>{ let _=handle.flush(); 0 }, Err(e)=>{ if e.kind()==io::ErrorKind::BrokenPipe {1} else {2} } }
}

fn validate_types_filters_preglob(args: &Args) -> Result<(), i32> {
    let types = match walker::build_types(args) { Ok(t)=>t, Err(m)=>{ eprint_str(&m); return Err(2); } };
    if let Err(m)=walker::build_filters(args, &types) { eprint_str(&m); return Err(2); }
    if let Err(m)=validate_pre_globs(args) { eprint_str(&m); return Err(2); }
    Ok(())
}
fn validate_pre_globs(args: &Args) -> Result<(), String> {
    for pat in &args.pre_globs {
        let stripped = pat.strip_prefix('!').unwrap_or(pat);
        if let Err(e)=glob::build_gitignore_glob(stripped, false) {
            return Err(format!("rg: error parsing glob '{}': {}\n", pat, e.0));
        }
        // also validate original with !? build_gitignore on stripped covers inner errors; error message uses original above.
    }
    Ok(())
}
fn collect_patterns_from_bytes(bytes: Vec<u8>, display: &str) -> Result<Vec<String>, String> {
    let mut out=Vec::new();
    // split lines retaining line numbers: lines separated by \n; if bytes empty => no lines.
    // Use Rust lines semantics: strip trailing \n and \r
    let mut start=0usize; let mut line_no=1usize;
    let mut idx=0usize;
    // We'll iterate with manual splitting to know lines when trailing newline doesn't create extra line.
    let mut lines_raw: Vec<&[u8]> = Vec::new();
    while idx<bytes.len() {
        if bytes[idx]==b'\n' { lines_raw.push(&bytes[start..idx]); start=idx+1; }
        idx+=1;
    }
    if start<bytes.len() { lines_raw.push(&bytes[start..]); }
    // if bytes ends with \n, no extra
    for raw in lines_raw {
        let mut line_bytes = raw;
        if line_bytes.ends_with(b"\r") { line_bytes=&line_bytes[..line_bytes.len()-1]; }
        match std::str::from_utf8(line_bytes) {
            Ok(s)=> out.push(s.to_string()),
            Err(e)=>{
                let pos=e.utf8_error().valid_up_to();
                let err_len=e.utf8_error().error_len();
                let end = match err_len { Some(l)=> (pos+l).min(line_bytes.len()), None=>line_bytes.len() };
                let bad=&line_bytes[pos..end];
                let esc: String = bad.iter().map(|b| format!("\\x{:02X}", b)).collect();
                return Err(format!("rg: {}:{}: found invalid UTF-8 in pattern at byte offset {}: {} (disable Unicode mode and use hex escape sequences to match arbitrary bytes in a pattern, e.g., '(?-u)\\xFF')\n", display, line_no, pos, esc));
            }
        }
        line_no+=1;
    }
    Ok(out)
}
fn read_pattern_file(path: &Path) -> Result<Vec<String>, String> {
    // open
    let file = match std::fs::File::open(path) { Ok(f)=>f, Err(e)=> return Err(format!("rg: {}: {}\n", path.to_string_lossy(), e)) };
    let mut reader = io::BufReader::new(file);
    let mut bytes=Vec::new();
    match reader.read_to_end(&mut bytes) {
        Ok(_)=>{},
        Err(e)=> return Err(format!("rg: {}:{}\n", path.to_string_lossy(), e)),
    }
    collect_patterns_from_bytes(bytes, &path.to_string_lossy())
}

fn build_engine_or_empty(args: &Args, patterns: &[String]) -> Result<search::Engine, String> {
    if patterns.is_empty() {
        // build a never-matching engine
        let never = vec!["[^\\u{0}-\\u{10FFFF}]".to_string()];
        // Need a copy of args without fixed etc? Use search build with a cloned patterns list but boundary etc would wrap - we want the never pattern as is.
        // Temporarily use build_engine with a pattern that never matches: we pass it as a raw pattern (not fixed?). If args.fixed is true, escape would break it.
        // So create a direct Engine via search helper: we call search::build_engine with patterns=never but need fixed=false.
        // Since build_engine reads args.fixed, we cannot easily override. Instead construct Regex here via a helper in search: add a function? For now, if fixed, the never pattern escapes - still will be built from transformed patterns below?
        // We'll handle by calling search::build_engine with never and if fixed, it will escape the brackets and match literally - not good.
        // Workaround: use patterns containing a byte impossible? Empty line pattern is handled earlier? Patterns empty only occurs if pattern file empty.
        // Use engine built from a pattern that matches a NUL followed by something impossible in a line? Lines may contain NUL in binary text mode.
        // Choose pattern using regex crate directly:
        return search::build_never_engine(args);
    }
    match search::build_engine(args, patterns) {
        Ok(e)=>Ok(e),
        Err(s)=>{
            if let Some(limit)=args.regex_size_limit {
                if s.to_lowercase().contains("size limit") || s.to_lowercase().contains("compiled") {
                    return Err(format!("compiled regex exceeds size limit of {}", limit));
                }
            }
            Err(s)
        }
    }
}
fn format_composite_auto_error(default_err: &str) -> String {
    format!("rg: regex could not be compiled with either the default regex engine or with PCRE2.\n\ndefault regex engine error:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n{}\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nPCRE2 regex engine error:\nPCRE2 is not available in this build of ripgrep\n", default_err.trim_end())
}

fn compute_is_one_file(specs: &[impl std::fmt::Debug]) -> bool { false } // placeholder replaced below

fn compute_colors_enabled(args: &Args, is_tty: bool) -> bool {
    if matches!(args.mode, Mode::Search(PrinterMode::Json)) { return false; }
    match args.color_when.as_str() {
        "never"=>false,
        "always"|"ansi"=>true,
        _=> {
            if std::env::var_os("NO_COLOR").is_some() { return false; }
            if let Some(term)=std::env::var_os("TERM") { if term=="dumb" { return false; } } else { return false; }
            // TERM unset also disables in tty as observed
            is_tty
        }
    }
}

fn emit_debug_initial(args: &Args, config_path: &Option<String>, config_loaded: bool, paths_given: usize, path_specs: &[impl std::fmt::Debug], is_search: bool, patterns: &[String]) {
    // Partial emulation
    if config_loaded {
        if let Some(p)=config_path {
            let cfg_args_debug = ""; // config args list would be shown by original; we don't have them here (message format uses loaded args)
            let _=cfg_args_debug;
            eprint_str(&format!("rg: DEBUG|rg::flags::config|crates/core/flags/config.rs:41: {}: arguments loaded from config file\n", p));
        }
    } else {
        eprint_str("rg: DEBUG|rg::flags::parse|crates/core/flags/parse.rs:97: no extra arguments found from configuration file\n");
    }
    eprint_str(&format!("rg: DEBUG|rg::flags::hiargs|crates/core/flags/hiargs.rs:1083: number of paths given to search: {}\n", paths_given));
    // is_one_file debug only when 1 path given
    if paths_given==1 {
        // approximate
        eprint_str("rg: DEBUG|rg::flags::hiargs|crates/core/flags/hiargs.rs:1094: is_one_file? false\n");
    }
    let _=(path_specs, is_search, patterns);
    eprint_str(&format!("rg: DEBUG|rg::flags::hiargs|crates/core/flags/hiargs.rs:1269: found hostname for hyperlink configuration: {}\n", search::get_hostname(args)));
    eprint_str(&format!("rg: DEBUG|rg::flags::hiargs|crates/core/flags/hiargs.rs:1279: hyperlink format: \"{}\"\n", args.hyperlink_format));
    let threads = if args.threads>0 { args.threads } else { 1 };
    eprint_str(&format!("rg: DEBUG|rg::flags::hiargs|crates/core/flags/hiargs.rs:174: using {} thread(s)\n", threads));
}

fn process_files_mode(args: &Args, segments: Vec<Segment>, walk_had_error: bool, _start: Instant) -> i32 {
    let stdout=io::stdout(); let mut writer=io::BufWriter::new(stdout.lock());
    let mut any=false; let mut broken=false;
    // need runtime-like for path_line rendering: construct a minimal runtime? path_line_bytes expects search Runtime with engine etc. For files mode, we can render manually.
    let is_tty=io::stdout().is_terminal();
    let colors_enabled=compute_colors_enabled(args, is_tty);
    let styles=search::resolve_styles(args);
    let hyperlink_active=!args.hyperlink_format.is_empty() && colors_enabled;
    let hostname=if hyperlink_active { search::get_hostname(args) } else { String::new() };
    // segments may need sorting if requested
    let segments_sorted = apply_sort_to_segments(args, segments);
    for seg in &segments_sorted {
        for hay in &seg.haystacks {
            any=true;
            if args.quiet { continue; }
            let mut line=Vec::new();
            if hay.is_stdin { line.extend_from_slice(b"<stdin>"); } else {
                // render path with color/hyperlink
                let disp = hay.display.clone();
                let disp_bytes = {
                    #[cfg(unix)] { disp.as_os_str().as_bytes().to_vec() } #[cfg(not(unix))] { disp.to_string_lossy().as_bytes().to_vec() }
                };
                let mut disp_bytes2=disp_bytes.clone();
                if let Some(sep)=args.path_separator { for b in disp_bytes2.iter_mut(){ if *b==b'/' {*b=sep;} } }
                if hyperlink_active && !hay.is_stdin {
                    let url=search::hyperlink_url(&args.hyperlink_format, args, &hostname, &disp, None, None);
                    if let Some(u)=url { line.extend_from_slice(format!("\x1b]8;;{}\x1b\\", u).as_bytes()); styles.path.render(&disp_bytes2, colors_enabled, &mut line); line.extend_from_slice(b"\x1b]8;;\x1b\\"); } else { styles.path.render(&disp_bytes2, colors_enabled, &mut line); }
                } else { styles.path.render(&disp_bytes2, colors_enabled, &mut line); }
            }
            line.extend_from_slice(if args.null { &[0u8] as &[u8] } else { b"\n" });
            if let Err(e)=writer.write_all(&line) { if e.kind()==io::ErrorKind::BrokenPipe { broken=true; } break; }
        }
        if broken { break; }
    }
    let _=writer.flush();
    if broken { return 1; }
    if walk_had_error { if args.quiet && any { return 0; } return 2; }
    if any {0} else {1}
}

fn apply_sort_to_segments(args: &Args, mut segments: Vec<Segment>) -> Vec<Segment> {
    if let Some((kind, reverse))=&args.sort {
        if kind=="none" { return segments; }
        for seg in segments.iter_mut() {
            match kind.as_str() {
                "path" => { seg.haystacks.sort_by(|a,b| { let ord=a.display.cmp(&b.display); if *reverse {ord.reverse()} else {ord} }); }
                "modified"|"accessed"|"created" => {
                    seg.haystacks.sort_by(|a,b| {
                        let ta=hay_time(a, kind); let tb=hay_time(b, kind); let ord=ta.cmp(&tb); if *reverse {ord.reverse()} else {ord}
                    });
                }
                _=>{}
            }
        }
    }
    segments
}
fn hay_time(hay: &Haystack, kind: &str) -> std::time::SystemTime {
    let path = match &hay.fs_path { Some(p)=>p.clone(), None=>hay.display.clone() };
    let md = std::fs::metadata(&path).or_else(|_| std::fs::symlink_metadata(&path));
    if let Ok(m)=md {
        match kind { "modified"=>m.modified().unwrap_or(std::time::UNIX_EPOCH), "accessed"=>m.accessed().unwrap_or(std::time::UNIX_EPOCH), "created"=>m.created().unwrap_or(std::time::UNIX_EPOCH), _=>std::time::UNIX_EPOCH }
    } else { std::time::UNIX_EPOCH }
}

fn process_search_mode(args: &Args, rt: &search::Runtime, segments_in: Vec<Segment>, walk_had_error: bool, implicit_search: bool, stdin_src: &mut search::StdinSource, program_start: Instant) -> i32 {
    let segments = apply_sort_to_segments(args, segments_in);
    let stdout=io::stdout(); let mut writer=io::BufWriter::new(stdout.lock());
    let mut had_error=walk_had_error;
    let mut broken_pipe=false;
    let mut overall_match=false;
    let mut files_without_success=false;
    let mut attempted: usize=0;
    // plain stats
    let mut stat_matches: u64=0; let mut stat_matched_lines: u64=0; let mut stat_files_with: u64=0; let mut stat_files_searched: u64=0; let mut stat_bytes_searched: u64=0; let mut stat_bytes_printed: u64=0; let mut stat_search_elapsed=Duration::from_secs(0);
    // json stats
    let mut json_searches: u64=0; let mut json_matches: u64=0; let mut json_matched_lines: u64=0; let mut json_bytes_searched: u64=0; let mut json_bytes_printed: u64=0; let mut json_elapsed=Duration::from_secs(0);
    let is_json = matches!(args.mode, Mode::Search(PrinterMode::Json));
    let is_files_without = matches!(args.mode, Mode::Search(PrinterMode::FilesWithoutMatch));
    let mut printed_blocks: usize=0;
    'outer: for seg in &segments {
        for hay in &seg.haystacks {
            attempted+=1;
            let per = search::process_file(hay, rt, stdin_src);
            if per.had_error { had_error=true; }
            // overall
            if is_files_without { if per.files_without_contributed { files_without_success=true; } } else { if per.is_match { overall_match=true; } }
            // stats plain
            if per.searched || !is_json {
                // For plain stats, searched files are those with searched=true (process_file sets true initially except errors/transform)
                // json mode's searched flag is contributor flag, don't use for plain
                if !is_json {
                    if per.searched { stat_files_searched+=1; }
                    if per.is_match { stat_files_with+=1; }
                    stat_matches+=per.stat_matches; stat_matched_lines+=per.stat_matched_lines; stat_bytes_searched+=per.bytes_searched; stat_bytes_printed+=per.bytes_printed_stat; stat_search_elapsed+=per.elapsed;
                }
            }
            if is_json {
                if per.searched { // contributor (end emitted)
                    json_searches+=1; json_matches+=per.stat_matches; json_matched_lines+=per.stat_matched_lines; json_bytes_searched+=per.bytes_searched; json_bytes_printed+= if args.quiet {0} else {per.json_begin_match_bytes as u64}; json_elapsed+=per.elapsed;
                }
            }
            // output
            if args.quiet && !is_json {
                // suppress per-file outputs (stats/json summary later)
                continue;
            }
            if is_json && args.quiet {
                continue;
            }
            let block = if is_json { per.lines_for_json.clone() } else { per.stdout_bytes.clone() };
            if block.is_empty() { continue; }
            // heading separator
            if !is_json && rt.heading_effective && !matches!(args.mode, Mode::Search(PrinterMode::Count)|Mode::Search(PrinterMode::CountMatches)|Mode::Search(PrinterMode::FilesWithMatches)|Mode::Search(PrinterMode::FilesWithoutMatch)) && args.vimgrep==false {
                if printed_blocks>0 {
                    if let Err(e)=writer.write_all(b"\n") { if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else { had_error=true; } break 'outer; }
                }
            }
            if let Err(e)=writer.write_all(&block) {
                if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else {
                    if !args.no_messages { eprint_str(&format!("rg: {}: {}\n", hay.display.to_string_lossy(), e)); }
                    had_error=true;
                }
                break 'outer;
            }
            printed_blocks+=1;
        }
    }
    // json summary
    if is_json && !broken_pipe {
        let total_elapsed=program_start.elapsed();
        let summary = format!("{{\"data\":{{\"elapsed_total\":{},\"stats\":{{\"bytes_printed\":{},\"bytes_searched\":{},\"elapsed\":{},\"matched_lines\":{},\"matches\":{},\"searches\":{},\"searches_with_match\":{}}}}},\"type\":\"summary\"}}\n",
            search::json_duration_obj_summary(total_elapsed), json_bytes_printed, json_bytes_searched, search::json_duration_obj_summary(json_elapsed), json_matched_lines, json_matches, json_searches, json_searches);
        if let Err(e)=writer.write_all(summary.as_bytes()) { if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else { had_error=true; } }
    }
    // plain stats
    if args.stats && !is_json && !broken_pipe {
        let total_elapsed=program_start.elapsed();
        let stats_str=format!("\n{} matches\n{} matched lines\n{} files contained matches\n{} files searched\n{} bytes printed\n{} bytes searched\n{:.6} seconds spent searching\n{:.6} seconds\n", stat_matches, stat_matched_lines, stat_files_with, stat_files_searched, stat_bytes_printed, stat_bytes_searched, stat_search_elapsed.as_secs_f64(), total_elapsed.as_secs_f64());
        if let Err(e)=writer.write_all(stats_str.as_bytes()) { if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else { had_error=true; } }
    }
    let _=writer.flush();
    if broken_pipe { return 1; }
    // no files searched error
    let mut no_files_error=false;
    if implicit_search && attempted==0 {
        no_files_error=true;
        if !args.no_messages { eprint_str("rg: No files were searched, which means ripgrep probably applied a filter you didn't expect.\nRunning with --debug will show why files are being skipped.\n"); }
    }
    if had_error || no_files_error {
        // quiet + matched success overrides error
        let success = if is_files_without { files_without_success } else { overall_match };
        if args.quiet && success { return 0; }
        return 2;
    }
    let success = if is_files_without { files_without_success } else { overall_match };
    if success {0} else {1}
}
RS
"}

actions.command:
cat > src/main.rs <<'RS'
mod flags; mod glob; mod encoding; mod filetypes; mod walker; mod search;

use std::io::{self, Write, Read, IsTerminal};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::time::{Instant, Duration};
use std::ffi::OsString;
#[cfg(unix)] use std::os::unix::ffi::OsStrExt;
#[cfg(unix)] use std::os::unix::fs::{FileTypeExt, MetadataExt};

use flags::{Args, Mode, PrinterMode, Special, PatternSource, Engine as FlagEngine};
use walker::{Haystack, Segment};

fn main() -> ExitCode {
    let code = real_main();
    ExitCode::from(code as u8)
}

fn eprint_str(s: &str) { let _ = io::stderr().write_all(s.as_bytes()); }

fn stdin_info() -> Option<std::fs::Metadata> {
    std::fs::metadata("/proc/self/fd/0").ok()
}
fn stdin_is_readable() -> bool {
    if io::stdin().is_terminal() { return false; }
    let md = match stdin_info() { Some(m)=>m, None=>return false };
    if md.is_dir() { return false; }
    if let Ok(null_md)=std::fs::metadata("/dev/null") {
        #[cfg(unix)] { if md.dev()==null_md.dev() && md.ino()==null_md.ino() { return false; } }
    }
    true
}

fn read_config_args() -> (Vec<OsString>, Option<String>, bool) {
    // returns config args, loaded path debug string, whether config was loaded
    let raw_cli: Vec<OsString> = std::env::args_os().skip(1).collect();
    let has_no_config = raw_cli.iter().any(|a| a.to_string_lossy()=="--no-config");
    if has_no_config { return (Vec::new(), None, false); }
    let path_os = match std::env::var_os("RIPGREP_CONFIG_PATH") { Some(v)=>{ if v.is_empty(){ return (Vec::new(), None, false); } v }, None=>return (Vec::new(), None, false) };
    let path = PathBuf::from(path_os.clone());
    match std::fs::read(&path) {
        Ok(content) => {
            let text = String::from_utf8_lossy(&content);
            let mut out=Vec::new();
            for line in text.lines() {
                let t=line.trim();
                if t.is_empty() || t.starts_with('#') { continue; }
                out.push(OsString::from(t));
            }
            (out, Some(path.to_string_lossy().to_string()), true)
        }
        Err(e) => {
            eprint_str(&format!("rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {}: {}\n", path.to_string_lossy(), e));
            (Vec::new(), None, false)
        }
    }
}

fn real_main() -> i32 {
    let program_start = Instant::now();
    let (config_args, config_path, config_loaded) = read_config_args();
    let mut argv: Vec<OsString> = Vec::new();
    argv.extend(config_args.iter().cloned());
    argv.extend(std::env::args_os().skip(1));
    let args = match flags::parse_args(argv) {
        Ok(a)=>a,
        Err(e)=>{ eprint_str(&e.0); return 2; }
    };
    // Special modes
    if let Some(special)=&args.special {
        return handle_special(special);
    }
    // Debug initial lines (partial)
    // We'll emit them later after paths/mode determination in search/files paths, because number-of-paths etc.
    match &args.mode {
        Mode::Types => {
            // types + filters validation
            if let Err(code)=validate_types_filters_preglob(&args) { return code; }
            let types = match walker::build_types(&args) { Ok(t)=>t, Err(m)=>{ eprint_str(&m); return 2; } };
            let out = types.display();
            return write_stdout_simple(out.as_bytes());
        }
        Mode::Generate(kind) => {
            if let Err(code)=validate_types_filters_preglob(&args) { return code; }
            let data: &[u8] = match kind.as_str() {
                "man"=>include_bytes!("../assets/generate_man.txt"),
                "complete-bash"=>include_bytes!("../assets/generate_complete_bash.txt"),
                "complete-zsh"=>include_bytes!("../assets/generate_complete_zsh.txt"),
                "complete-fish"=>include_bytes!("../assets/generate_complete_fish.txt"),
                "complete-powershell"=>include_bytes!("../assets/generate_complete_powershell.txt"),
                _=>b"",
            };
            return write_stdout_simple(data);
        }
        _=>{}
    }
    // Search or Files
    let is_search = matches!(args.mode, Mode::Search(_));
    let mut stdin_src = search::StdinSource::new();
    // Pattern collection for search
    let mut patterns: Vec<String> = Vec::new();
    let mut search_paths_positional: Vec<PathBuf> = Vec::new();
    let mut has_stdin_pattern=false;
    if is_search {
        // Collect
        if args.has_pattern_flags {
            for src in &args.pattern_sources {
                match src {
                    PatternSource::Regexp(p)=> patterns.push(p.clone()),
                    PatternSource::File(path)=> {
                        if path.as_os_str()==std::ffi::OsStr::new("-") {
                            has_stdin_pattern=true;
                            // read stdin bytes
                            let bytes = match stdin_src.read_patterns() { Ok(b)=>b, Err(_)=>Vec::new() };
                            // split lines
                            match collect_patterns_from_bytes(bytes, "<stdin>") { Ok(mut ps)=>patterns.append(&mut ps), Err(msg)=>{ eprint_str(&msg); return 2; } }
                        } else {
                            match read_pattern_file(path) { Ok(mut ps)=>patterns.append(&mut ps), Err(msg)=>{ eprint_str(&msg); return 2; } }
                        }
                    }
                }
            }
            search_paths_positional = args.positionals.clone();
        } else {
            if args.positionals.is_empty() {
                eprint_str("rg: ripgrep requires at least one pattern to execute a search\n");
                return 2;
            }
            let pat_path=&args.positionals[0];
            let pat_str = match pat_path.to_str() { Some(s)=>s.to_string(), None=>{ eprint_str("rg: pattern given is not valid UTF-8\n"); return 2; } };
            patterns.push(pat_str);
            search_paths_positional = args.positionals[1..].to_vec();
        }
        // stdin pattern conflict with explicit stdin search
        if has_stdin_pattern && search_paths_positional.iter().any(|p| p.as_os_str()==std::ffi::OsStr::new("-")) {
            eprint_str("rg: error: attempted to read patterns from stdin while also searching stdin\n"); return 2;
        }
    } else {
        search_paths_positional = args.positionals.clone();
    }
    // Types / filters / preglob validation (after patterns as per observed ordering for search; for files, patterns not read)
    let types = match walker::build_types(&args) { Ok(t)=>t, Err(m)=>{ eprint_str(&m); return 2; } };
    let filters = match walker::build_filters(&args, &types) { Ok(f)=>f, Err(m)=>{ eprint_str(&m); return 2; } };
    if let Err(msg)=validate_pre_globs(&args) { eprint_str(&msg); return 2; }
    // Engine for search
    let engine_opt: Option<search::Engine>;
    if is_search {
        // engine handling
        if args.engine==FlagEngine::Pcre2 {
            eprint_str("rg: PCRE2 is not available in this build of ripgrep\n"); return 2;
        }
        // newline check + build
        let has_newline = patterns.iter().any(|p| search::pattern_contains_newline(p, args.fixed));
        if args.engine==FlagEngine::Auto {
            // try default (newline is a failure for auto)
            if has_newline && !args.multiline {
                let default_err = "the literal \"\\n\" is not allowed in a regex\n\nConsider enabling multiline mode with the --multiline flag (or -U for short).\nWhen multiline mode is enabled, new line characters can be matched.".to_string();
                eprint_str(&format_composite_auto_error(&default_err)); return 2;
            }
            match build_engine_or_empty(&args, &patterns) {
                Ok(e)=> engine_opt=Some(e),
                Err(err_str)=>{
                    eprint_str(&format_composite_auto_error(&err_str)); return 2;
                }
            }
        } else {
            if has_newline && !args.multiline {
                eprint_str("rg: the literal \"\\n\" is not allowed in a regex\n\nConsider enabling multiline mode with the --multiline flag (or -U for short).\nWhen multiline mode is enabled, new line characters can be matched.\n"); return 2;
            }
            match build_engine_or_empty(&args, &patterns) {
                Ok(e)=> engine_opt=Some(e),
                Err(err_str)=>{
                    // size limit special already in err_str?
                    eprint_str(&format!("rg: {}\n", err_str.trim_end())); return 2;
                }
            }
        }
    } else { engine_opt=None; }
    // Paths determination
    enum PathSpec { Stdin, Fs(PathBuf, bool) } // bool implicit
    let mut path_specs: Vec<PathSpec> = Vec::new();
    let mut implicit_search = false;
    if search_paths_positional.is_empty() {
        if is_search && !has_stdin_pattern && stdin_is_readable() {
            path_specs.push(PathSpec::Stdin);
        } else {
            path_specs.push(PathSpec::Fs(PathBuf::from("."), true));
            implicit_search = true;
        }
    } else {
        for p in &search_paths_positional {
            if is_search && p.as_os_str()==std::ffi::OsStr::new("-") { path_specs.push(PathSpec::Stdin); } else if !is_search && p.as_os_str()==std::ffi::OsStr::new("-") && matches!(args.mode, Mode::Files) {
                // --files - lists <stdin>
                path_specs.push(PathSpec::Stdin);
            } else { path_specs.push(PathSpec::Fs(p.clone(), false)); }
        }
    }
    let paths_given_count = if search_paths_positional.is_empty() {0} else {search_paths_positional.len()};
    // debug initial emission (partial emulation)
    if args.debug || args.trace {
        emit_debug_initial(&args, &config_path, config_loaded, paths_given_count, &path_specs, is_search, &patterns);
    }
    // Walk
    let mut walk_ctx = walker::WalkContext::new(&args, &filters);
    let mut segments: Vec<Segment> = Vec::new();
    let total_path_specs = path_specs.len();
    for spec in &path_specs {
        match spec {
            PathSpec::Stdin => {
                segments.push(Segment{haystacks: vec![Haystack{display: PathBuf::from("<stdin>"), fs_path: None, is_stdin:true, explicit_file:true}]});
            }
            PathSpec::Fs(path, implicit) => {
                if *implicit {
                    segments.push(walker::walk_root_with_display(&mut walk_ctx, path, total_path_specs, true));
                } else {
                    segments.push(walker::walk_root(&mut walk_ctx, path, total_path_specs));
                }
            }
        }
    }
    let walk_had_error = walk_ctx.had_error;
    // Files mode processing
    if matches!(args.mode, Mode::Files) {
        return process_files_mode(&args, segments, walk_had_error, program_start);
    }
    // Search mode runtime
    let engine = engine_opt.unwrap();
    // show filename decision
    let is_one_file = compute_is_one_file(&path_specs);
    let show_filename = match args.with_filename { Some(v)=>v, None=>!is_one_file };
    let is_tty = io::stdout().is_terminal();
    let colors_enabled = compute_colors_enabled(&args, is_tty);
    let heading_effective = args.heading.unwrap_or(is_tty);
    let show_line_number = match args.line_number { Some(v)=>v, None=> is_tty || args.column };
    let styles = search::resolve_styles(&args);
    let hyperlink_active = !args.hyperlink_format.is_empty() && colors_enabled;
    let hostname = if hyperlink_active { search::get_hostname(&args) } else { String::new() };
    let rt = search::Runtime { args: &args, engine: &engine, styles, colors_enabled, heading_effective, show_filename, show_line_number, hostname, hyperlink_active, started_at: program_start };
    return process_search_mode(&args, &rt, segments, walk_had_error, implicit_search, &mut stdin_src, program_start);
}

fn handle_special(special: &Special) -> i32 {
    match special {
        Special::HelpLong => write_stdout_simple(include_bytes!("../assets/help_long.txt")),
        Special::HelpShort => write_stdout_simple(include_bytes!("../assets/help_short.txt")),
        Special::VersionLong => write_stdout_simple(b"ripgrep 14.1.1 (rev 41bff5fc54)\n\nfeatures:-pcre2\nsimd(compile):+SSE2,-SSSE3,-AVX2\nsimd(runtime):+SSE2,+SSSE3,+AVX2\n\nPCRE2 is not available in this build of ripgrep.\n"),
        Special::VersionShort => write_stdout_simple(b"ripgrep 14.1.1 (rev 41bff5fc54)\n"),
        Special::Pcre2Version => {
            let rc = write_stdout_simple(b"PCRE2 is not available in this build of ripgrep.\n");
            if rc==0 {1} else {rc}
        }
    }
}
fn write_stdout_simple(data: &[u8]) -> i32 {
    let stdout=io::stdout(); let mut handle=stdout.lock();
    match handle.write_all(data) { Ok(_)=>{ let _=handle.flush(); 0 }, Err(e)=>{ if e.kind()==io::ErrorKind::BrokenPipe {1} else {2} } }
}

fn validate_types_filters_preglob(args: &Args) -> Result<(), i32> {
