fn collect_patterns_from_bytes(bytes: Vec<u8>, display: &str) -> Result<Vec<String>, String> {
    let mut out=Vec::new();
    // split lines retaining line numbers: lines separated by \n; if bytes empty => no lines.
    // Use Rust lines semantics: strip trailing \n and \r
    let mut start=0usize; let mut line_no=1usize;
    let mut idx=0usize;
    // We'll iterate with manual splitting to know lines when trailing newline doesn't create extra line.
    let mut lines_raw: Vec<&[u8]> = Vec::new();
    while idx<bytes.len() {
        if bytes[idx]==b'\n' { lines_raw.push(&bytes[start..idx]); start=idx+1; }
        idx+=1;
    }
    if start<bytes.len() { lines_raw.push(&bytes[start..]); }
    // if bytes ends with \n, no extra
    for raw in lines_raw {
        let mut line_bytes = raw;
        if line_bytes.ends_with(b"\r") { line_bytes=&line_bytes[..line_bytes.len()-1]; }
        match std::str::from_utf8(line_bytes) {
            Ok(s)=> out.push(s.to_string()),
            Err(e)=>{
                let pos=e.utf8_error().valid_up_to();
                let err_len=e.utf8_error().error_len();
                let end = match err_len { Some(l)=> (pos+l).min(line_bytes.len()), None=>line_bytes.len() };
                let bad=&line_bytes[pos..end];
                let esc: String = bad.iter().map(|b| format!("\\x{:02X}", b)).collect();
                return Err(format!("rg: {}:{}: found invalid UTF-8 in pattern at byte offset {}: {} (disable Unicode mode and use hex escape sequences to match arbitrary bytes in a pattern, e.g., '(?-u)\\xFF')\n", display, line_no, pos, esc));
            }
        }
        line_no+=1;
    }
    Ok(out)
}
fn read_pattern_file(path: &Path) -> Result<Vec<String>, String> {
    // open
    let file = match std::fs::File::open(path) { Ok(f)=>f, Err(e)=> return Err(format!("rg: {}: {}\n", path.to_string_lossy(), e)) };
    let mut reader = io::BufReader::new(file);
    let mut bytes=Vec::new();
    match reader.read_to_end(&mut bytes) {
        Ok(_)=>{},
        Err(e)=> return Err(format!("rg: {}:{}\n", path.to_string_lossy(), e)),
    }
    collect_patterns_from_bytes(bytes, &path.to_string_lossy())
}

