    }
    if had_error || no_files_error {
        // quiet + matched success overrides error
        let success = if is_files_without { files_without_success } else { overall_match };
        if args.quiet && success { return 0; }
        return 2;
    }
    let success = if is_files_without { files_without_success } else { overall_match };
    if success {0} else {1}
}
