fn validate_pre_globs(args: &Args) -> Result<(), String> {
    for pat in &args.pre_globs {
        let stripped = pat.strip_prefix('!').unwrap_or(pat);
        if let Err(e)=glob::build_gitignore_glob(stripped, false) {
            return Err(format!("rg: error parsing glob '{}': {}\n", pat, e.0));
        }
        // also validate original with !? build_gitignore on stripped covers inner errors; error message uses original above.
    }
    Ok(())
}
fn collect_patterns_from_bytes(bytes: Vec<u8>, display: &str) -> Result<Vec<String>, String> {
    let mut out=Vec::new();
    // split lines retaining line numbers: lines separated by \n; if bytes empty => no lines.
    // Use Rust lines semantics: strip trailing \n and \r
    let mut start=0usize; let mut line_no=1usize;
    let mut idx=0usize;
    // We'll iterate with manual splitting to know lines when trailing newline doesn't create extra line.
    let mut lines_raw: Vec<&[u8]> = Vec::new();
    while idx<bytes.len() {
        if bytes[idx]==b'\n' { lines_raw.push(&bytes[start..idx]); start=idx+1; }
        idx+=1;
    }
    if start<bytes.len() { lines_raw.push(&bytes[start..]); }
    // if bytes ends with \n, no extra
    for raw in lines_raw {
        let mut line_bytes = raw;
        if line_bytes.ends_with(b"\r") { line_bytes=&line_bytes[..line_bytes.len()-1]; }
        match std::str::from_utf8(line_bytes) {
            Ok(s)=> out.push(s.to_string()),
            Err(e)=>{
                let pos=e.utf8_error().valid_up_to();
                let err_len=e.utf8_error().error_len();
                let end = match err_len { Some(l)=> (pos+l).min(line_bytes.len()), None=>line_bytes.len() };
                let bad=&line_bytes[pos..end];
                let esc: String = bad.iter().map(|b| format!("\\x{:02X}", b)).collect();
                return Err(format!("rg: {}:{}: found invalid UTF-8 in pattern at byte offset {}: {} (disable Unicode mode and use hex escape sequences to match arbitrary bytes in a pattern, e.g., '(?-u)\\xFF')\n", display, line_no, pos, esc));
            }
        }
        line_no+=1;
    }
    Ok(out)
}
fn read_pattern_file(path: &Path) -> Result<Vec<String>, String> {
    // open
    let file = match std::fs::File::open(path) { Ok(f)=>f, Err(e)=> return Err(format!("rg: {}: {}\n", path.to_string_lossy(), e)) };
    let mut reader = io::BufReader::new(file);
    let mut bytes=Vec::new();
    match reader.read_to_end(&mut bytes) {
        Ok(_)=>{},
        Err(e)=> return Err(format!("rg: {}:{}\n", path.to_string_lossy(), e)),
    }
    collect_patterns_from_bytes(bytes, &path.to_string_lossy())
}

fn build_engine_or_empty(args: &Args, patterns: &[String]) -> Result<search::Engine, String> {
    if patterns.is_empty() {
        // build a never-matching engine
        let never = vec!["[^\\u{0}-\\u{10FFFF}]".to_string()];
        // Need a copy of args without fixed etc? Use search build with a cloned patterns list but boundary etc would wrap - we want the never pattern as is.
        // Temporarily use build_engine with a pattern that never matches: we pass it as a raw pattern (not fixed?). If args.fixed is true, escape would break it.
        // So create a direct Engine via search helper: we call search::build_engine with patterns=never but need fixed=false.
        // Since build_engine reads args.fixed, we cannot easily override. Instead construct Regex here via a helper in search: add a function? For now, if fixed, the never pattern escapes - still will be built from transformed patterns below?
        // We'll handle by calling search::build_engine with never and if fixed, it will escape the brackets and match literally - not good.
        // Workaround: use patterns containing a byte impossible? Empty line pattern is handled earlier? Patterns empty only occurs if pattern file empty.
        // Use engine built from a pattern that matches a NUL followed by something impossible in a line? Lines may contain NUL in binary text mode.
        // Choose pattern using regex crate directly:
        return search::build_never_engine(args);
    }
    match search::build_engine(args, patterns) {
        Ok(e)=>Ok(e),
        Err(s)=>{
            if let Some(limit)=args.regex_size_limit {
