fn process_files_mode(args: &Args, segments: Vec<Segment>, walk_had_error: bool, _start: Instant) -> i32 {
    let stdout=io::stdout(); let mut writer=io::BufWriter::new(stdout.lock());
    let mut any=false; let mut broken=false;
    // need runtime-like for path_line rendering: construct a minimal runtime? path_line_bytes expects search Runtime with engine etc. For files mode, we can render manually.
    let is_tty=io::stdout().is_terminal();
    let colors_enabled=compute_colors_enabled(args, is_tty);
    let styles=search::resolve_styles(args);
    let hyperlink_active=!args.hyperlink_format.is_empty() && colors_enabled;
    let hostname=if hyperlink_active { search::get_hostname(args) } else { String::new() };
    // segments may need sorting if requested
    let segments_sorted = apply_sort_to_segments(args, segments);
    for seg in &segments_sorted {
        for hay in &seg.haystacks {
            any=true;
            if args.quiet { continue; }
            let mut line=Vec::new();
            if hay.is_stdin { line.extend_from_slice(b"<stdin>"); } else {
                // render path with color/hyperlink
                let disp = hay.display.clone();
                let disp_bytes = {
                    #[cfg(unix)] { disp.as_os_str().as_bytes().to_vec() } #[cfg(not(unix))] { disp.to_string_lossy().as_bytes().to_vec() }
                };
                let mut disp_bytes2=disp_bytes.clone();
                if let Some(sep)=args.path_separator { for b in disp_bytes2.iter_mut(){ if *b==b'/' {*b=sep;} } }
                if hyperlink_active && !hay.is_stdin {
                    let url=search::hyperlink_url(&args.hyperlink_format, args, &hostname, &disp, None, None);
                    if let Some(u)=url { line.extend_from_slice(format!("\x1b]8;;{}\x1b\\", u).as_bytes()); styles.path.render(&disp_bytes2, colors_enabled, &mut line); line.extend_from_slice(b"\x1b]8;;\x1b\\"); } else { styles.path.render(&disp_bytes2, colors_enabled, &mut line); }
                } else { styles.path.render(&disp_bytes2, colors_enabled, &mut line); }
            }
            line.extend_from_slice(if args.null { &[0u8] as &[u8] } else { b"\n" });
            if let Err(e)=writer.write_all(&line) { if e.kind()==io::ErrorKind::BrokenPipe { broken=true; } break; }
        }
        if broken { break; }
    }
    let _=writer.flush();
    if broken { return 1; }
    if walk_had_error { if args.quiet && any { return 0; } return 2; }
    if any {0} else {1}
}

fn apply_sort_to_segments(args: &Args, mut segments: Vec<Segment>) -> Vec<Segment> {
    if let Some((kind, reverse))=&args.sort {
        if kind=="none" { return segments; }
        for seg in segments.iter_mut() {
            match kind.as_str() {
                "path" => { seg.haystacks.sort_by(|a,b| { let ord=a.display.cmp(&b.display); if *reverse {ord.reverse()} else {ord} }); }
                "modified"|"accessed"|"created" => {
                    seg.haystacks.sort_by(|a,b| {
                        let ta=hay_time(a, kind); let tb=hay_time(b, kind); let ord=ta.cmp(&tb); if *reverse {ord.reverse()} else {ord}
                    });
                }
                _=>{}
            }
        }
    }
    segments
}
fn hay_time(hay: &Haystack, kind: &str) -> std::time::SystemTime {
    let path = match &hay.fs_path { Some(p)=>p.clone(), None=>hay.display.clone() };
    let md = std::fs::metadata(&path).or_else(|_| std::fs::symlink_metadata(&path));
    if let Ok(m)=md {
        match kind { "modified"=>m.modified().unwrap_or(std::time::UNIX_EPOCH), "accessed"=>m.accessed().unwrap_or(std::time::UNIX_EPOCH), "created"=>m.created().unwrap_or(std::time::UNIX_EPOCH), _=>std::time::UNIX_EPOCH }
    } else { std::time::UNIX_EPOCH }
}

fn process_search_mode(args: &Args, rt: &search::Runtime, segments_in: Vec<Segment>, walk_had_error: bool, implicit_search: bool, stdin_src: &mut search::StdinSource, program_start: Instant) -> i32 {
    let segments = apply_sort_to_segments(args, segments_in);
    let stdout=io::stdout(); let mut writer=io::BufWriter::new(stdout.lock());
    let mut had_error=walk_had_error;
    let mut broken_pipe=false;
    let mut overall_match=false;
    let mut files_without_success=false;
    let mut attempted: usize=0;
    // plain stats
    let mut stat_matches: u64=0; let mut stat_matched_lines: u64=0; let mut stat_files_with: u64=0; let mut stat_files_searched: u64=0; let mut stat_bytes_searched: u64=0; let mut stat_bytes_printed: u64=0; let mut stat_search_elapsed=Duration::from_secs(0);
    // json stats
    let mut json_searches: u64=0; let mut json_matches: u64=0; let mut json_matched_lines: u64=0; let mut json_bytes_searched: u64=0; let mut json_bytes_printed: u64=0; let mut json_elapsed=Duration::from_secs(0);
    let is_json = matches!(args.mode, Mode::Search(PrinterMode::Json));
    let is_files_without = matches!(args.mode, Mode::Search(PrinterMode::FilesWithoutMatch));
    let mut printed_blocks: usize=0;
    'outer: for seg in &segments {
        for hay in &seg.haystacks {
            attempted+=1;
            let per = search::process_file(hay, rt, stdin_src);
            if per.had_error { had_error=true; }
            // overall
            if is_files_without { if per.files_without_contributed { files_without_success=true; } } else { if per.is_match { overall_match=true; } }
            // stats plain
            if per.searched || !is_json {
                // For plain stats, searched files are those with searched=true (process_file sets true initially except errors/transform)
                // json mode's searched flag is contributor flag, don't use for plain
                if !is_json {
                    if per.searched { stat_files_searched+=1; }
                    if per.is_match { stat_files_with+=1; }
                    stat_matches+=per.stat_matches; stat_matched_lines+=per.stat_matched_lines; stat_bytes_searched+=per.bytes_searched; stat_bytes_printed+=per.bytes_printed_stat; stat_search_elapsed+=per.elapsed;
                }
            }
            if is_json {
                if per.searched { // contributor (end emitted)
                    json_searches+=1; json_matches+=per.stat_matches; json_matched_lines+=per.stat_matched_lines; json_bytes_searched+=per.bytes_searched; json_bytes_printed+= if args.quiet {0} else {per.json_begin_match_bytes as u64}; json_elapsed+=per.elapsed;
                }
            }
            // output
            if args.quiet && !is_json {
                // suppress per-file outputs (stats/json summary later)
                continue;
            }
            if is_json && args.quiet {
                continue;
            }
            let block = if is_json { per.lines_for_json.clone() } else { per.stdout_bytes.clone() };
            if block.is_empty() { continue; }
            // heading separator
            if !is_json && rt.heading_effective && !matches!(args.mode, Mode::Search(PrinterMode::Count)|Mode::Search(PrinterMode::CountMatches)|Mode::Search(PrinterMode::FilesWithMatches)|Mode::Search(PrinterMode::FilesWithoutMatch)) && args.vimgrep==false {
                if printed_blocks>0 {
                    if let Err(e)=writer.write_all(b"\n") { if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else { had_error=true; } break 'outer; }
                }
            }
            if let Err(e)=writer.write_all(&block) {
                if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else {
                    if !args.no_messages { eprint_str(&format!("rg: {}: {}\n", hay.display.to_string_lossy(), e)); }
                    had_error=true;
                }
                break 'outer;
            }
            printed_blocks+=1;
        }
    }
    // json summary
    if is_json && !broken_pipe {
        let total_elapsed=program_start.elapsed();
        let summary = format!("{{\"data\":{{\"elapsed_total\":{},\"stats\":{{\"bytes_printed\":{},\"bytes_searched\":{},\"elapsed\":{},\"matched_lines\":{},\"matches\":{},\"searches\":{},\"searches_with_match\":{}}}}},\"type\":\"summary\"}}\n",
            search::json_duration_obj_summary(total_elapsed), json_bytes_printed, json_bytes_searched, search::json_duration_obj_summary(json_elapsed), json_matched_lines, json_matches, json_searches, json_searches);
        if let Err(e)=writer.write_all(summary.as_bytes()) { if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else { had_error=true; } }
    }
    // plain stats
    if args.stats && !is_json && !broken_pipe {
        let total_elapsed=program_start.elapsed();
        let stats_str=format!("\n{} matches\n{} matched lines\n{} files contained matches\n{} files searched\n{} bytes printed\n{} bytes searched\n{:.6} seconds spent searching\n{:.6} seconds\n", stat_matches, stat_matched_lines, stat_files_with, stat_files_searched, stat_bytes_printed, stat_bytes_searched, stat_search_elapsed.as_secs_f64(), total_elapsed.as_secs_f64());
        if let Err(e)=writer.write_all(stats_str.as_bytes()) { if e.kind()==io::ErrorKind::BrokenPipe { broken_pipe=true; } else { had_error=true; } }
    }
    let _=writer.flush();
    if broken_pipe { return 1; }
    // no files searched error
    let mut no_files_error=false;
    if implicit_search && attempted==0 {
        no_files_error=true;
        if !args.no_messages { eprint_str("rg: No files were searched, which means ripgrep probably applied a filter you didn't expect.\nRunning with --debug will show why files are being skipped.\n"); }
    }
    if had_error || no_files_error {
        // quiet + matched success overrides error
        let success = if is_files_without { files_without_success } else { overall_match };
        if args.quiet && success { return 0; }
        return 2;
    }
    let success = if is_files_without { files_without_success } else { overall_match };
    if success {0} else {1}
}
RS
