// Banned literal detection (line terminator / NUL byte) based on HIR-literal approximation.
fn literal_occurrences(pat: &str, fixed: bool) -> Vec<u8> {
    let mut occ = Vec::new();
    if fixed {
        for b in pat.bytes() { if matches!(b, 0|10|13) { occ.push(b); } }
        return occ;
    }
    let chars: Vec<char> = pat.chars().collect();
    let mut i=0usize;
    while i<chars.len() {
        let c=chars[i];
        if c=='[' {
            // parse class
            let mut j=i+1;
            let mut negated=false;
            if j<chars.len() && chars[j]=='^' { negated=true; j+=1; }
            let mut values: std::collections::HashSet<u32> = std::collections::HashSet::new();
            let mut multi=false;
            // If first char is ] it's literal
            let mut first=true;
            while j<chars.len() {
                if chars[j]==']' && !first { j+=1; break; }
                first=false;
                // posix class
                if chars[j]=='[' && j+1<chars.len() && chars[j+1]==':' {
                    if let Some(pos)=chars[j+2..].iter().position(|&ch| ch==':') {
                        // need closing :]
                        multi=true; j=j+2+pos+2; continue;
                    }
                }
                // decode one class item char
                let (mut val_opt, consumed): (Option<u32>, usize) = decode_escape_at(&chars, j);
                if val_opt.is_none() && j<chars.len() && !(chars[j]=='\\') {
                    val_opt=Some(chars[j] as u32); 
                }
                let cur_j=j;
                j += if consumed>0 {consumed} else {1};
                // range?
                if j<chars.len() && chars[j]=='-' && j+1<chars.len() && chars[j+1]!=']' {
                    let (end_val, cons2) = decode_escape_at(&chars, j+1);
                    let end_v = if end_val.is_some() {end_val} else {Some(chars[j+1] as u32)};
                    if let (Some(sv), Some(ev))=(val_opt, end_v) {
                        if ev>=sv && ev-sv<256 { for v in sv..=ev { values.insert(v); } if ev>sv { multi=true; } } else { multi=true; }
                    } else { multi=true; }
                    j+=1+ if cons2>0 {cons2} else {1};
                    continue;
                }
                let _=cur_j;
                if let Some(v)=val_opt {
                    // shorthands decoded as None by decode_escape_at for \d etc - those set multi in decoder? We detect: if escape was a shorthand, decoder returns (None,2). Mark multi.
                    values.insert(v);
                } else {
                    multi=true;
                }
            }
            if !negated && !multi && values.len()==1 {
                let v=*values.iter().next().unwrap();
                if v<256 && matches!(v, 0|10|13) { occ.push(v as u8); }
            }
            i=j; continue;
        }
        if c=='\\' {
            let (val, consumed) = decode_escape_at(&chars, i);
            if let Some(v)=val { if v<256 && matches!(v, 0|10|13) { occ.push(v as u8); } }
            i += if consumed>0 {consumed} else {2};
            continue;
        }
        if (c as u32)<256 && matches!(c as u32, 0|10|13) { occ.push(c as u8); }
        i+=1;
    }
    occ
}
fn decode_escape_at(chars: &[char], i: usize) -> (Option<u32>, usize) {
    if i>=chars.len() { return (None,0); }
    if chars[i]!='\\' {
        return (Some(chars[i] as u32), 1);
    }
    if i+1>=chars.len() { return (None,1); }
