{"command":"cat > /tmp/patch_config.py <<'PY'
import pathlib
p=pathlib.Path("src/main.rs"); t=p.read_text()
old_start=t.find("    let path = PathBuf::from(path_os.clone());")
old_end=t.find("fn real_main()")
segment=t[old_start:old_end]
new_segment='''    let path = PathBuf::from(path_os.clone());
    // Open then read: open errors include path, read errors do not (matching original).
    let mut file = match std::fs::File::open(&path) {
        Ok(f)=>f,
        Err(e)=>{
            eprint_str(&format!("rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {}: {}\\n", path.to_string_lossy(), e));
            return (Vec::new(), None, false);
        }
    };
    let mut content_bytes=Vec::new();
    match file.read_to_end(&mut content_bytes) {
        Ok(_)=>{
            let mut out=Vec::new();
            for raw_line in content_bytes.split(|b| *b==b'\\n') {
                let mut line = raw_line;
                if line.ends_with(b"\\r") { line=&line[..line.len()-1]; }
                // trim ASCII whitespace
                let mut start=0usize; let mut end=line.len();
                while start<end && matches!(line[start], b' '|b'\\t'|b'\\r'|0x0c) { start+=1; }
                while end>start && matches!(line[end-1], b' '|b'\\t'|b'\\r'|0x0c) { end-=1; }
                let trimmed=&line[start..end];
                if trimmed.is_empty() || trimmed.first()==Some(&b'#') { continue; }
                #[cfg(unix)] { use std::os::unix::ffi::OsStringExt; out.push(OsString::from_vec(trimmed.to_vec())); }
                #[cfg(not(unix))] { out.push(OsString::from(String::from_utf8_lossy(trimmed).to_string())); }
            }
            (out, Some(path.to_string_lossy().to_string()), true)
        }
        Err(e)=>{
            eprint_str(&format!("rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {}\\n", e));
            (Vec::new(), None, false)
        }
    }
}

'''
t=t[:old_start]+new_segment+t[old_end:]
p.write_text(t)
