    if let Some((kind, reverse))=&args.sort {
        if kind=="none" { return segments; }
        if kind=="path" && !*reverse {
            for seg in segments.iter_mut() {
                seg.haystacks.sort_by(|a,b| a.display.cmp(&b.display));
            }
            return segments;
        }
        // Global sorting for reverse path and time-based sorts
        let mut all: Vec<Haystack> = Vec::new();
        for seg in segments.into_iter() { all.extend(seg.haystacks); }
        match kind.as_str() {
            "path" => { all.sort_by(|a,b| b.display.cmp(&a.display)); }
            "modified"|"accessed"|"created" => {
                all.sort_by(|a,b| {
                    let ta=hay_time(a, kind); let tb=hay_time(b, kind);
                    let ord=ta.cmp(&tb); if *reverse {ord.reverse()} else {ord}
                });
            }
            _=>{}
        }
        return vec![Segment{haystacks: all}];
    }
    segments
}
